void parse_options(int argc, char* argv[]) {
    int opt = 0;
    while ((opt = getopt(argc, argv, "cs:o:vh")) != -1) {
        switch (opt) {
            case 'c':
                is_case_sensitive = true;
                break;
            case 's':
                output_file = optarg;
                break;
            case 'v':
                verbose = true;
                break;
            case 'h':
                usage();
                exit(0);
            default:
                cerr << "Invalid option" << endl;
                usage();
                exit(1);
        }
    }
}

long long total_lines = 0;
vector<string> lines;

void process_line(const string& line) {
    if (is_case_sensitive) {
        lines.push_back(line);
        total_lines++;
    } else {
        transform(line.begin(), line.end(), line.begin(), ::toupper);
        auto it = find(lines.begin(), lines.end(), line);
        if (it == lines.end()) {
            lines.push_back(line);
            total_lines++;
        }
    }
}

void read_file(const string& filename) {
    ifstream file(filename);
    string line;
    while (getline(file, line)) {
        process_line(line);
    }
}

void compute_stats() {
    long long total_chars = 0;
    double avg_line_length = 0.0;

    for (const auto& line : lines) {
        total_chars += line.size();
    }

    avg_line_length = static_cast<double>(total_chars) / total_lines;

    if (verbose) {
        cout << "Total characters: " << total_chars << endl;
        cout << "Average line length: " << avg_line_length << endl;
    }
}

int main(int argc, char* argv[]) {
    clock_t start = clock();
    parse_options(argc, argv);

    for (int i = optind; i < argc; ++i) {
        read_file(argv[i]);
    }

    compute_stats();

    if (!output_file.empty()) {
        ofstream output(output_file);
        for (const auto& line : lines) {
            output << line << endl;
        }
    } else {
        cout << lines.size() << " lines read" << endl;
    }

    clock_t end = clock();
    double time_taken = static_cast<double>(end - start) / CLOCKS_PER_SEC;

    LogEntry log_entry{to_string(time_taken), "INFO"};
    log_entry("Parsing took {0} seconds".format(time_taken));

    return 0;
}
