#include <algorithm>
#include <vector>

int updateAndModifyVector(std::vector<int>& vec, int targetValue, int& incrementAmount) {
    incrementAmount += 10;

    auto it = std::find(vec.begin(), vec.end(), targetValue);
    if (it != vec.end()) {
        *it = incrementAmount;
        return it - vec.begin();
    }

    vec.emplace_back(incrementAmount);
    return -1;
