function manageUserRequest() {
    $request = json_decode(file_get_contents('php://input'), true);

    if (!isset($request['name']) || !isset($request['email']) || !isset($request['password']) || !isset($request['sub_action'])) {
        http_response_code(400);
        echo json_encode(['message' => 'error', 'data' => []]);
        return;
    }

    $name = trim($request['name']);
    $email = filter_var($request['email'], FILTER_VALIDATE_EMAIL);
    $password = trim($request['password']);

    if (!$email) {
        http_response_code(400);
        echo json_encode(['message' => 'error', 'data' => []]);
        return;
    }

    $db = new PDO('mysql:host=localhost;dbname=mydb', 'username', 'password');
    $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    $stmt = $db->prepare("SELECT id FROM users WHERE email = :email");
    $stmt->execute([':email' => $email]);

    if ($stmt->rowCount() > 0) {
        $userData = $stmt->fetch(PDO::FETCH_ASSOC);
        http_response_code(200);
        echo json_encode(['message' => 'success', 'data' => ['id' => $userData['id']]]);
        return;
    }

    $createdAt = new DateTime();

    try {
        $apiResponse = callExternalApi($email, $password);
    } catch (Exception $e) {
        http_response_code(503);
        echo json_encode(['message' => 'error', 'data' => []]);
        return;
    }

    if ($apiResponse['status'] !== 200) {
        http_response_code(401);
        echo json_encode(['message' => 'error', 'data' => []]);
        return;
    }

    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

    try {
        $db->beginTransaction();
        $stmt = $db->prepare("INSERT INTO users (name, email, password, created_at) VALUES (:name, :email, :password, :created_at)");
        $stmt->execute([':name' => $name, ':email' => $email, ':password' => $hashedPassword, ':created_at' => $createdAt->format('Y-m-d H:i:s')]);
        $db->commit();
    } catch (Exception $e) {
        $db->rollback();
        http_response_code(500);
        echo json_encode(['message' => 'error', 'data' => []]);
        return;
    }

    http_response_code(201);
    echo json_encode(['message' => 'success', 'data' => ['id' => $db->lastInsertId()]]);
}

