    await exponentialBackoffStrategy.RunAsync(() => contentService.UpdateWebpageSectionContentAsync(pageSectionId, elementId, htmlContent));

    // Store the updated content in the cache for faster retrieval in future requests.
    cacheManager.Set(pageSectionId, elementId, htmlContent);

    // Notify all open browser tabs displaying the affected page section to refresh.
