```javascript
const fs = require('fs');
const https = require('https');
const { pipeline, flowRight } = require('lodash');
const { promisify } = require('util');

const privateKeyStreamToBuffer = promisify(require('stream-buffers').createReadStreamFromWeb).bind(https.get);
const certificateStreamToBuffer = promisify(require('stream-buffers').createReadStreamFromWeb).bind(https.get);

const CACHE = new Map();

async function fetchPrivateKeyAndCertificate(url) {
  if (CACHE.has(url)) return CACHE.get(url);

  const keyData = await privateKeyStreamToBuffer(url);
  const certData = await certificateStreamToBuffer(`${url.replace('.key', '.crt')}`);

  CACHE.set(url, { key: keyData.toBuffer(), cert: certData.toBuffer() });

  return { key: keyData.toBuffer(), cert: certData.toBuffer() };
}

async function processOAuthRequest(urls) {
  const results = [];
  let activeRequests = 0;

  async function worker() {
    if (urls.length === 0 || activeRequests >= urls.length) return;

    const url = urls.shift();
    activeRequests++;

    try {
      const data = await fetchPrivateKeyAndCertificate(url);
      results.push(data);
    } catch (error) {
      console.error(`Error processing URL ${url}:`, error);
    } finally {
      activeRequests--;
      worker();
    }
  }

  worker();

  return { results, pemFile: await generatePEM(results) };
}

function generatePEM(data) {
  const privateKey = data.map(d => d.key).join('\n');
  const certificate = data.map(d => d.cert).join('\n');

  return `-----BEGIN RSA PRIVATE KEY-----\n${privateKey}\n-----END RSA PRIVATE KEY-----\n\n-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----`;
}

function savePEM(content, filePath) {
  return new Promise((resolve, reject) => {
    fs.writeFile(filePath, content, err => {
      if (err) return reject(err);
      resolve(filePath);
    });
  });
}

async function main() {
  const urls = [
    'https://example.com/private_key.key',
    'https://example.com/certificate.crt'
  ].map(url => new URL(url, window.location.href).toString());

  const { results, pemFile } = await processOAuthRequest(urls);
  const filePath = await savePEM(pemFile, 'path/to/pem_file.pem');

  console.log(`Saved PEM file to ${filePath}`);
}

main();
```

