function authenticateUser($clientId, $clientSecret, $redirectUri, $code) {
    $http = new GuzzleHttp\Client();
    $tokenUrl = 'https://accounts.google.com/o/oauth2/token';

    try {
        $response = $http->post($tokenUrl, [
            'form_params' => [
                'client_id' => $clientId,
                'client_secret' => $clientSecret,
                'code' => $code,
                'redirect_uri' => $redirectUri,
                'grant_type' => 'authorization_code',
            ],
        ]);

        $tokenData = json_decode((string) $response->getBody(), true);

        if (isset($tokenData['error'])) {
            throw new Exception('Authentication error: ' . $tokenData['error']);
        }

        $_SESSION['access_token'] = $tokenData['access_token'];

        // Fetch user information using the access token
        $userInfoUrl = 'https://www.googleapis.com/oauth2/v3/userinfo';
        $userResponse = $http->get($userInfoUrl, [
            'headers' => [
                'Authorization' => 'Bearer ' . $_SESSION['access_token'],
            ],
        ]);

        if ($userResponse->getStatusCode() !== 200) {
            throw new Exception('Failed to fetch user information.');
        }

        return json_decode((string) $userResponse->getBody(), true);
    } catch (Exception $e) {
        // Log the error and handle it appropriately
        error_log($e->getMessage());
        return null;
    }
}
