And here's the JavaScript function `recursiveTraversal`:

```javascript
function recursiveTraversal(root, selector, callback, visited) {
    if (!visited || !visited[root.nodeName]) {
        if (callback(root, selector)) {
            visited = visited || {};
            visited[root.nodeName] = true;
            Array.from(root.children).forEach(child => recursiveTraversal(child, selector, callback, visited));
        }
    }

    if (root.hasAttributes) {
        for (let i = 0; i < root.attributes.length; i++) {
            const attr = root.attributes[i];
            recursiveTraversal(attr, selector, callback, visited);
        }
    }
}
```

