char* append_numbers(const char *filename, size_t num_digits) {
    size_t len = strlen(filename);
    char *new_filename = malloc(len + num_digits + 5); // 5 for ".xyz" extension and null terminator
    if (!new_filename) {
        perror("malloc failed");
        return NULL;
    }

    // Replace spaces with underscores
    for (size_t i = 0; filename[i]; ++i) {
        if (filename[i] == ' ') {
            new_filename[i] = '_';
        } else {
            new_filename[i] = filename[i];
        }
    }

    // Append extension and number sequence
    size_t ext_len = 4; // ".xyz"
    snprintf(new_filename + len - ext_len, ext_len, ".%0*d", num_digits, num_digits);

