#define IMMAGICK_LIBRARIES "magick-config --libs"

int convertJpegToPdf(const char *inputFile, const char *outputFile) {
    pid_t child = fork();

    if (child < 0) {
        perror("Fork failed");
        return 1;
    } else if (child > 0) {
        int status;
        waitpid(child, &status, 0);
        return WEXITSTATUS(status);
    }

    char *imageMagickCflags = NULL;
    char *imageMagickLibraries = NULL;
    char *args[] = {"./convert", inputFile, "-pdf", outputFile, NULL};

    if ((imageMagickCflags = (char *)malloc(sizeof(char) * (strlen(IMMAGICK_LIBRARY) + 1))) == NULL ||
        (imageMagickLibraries = (char *)malloc(sizeof(char) * (strlen(IMMAGICK_LIBRARIES) + 1))) == NULL) {
        perror("Memory allocation failed");
        return 1;
    }

    if (system(IMMAGICK_LIBRARY) != 0 || system(imageMagickLibraries) != 0) {
        free(imageMagickCflags);
        free(imageMagickLibraries);
        perror("ImageMagick library configuration failed");
        return 1;
    }

    char *env[] = {"LD_PRELOAD", imageMagickLibraries, NULL};
    execvp(".\\convert", args);

    if (execvp(args[0], args) < 0) {
        perror("Exec failed");
    }

    free(imageMagickCflags);
    free(imageMagickLibraries);
    return 1;
}
