bool validate_config(const std::string& filename) {
    try {
        nlohmann::json j;
        std::ifstream file(filename);
        if (!file.is_open()) {
            throw std::runtime_error("Unable to open configuration file");
        }
        file >> j;

        bool valid = true;
        const auto& config = j.get<nlohmann::json>();

        if (!(config.contains("network_host") && config.contains("network_port")
            && config.contains("log_level") && config.contains("security_key")
