                .compare("INFO") || !config["log_level"].get<std::string>()
                .compare("WARNING") || !config["log_level"].get<std::string>()
                .compare("ERROR") || !config["log_level"].get<std::string>()
                .compare("CRITICAL")) {
                valid = false;
            } else if (config["security_key"].get<std::string>().length() < 16) {
                valid = false;
            } else if (!config["load_balancing_enabled"].is_boolean()) {
