using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using log4net;

public class TripleDESDecryptor
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(TripleDESDecryptor));
    private TripleDESCryptoServiceProvider _tripleDes;
    private HMACSHA256 _hmac;
    private byte[] _key;
    private byte[] _iv;

    public TripleDESDecryptor(byte[] key, byte[] iv)
    {
        _key = key;
        _iv = iv;
        _tripleDes = new TripleDESCryptoServiceProvider();
        _hmac = new HMACSHA256(key);
    }

    public string DecryptBase64(string base64EncodedData, byte[] mac)
    {
        var data = Convert.FromBase64String(base64EncodedData);
        if (VerifyMac(mac, data))
        {
            using (var ms = new MemoryStream(data))
            {
                using (var cs = new CryptoStream(ms, _tripleDes.CreateDecryptor(_key, _iv), CryptoStreamMode.Read))
                {
                    var decryptedData = new byte[data.Length];
                    cs.Read(decryptedData, 0, decryptedData.Length);
                    return Encoding.UTF8.GetString(decryptedData);
                }
            }
        }
        else
        {
            Log.Error("MAC verification failed");
            throw new ArgumentException("Invalid MAC");
        }
    }

    private bool VerifyMac(byte[] mac, byte[] data)
    {
        var hmac = _hmac.ComputeHash(data);
        Array.Reverse(hmac);
        Array.Reverse(mac);
        return mac.SequenceEqual(hmac);
    }
}
```

