    {
        _logger = logger;
        _outputDirectory = outputDirectory;
        _cache = new ConcurrentDictionary<string, byte[]>();
        _cacheSize = cacheSize;
    }

    public async Task<byte[]> CalculateHashAsync(string filePath)
    {
        if (!File.Exists(filePath)) throw new FileNotFoundException();
        if (!Directory.Exists(_outputDirectory)) throw new DirectoryNotFoundException();
        if (!Directory.GetPermissions(_outputDirectory).FullControl) throw new UnauthorizedAccessException();

        string hashKey = GetHashKey(filePath);

        if (_cache.TryGetValue(hashKey, out var cachedHash)) return cachedHash;

        using (var sha256 = SHA256.Create())
