import java.io.*;
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.util.ConcurrentModificationException;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.locks.ReentrantLock;

public class Deserializer {
    private static final int HEADER_LENGTH = 4;
    private static final String CACHE_KEY_FORMAT = "%s-%s";
    private static final int CACHE_SIZE = 100;
    private static final MessageDigest SHA_256 = MessageDigest.getInstance("SHA-256");

    private Map<String, CacheEntry> cache = new HashMap<>();
    private ReentrantLock lock = new ReentrantLock();

    public <T> T deserialize(byte[] data) throws InvalidHeaderException, SerializationException {
        if (data == null || data.length < HEADER_LENGTH) {
            throw new InvalidHeaderException("Invalid header length");
        }

        ByteBuffer buffer = ByteBuffer.wrap(data);
        int header = buffer.getInt();
        if (header != 0xDEADBEEF) {
            throw new InvalidHeaderException("Invalid header value");
        }

        try (ObjectInputStream ois = new ObjectInputStream(new SynchronizedObjectInputStream(new ByteArrayInputStream(data))) {
            @Override
            protected synchronized Object readObject() throws IOException, ClassNotFoundException {
                if (this.getClass().getDeclaredField("classLoader").get(this) != Deserializer.class.getClassLoader()) {
                    throw new SerializationException("Deserialization of Externalizable objects is not allowed");
                }
                return super.readObject();
            }
        }) {
            Class<?> clazz = ois.readClass();
            String cacheKey = String.format(CACHE_KEY_FORMAT, clazz.getName(), toHexString(data));
            CacheEntry entry = cache.computeIfAbsent(cacheKey, k -> new CacheEntry());
            synchronized (entry) {
                if (!entry.isEvicted()) {
                    try {
                        return (T) entry.object;
                    } catch (ClassCastException e) {
                        throw new SerializationException("Deserialized object type mismatch");
                    }
                }
            }

            Object deserializedObject = ois.readObject();
            synchronized (entry) {
                entry.object = deserializedObject;
                entry.lastAccessed = System.currentTimeMillis();
            }

            return (T) deserializedObject;
        } catch (IOException | ClassNotFoundException e) {
            throw new SerializationException("Error during deserialization", e);
        }
    }

    private String toHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x ", b));
        }
        return sb.toString();
    }

    private static class CacheEntry {
        Object object;
        long lastAccessed;
        final ReentrantLock lock = new ReentrantLock();

        boolean isEvicted() {
            if (lock.getWriteLock().isHeldByCurrentThread()) {
                return false;
            }
            try {
                lock.readLock().lock();
                long currentTime = System.currentTimeMillis();
                long timeSinceLastAccess = currentTime - lastAccessed;
                if (timeSinceLastAccess > CACHE_SIZE * 60 * 1000) { // 60 minutes
                    evict();
                }
            } finally {
                lock.readLock().unlock();
            }
            return isEvicted;
        }

        void evict() {
            object = null;
            isEvicted = true;
        }

        boolean isEvicted = false;
    }

    private static class SynchronizedObjectInputStream extends ObjectInputStream {
        public SynchronizedObjectInputStream(InputStream in) {
            super(in);
        }

        @Override
        protected synchronized void readStreamHeader() throws IOException, ClassNotFoundException {
            super.readStreamHeader();
        }

        @Override
        protected synchronized Object readObject() throws IOException, ClassNotFoundException {
            return super.readObject();
        }
    }
}

class InvalidHeaderException extends RuntimeException {
    public InvalidHeaderException(String message) {
        super(message);
    }
}

class SerializationException extends RuntimeException {
    private SerializationException() {}

    private SerializationException(String message, Throwable cause) {
        super(message, cause);
    }

    public static SerializationException of(String message) {
        return new SerializationException(message, null);
    }

    public static SerializationException of(Throwable cause) {
        return new SerializationException(cause.getMessage(), cause);
    }
}
```

