mod logger {
    use super::*;

    pub fn init_logger() {
        env_logger::Builder::new()
            .format(|buf, record| writeln!(buf, "{} - {}: {}", chrono::Local::now().format("%Y-%m-%d %H:%M:%S"), record.level(), record.args()))
            .init();
    }
