static CONFIG_DIR_LOCK: Mutex<()> = Mutex::new(());

fn init_config_dir() -> Result<PathBuf, Box<dyn Error>> {
    let config_dirs = ConfigDirs::new().unwrap();
    let config_dir = config_dirs.config_dir().join("my-app");

    let mut lock = CONFIG_DIR_LOCK.lock().unwrap();

    if fs::metadata(&config_dir).is_err() {
        fs::create_dir_all(&config_dir)?;
    }

    Ok(config_dir)
}

fn set_env_var(path: PathBuf) {
    let config_dir = path.to_str().unwrap();
    if std::env::var("MY_APP_CONFIG").is_err() {
        std::env::set_var("MY_APP_CONFIG", config_dir);
    }
}

fn main() {
    logger::init_logger();

    let config_path = match init_config_dir() {
        Ok(path) => path,
        Err(e) => {
            error!("Failed to initialize configuration directory: {}", e);
            return;
        }
    };

    set_env_var(config_path);
}
