```c
#include <stdio.h>
#include <stdlib.h>
#include <openssl/evp.h>
#include <openssl/rsa.h>
#include <openssl/sha.h>
#include <openssl/md5.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[16]; // 128-bit CRC tag
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* populateNfarxIndications(int N) {
    NFAPI_CRC_INDICATION_PDU_T *indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        perror("Memory allocation failed");
        return NULL;
    }

    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create EVP context\n");
        free(indications);
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&mutex);

        indications[i].RX_UE_INFORMATION_TAG = i + 1;
        indications[i].RNTI = i * 1000000 + time(NULL); // Unique RNTI based on current time

        EVP_DigestInit_ex(ctx, EVP_sha1(), NULL);
        EVP_DigestUpdate(ctx, &i, sizeof(i));
        unsigned char crc[SHA_DIGEST_LENGTH];
        EVP_DigestFinal_ex(ctx, crc, NULL);
        memcpy(indications[i].CRC_INDICATION_REL8_TAG, crc, SHA_DIGEST_LENGTH);

        pthread_mutex_unlock(&mutex);
    }

    EVP_MD_CTX_free(ctx);
    return indications;
}

// Unit tests and other functions go here...
```

