using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Microsoft.Extensions.Caching.Memory;

public class DynamicValueGenerator
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private readonly TimeSpan _cacheExpiration;

    public DynamicValueGenerator(HttpClient httpClient, IMemoryCache cache, TimeSpan cacheExpiration)
    {
        _httpClient = httpClient;
        _cache = cache;
        _cacheExpiration = cacheExpiration;
    }

    public int NextInt(int min, int max, bool inclusive) => new Random().Next(min, (inclusive ? max : max + 1));

    public float NextFloat(float min, float max, bool inclusive) => new Random().NextFloat(min, (inclusive ? max : max + 1));

    public T NextFromList<T>(IEnumerable<T> options)
    {
        if (_cache.TryGetValue("options_" + GetHashCode(), out var cachedOptions))
            return (T)cachedOptions;

        var serializedOptions = JsonConvert.SerializeObject(options);
        _cache.Set("options_" + GetHashCode(), serializedOptions, _cacheExpiration);

        return options.GetRandom();
    }

    public async Task<string[]> FetchStringsFromApiAsync(string url, string userAgent)
    {
        var request = new HttpRequestMessage
        {
            Method = HttpMethod.Get,
            RequestUri = new Uri(url),
            Headers =
            {
                { "User-Agent", userAgent }
            }
        };

        _httpClient.Timeout = TimeSpan.FromSeconds(10);
        var response = await _httpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();
        return await JsonConvert.DeserializeObject<string[]>(await response.Content.ReadAsStringAsync());
    }

    public async Task<T[]> FetchListFromApiAsync<T>(string url, string userAgent) where T : new()
    {
        var strings = await FetchStringsFromApiAsync(url, userAgent);
        return JsonConvert.DeserializeObject<T[]>(strings[0]);
    }
}
