#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Record {
    int key;
    int value;
} Record;

typedef struct Storage {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Storage;

Storage* create_storage(size_t initial_capacity, size_t max_size) {
    if (initial_capacity == 0 || max_size <= initial_capacity) {
        return NULL;
    }

    Storage* storage = malloc(sizeof(Storage));
    storage->records = calloc(initial_capacity, sizeof(Record));
    storage->capacity = initial_capacity;
    storage->size = 0;
    pthread_mutex_init(&storage->lock, NULL);

    return storage;
}

int add_record(Storage* storage, Record record) {
    if (storage->size >= storage->capacity) {
        return -1; // Storage is full
    }

    pthread_mutex_lock(&storage->lock);
    storage->records[storage->size] = record;
    storage->size++;
    pthread_mutex_unlock(&storage->lock);

    return 0; // Success
}

Record* get_record(Storage* storage, int key) {
    if (storage->size == 0) {
        return NULL; // Empty storage
    }

    pthread_mutex_lock(&storage->lock);
    for (size_t i = 0; i < storage->size; ++i) {
        if (storage->records[i].key == key) {
            Record* result = &storage->records[i];
            pthread_mutex_unlock(&storage->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&storage->lock);

    return NULL; // Key not found
}

void resize(Storage* storage, size_t new_capacity) {
    if (new_capacity <= storage->size) {
        return; // No need to resize
    }

    Record* new_records = realloc(storage->records, new_capacity * sizeof(Record));
    if (!new_records) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    storage->records = new_records;
    storage->capacity = new_capacity;
}

