        else
            return _random.Next(min, max);
    }

    public Vector3D NextVector3D()
    {
        return new Vector3D(Next(_minX, _maxX), Next(_minY, _maxY), Next(_minZ, _maxZ));
    }

    public Point3D NextPoint3D()
    {
        return new Point3D(NextDouble(_minX, _maxX), NextDouble(_minY, _maxY), NextDouble(_minZ, _maxZ));
    }

