    {
        _minX = minX;
        _maxX = maxX;
        _minY = minY;
        _maxY = maxY;
        _minZ = minZ;
        _maxZ = maxZ;
        return NextPoint3D();
    }

    public override string ToString()
    {
        var builder = new StringBuilder();
        builder.AppendLine($"SpatialValueGenerator:");
        builder.AppendLine($"\tMin X: {_minX}, Max X: {_maxX}");
        builder.AppendLine($"\tMin Y: {_minY}, Max Y: {_maxY}");
        builder.AppendLine($"\tMin Z: {_minZ}, Max Z: {_maxZ}");
        builder.AppendLine($"\tIs Exclusive Upper Bound: {_isExclusiveUpperBound}");
        return builder.ToString();
    }
}

