```java
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Collectors;

public class CommandProcessor {
    private static final String USAGE = "Usage: java -jar command-processor.jar [config-file] [log] [output-dir]\n" +
            "Where:\n" +
            "- config-file is the path to the configuration file containing shell commands.\n" +
            "- log (optional) specifies whether to log execution details (true/false). Defaults to false.\n" +
            "- output-dir is the directory where results will be saved. If not provided, a temporary directory will be used.\n";

    private static final String TEMP_FILE_SUFFIX = ".temp";

    public static void main(String[] args) {
        if (args.length < 1 || args.length > 3) {
            System.out.println(USAGE);
            return;
        }

        String configFile = args[0];
        boolean logExecution = args.length >= 2 && "true".equalsIgnoreCase(args[1]);
        Path outputDir = args.length == 3 ? Paths.get(args[2]) : Files.createTempDirectory("command-processor");

        try {
            List<String> commands = readCommandsFromFile(configFile);
            for (String command : commands) {
                File tempFile = new File(command + TEMP_FILE_SUFFIX);
                if (tempFile.exists()) tempFile.delete();

                Process process = Runtime.getRuntime().exec(command);
                int exitValue = process.waitFor();
                if (exitValue != 0) {
                    System.err.println("Command execution failed with exit value: " + exitValue);
                    continue;
                }

                StringBuilder outputBuilder = new StringBuilder();
                StringBuilder errorBuilder = new StringBuilder();
                InputStream input = process.getInputStream();
                InputStream errorInput = process.getErrorStream();

                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = input.read(buffer)) != -1) {
                    outputBuilder.append(new String(buffer, 0, bytesRead));
                }
                while ((bytesRead = errorInput.read(buffer)) != -1) {
                    errorBuilder.append(new String(buffer, 0, bytesRead));
                }

                saveOutput(outputBuilder.toString(), errorBuilder.toString(), logExecution, outputDir);
            }
        } catch (IOException | InterruptedException e) {
            System.err.println("Error processing commands: " + e.getMessage());
        }
    }

    private static List<String> readCommandsFromFile(String filePath) throws IOException {
        return Files.lines(Paths.get(filePath)).collect(Collectors.toList());
    }

    private static void saveOutput(String output, String error, boolean logExecution, Path outputDir) {
        if (outputDir == null) return;

        Path resultFile = Files.createFile(outputDir.resolve(UUID.randomUUID() + ".txt"));
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(resultFile.toFile()))) {
            writer.write("Command Output:\n");
            writer.write(output);
            writer.newLine();
            writer.write("Error:\n");
            writer.write(error);
            if (logExecution) {
                writer.newLine();
                writer.write("Log:\n");
                writer.write(System.getProperty("user.dir") + "\n");
                writer.write(System.getenv().keySet().stream()
                        .map(k -> k + "=" + System.getenv(k))
                        .collect(Collectors.joining("\n")));
            }
        }
    }
}
```

This application reads a configuration file containing shell commands, executes them one by one, and saves the output in a structured format within the specified output directory. It also handles command execution failures gracefully and logs execution details if requested. The temporary files used during execution are deleted before each command is executed.

To run this application, save it as `CommandProcessor.java`, compile it using `javac CommandProcessor.java`, and then execute it with the required arguments:

```sh
java -jar target/command-processor.jar config.txt true output_dir
```']

