    data->append((char*)contents, size * nmemb);
    return size * nmemb;
}

Data processJson(const std::string& jsonStr) {
    Data result;
    auto j = json::parse(jsonStr);

    try {
        for (auto i : j.get<std::vector<int>>("integers")) {
            result.integers.push_back(i);
        }

        for (auto f : j.get<std::vector<double>>("floats")) {
            result.floats.push_back(f);
        }
    } catch (const std::exception& e) {
        std::cerr << "Error parsing JSON: " << e.what() << '\n';
    }

    return result;
}

void handleRequest(std::string url, std::function<void(Data)> callback) {
    curl_global_init(CURL_GLOBAL_DEFAULT);
    auto data = new std::string();

    CURL* curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, data);

        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            std::cerr << "Error fetching URL: " << curl_easy_strerror(res) << '\n';
            delete data;
            curl_easy_cleanup(curl);
            return;
        }

        Data result = processJson(*data);
        callback(result);
        delete data;
        curl_easy_cleanup(curl);
    }
}

void onDataReceived(Data data) {
    auto sumFloats = std::accumulate(data.floats.begin(), data.floats.end(), 0.0);
    auto avgInts = data.integers.size() > 0 ? std::accumulate(data.integers.begin(), data.integers.end(), 0) / static_cast<double>(data.integers.size()) : 0;

    std::cout << "Average of integers: " << avgInts << "\n";
    std::cout << "Sum of floats: " << sumFloats << '\n';
}

int main() {
    try {
        io_context ioc;
        boost::asio::ip::tcp::resolver resolver(ioc);
        auto results = boost::container::small_vector<std::pair<std::string, std::function<void(Data)>>>{};

        // Add URLs to process here
        results.emplace_back("http://example.com/data1", onDataReceived);
        results.emplace_back("http://example.com/data2", onDataReceived);

        for (auto& url : results) {
            io_service::work work(ioc);
            handleRequest(url.first, url.second);
        }

        ioc.run();
    } catch (const std::exception& e) {
        std::cerr << "Error in main: " << e.what() << '\n';
    }

    curl_global_cleanup();
}
```

This example demonstrates a simple concurrent request system using Boost.Asio, error handling for network failures and JSON parsing, and caching strategies through the use of a small vector to store URLs and their corresponding callback functions. However, it does not include any actual caching mechanism or memory optimization techniques beyond what is provided by the used libraries. You may need to further optimize the code based on your specific requirements and constraints.']

