    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ProtocolList;

ProtocolList protocol_list = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void load_protocols(const char* config_file) {
    FILE* file = fopen(config_file, "r");
    if (!file) {
        perror("Error opening configuration file");
        return;
    }

    Protocol** new_protocols = NULL;
    size_t capacity = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse the protocol entry and create a Protocol struct
        // ...

        if (capacity == protocol_list.count) {
            Protocol** temp = realloc(new_protocols, capacity * 2 * sizeof(Protocol*));
            if (!temp) {
                fprintf(stderr, "Out of memory\n");
                break;
            }
            new_protocols = temp;
            capacity *= 2;
        }

        new_protocols[protocol_list.count++] = protocol;
    }

    if (new_protocols) {
        pthread_mutex_lock(&protocol_list.lock);
        free(protocol_list.protocols);
        protocol_list.protocols = new_protocols;
        protocol_list.capacity = capacity;
        pthread_mutex_unlock(&protocol_list.lock);
    }

    fclose(file);
}

void* init_protocol(size_t index) {
    pthread_mutex_lock(&protocol_list.lock);
    if (index >= protocol_list.count) {
        pthread_mutex_unlock(&protocol_list.lock);
        return NULL;
    }
    void* (*init)(void) = protocol_list.protocols[index]->init;
    Protocol* protocol = protocol_list.protocols[index];
    pthread_mutex_unlock(&protocol_list.lock);
    return init();
}

// ... (Add other functions for handling packets, cleaning up resources, etc.)
```

