struct Semaphore {
    sem_t sem; // System semaphore
    int value; // Current semaphore value
};
```

2. Implement a dynamic array for managing the set of semaphores:

```cpp
#include <vector>
std::vector<Semaphore> semaphores;
const int MAX_SEMAPHORES = 100;
```

3. Initialize semaphores with given values at runtime:

```cpp
void init_semaphores(int* initial_values, int count) {
    if (count > MAX_SEMAPHORES) {
        throw std::runtime_error("Initialization count exceeds the maximum number of semaphores");
    }

    for (int i = 0; i < count; ++i) {
        Semaphore s;
        s.value = initial_values[i];
        sem_init(&s.sem, 0, s.value);
        semaphores.push_back(s);
    }
}
```

4. Implement wait and signal operations:

```cpp
void wait(int index) {
    if (index >= semaphores.size()) {
        throw std::runtime_error("Invalid semaphore index");
    }
    sem_wait(&semaphores[index].sem);
}

void signal(int index) {
    if (index >= semaphores.size()) {
        throw std::runtime_error("Invalid semaphore index");
    }
    sem_post(&semaphores[index].sem);
}
```

5. Implement dynamic resizing of the semaphore set:

```cpp
void resize(int new_size) {
    if (new_size > MAX_SEMAPHORES) {
        throw std::runtime_error("New size exceeds the maximum number of semaphores");
    }

    std::vector<Semaphore> new_semaphores(new_size);
    for (int i = 0; i < semaphores.size() && i < new_size; ++i) {
        new_semaphores[i] = semaphores[i];
    }
    semaphores = std::move(new_semaphores);
}
```

