```cpp
#include <boost/asio.hpp>
#include <log4cxx/logger.h>
#include <log4cxx/basicconfigurator.h>

using boost::asio::ip::tcp;

struct HttpRequest {
    std::string method;
    std::string url;
    std::map<std::string, std::string> headers;
    std::string body;
};

class HttpClient {
public:
    void sendRequest(const HttpRequest& request) {
        // Create a TCP socket and establish a connection to the server.
        tcp::resolver resolver(io_);
        auto results = resolver.resolve(request.url, "http");

        boost::asio::connect(*socket_, results.begin(), results.end());

        // Set up an asynchronous write operation for the request headers and body.
        boost::beast::ostream outputStream(*socket_);
        outputStream << request.method << ' ' << request.url << ' ' << "HTTP/1.1\r\n";
        for (const auto& header : request.headers) {
            outputStream << header.first << ": " << header.second << "\r\n";
        }
        if (!request.body.empty()) {
            outputStream << "\r\n" << request.body;
        }
        outputStream << "\r\n";

        // Set up an asynchronous read operation for the response.
        auto buffer = boost::beast::flat_buffer(1024);
        beast::error_code errorCode;
        auto readHandler = [this, &errorCode](boost::system::error_code ec, std::size_t bytesTransferred) {
            if (!ec) {
                // Process the response here.
                log_.info("Received response: " + boost::asio::buffer_to_string(buffers_[0].data(), bytesTransferred));
                ++successfulRequests_;
            } else if (ec == boost::beast::errc::connection_aborted) {
                // Handle connection errors here.
                log_.error("Connection aborted: " + ec.message());
                ++failedAttempts_;
            } else {
                // Handle other errors here.
                log_.error("Error: " + ec.message());
                ++failedAttempts_;
            }

            if (socket_) {
                socket_->close(ec);
                socket_.reset();
            }
        };

        beast::flat_buffer buffers_[1];
        boost::asio::async_read(*socket_, buffers_[0], readHandler, errorCode);
    }

private:
    boost::asio::io_context io_;
    tcp::socket socket_;
    log4cxx::LoggerPtr log_{&log4cxx::Logger::getLogger("HttpClient")};
    int successfulRequests_{0}, failedAttempts_{0};
};

int main(int argc, char* argv[]) {
    // Configure logging.
    log4cxx::BasicConfigurator::configure();

    // Parse command-line arguments to construct HttpRequest objects.
    // Create HttpClient instances and send requests as needed.

    return 0;
}
```

