[" Here's a JavaScript function using `fs` module (Node.js) that meets your requirements:

```javascript
const fs = require('fs');
const path = require('path');
const readFilePromise = (filePath) => {
  return new Promise((resolve, reject) => {
    fs.stat(filePath, (err, stats) => {
      if (err) {
        console.error(`Error checking file ${filePath}:`, err);
        return reject(err);
      }

      if (!stats.isFile()) {
        console.error(`${filePath} is not a regular file`);
        return reject(new Error(`${filePath} is not a regular file`));
      }

      const readStream = fs.createReadStream(filePath);
      const chunks = [];

      readStream.on('error', (err) => {
        console.error(`Error reading file ${filePath}:`, err);
        readStream.destroy();
        return reject(err);
      });

      readStream.on('data', (chunk) => {
        chunks.push(chunk);
      });

      readStream.on('end', () => {
        resolve(Buffer.concat(chunks).toString());
      });
    });
  });
};
```

This function uses a Promise to handle asynchronous file reading and error handling. It checks if the provided file path is valid, ensures it's a regular file, and creates a read stream for the file. The function reads the file in chunks to avoid blocking the event loop and minimizes memory usage when dealing with large files.

To use this function, you can call it like so:

```javascript
readFilePromise('path/to/your/file.txt')
  .then((content) => {
    console.log(content);
  })
  .catch((err) => {
    console.error(err);
  });
```"]

