function createRegex(books, caseSensitive = false) {
  const regexes = books.map((book) => {
    const bookName = caseSensitive ? book : book.toLowerCase();
    return new RegExp(`\\b(${bookName})\\w*\\b`, 'gi');
  });
  return regexes;
}

// Define the main function to process the text and extract book references
async function findBookReferences(text, options = {}) {
  // Merge user-specified options with default config
  const finalConfig = lodash.merge({}, config, options);

  // Create regular expressions for each testament
  const oldTestamentRegexes = createRegex(finalConfig.bibleBooks.oldTestament);
  const newTestamentRegexes = createRegex(finalConfig.bibleBooks.newTestament);

  // Find matches in the text and group them by book name
  const matches = { oldTestament: [], newTestament: [] };
  let oldMatches, newMatches;

  // Use a loop to iterate through each testament's regexes for better performance
  for (let i = 0; i < oldTestamentRegexes.length; i++) {
    oldMatches = text.match(oldTestamentRegexes[i]);
    if (oldMatches) matches.oldTestament = matches.oldTestament.concat(oldMatches);
  }

  for (let i = 0; i < newTestamentRegexes.length; i++) {
    newMatches = text.match(newTestamentRegexes[i]);
    if (newMatches) matches.newTestament = matches.newTestament.concat(newMatches);
  }

  // Filter the matches based on user-specified criteria
  const filteredMatches = lodash.filter(matches.oldTestament.concat(matches.newTestament), (match) => {
    return finalConfig.filter.includeOnlyDirectMentions ? isDirectMention(match) : true;
  });

  // Define a function to check if a match is a direct mention
  function isDirectMention(match) {
    const wordsBefore = text.slice(0, match.index - match[0].length).split(/\s+/);
    const wordsAfter = text.slice(match.index).split(/\s+/);

    // Check if the match is preceded and followed by a word that doesn't belong to the Bible
    return (
      !wordsBefore.some((word) => isBibleWord(word, finalConfig.languages)) &&
      !wordsAfter.some((word) => isBibleWord(word, finalConfig.languages))
    );
  }

  // Define a function to check if a word is a Bible word (case-insensitive)
  function isBibleWord(word, languages) {
    return languages.some((lang) => new RegExp(`\\b(${word})\\w*\\b`, 'i').test(getBibleWords(lang).join('|')));
  }

  // Define a function to fetch additional contextual information about each book
  async function getBookInfo(bookName) {
    const apiResponse = await axios.get(`${finalConfig.apiUrl}/${bookName}`);
    return apiResponse.data;
  }

  // Define a memoized function to fetch book info with debouncing for performance
  const getBookInfoDebounced = lodash.debounce(getBookInfo, finalConfig.debounceDelay);

  // Process the filtered matches and fetch additional contextual information
  const results = {};
  for (const match of filteredMatches) {
    const bookName = match[0];
    if (!results[bookName]) results[bookName] = 1;
    else results[bookName]++;

    // Fetch additional contextual information and handle potential API failures or delays
    try {
      const bookInfo = await getBookInfoDebounced(bookName);
      results[bookName].info = bookInfo;
    } catch (error) {
      console.error(`Error fetching info for ${bookName}:`, error);
    }
  }

  return results;
}
```"]

