angular.module('myApp')
  .factory('FormValidator', ['$q', function($q) {
    var cache = {};
    var log = [];

    function validateAndUpdate(form, fieldNames, onSuccess, onError) {
      var deferred = $q.defer();

      // Filter form fields based on the provided field names
      var validFields = angular.forEach(form.$error, function(field) {
        return angular.forEach(field, function(fieldObj) {
          if (fieldNames.indexOf(fieldObj.$name) !== -1) {
            return cache[fieldObj.$name] = fieldObj;
          }
        });
      });

      // If there are valid fields, send them to the parent window for processing
      if (validFields.length > 0) {
        var dataToSend = {};
        angular.forEach(validFields, function(field) {
          dataToSend[field.$name] = {
            type: field.type,
            validationStatus: field.$dirty && field.$invalid,
            value: field.$modelValue
          };
        });

        // Simulate network request and potential failures/delays
        $q.when(parent.processFormData(dataToSend))
          .then(function(response) {
            angular.forEach(response, function(updatedFieldData) {
              cache[updatedFieldData.name].$setViewValue(updatedFieldData.value);
            });
            deferred.resolve();
          })
          .catch(function(error) {
            onError(error);
            log.push({ event: 'error', data: error });
          });
      } else {
        // No valid fields to process, resolve the promise immediately
        deferred.resolve();
      }

      return deferred.promise;
    }

    return {
      validateAndUpdate: validateAndUpdate
    };
  }]);
