fn analyze_rust_project(args: Vec<String>) -> Result<(i32, f64, i64, Vec<Element>), AnalysisError> {
    let project_path = args[0].clone();
    let css_selector = args[1].clone();

    // Check dependencies and attempt to resolve them if necessary
    check_dependencies(&project_path)?;

    // Compile the Rust project and measure compilation time
    let start_time = Instant::now();
    let output = compile_rust_project(&project_path)?;
    let compilation_time = start_time.elapsed().as_secs_f64();

    // Parse the compiled HTML, calculate resident set size change, and find matching DOM elements
    let html_content = read_output(&output)?;
    let mut rss_before = get_rss()?;
    let document = document_from_string(html_content.as_str())?;
    let mut elements = Vec::new();

    let parser = TreesoupParser::new();
    for node in parser.walk_up(&document, css_selector.as_str()) {
        elements.push(Element {
            tag: node.tag().to_string(),
            attributes: node.attributes().collect(),
        });
    }

    let rss_after = get_rss()?;
    let rss_change = rss_after - rss_before;

    Ok((output.status().code(), compilation_time, rss_change, elements))
}

