class DatabaseUpdateAndRandomValueGenerator {
    private $db;
    private $ranges = [];
    private $rangeCache;
    private $cacheSize = 1000;
    private $refreshInterval = 60; // seconds
    private $lastRefresh;

    public function __construct($db) {
        $this->db = $db;
        $this->rangeCache = $this->getRandomValuesFromRanges(array_merge([
            'default' => [0, 1] // Default range for fallback scenarios
        ], $this->ranges));
        $this->lastRefresh = time();
    }

    public function updateClinic($clinicId) {
        $stmt = $this->db->prepare("UPDATE clinics SET status=?, last_modified_ip=?, last_modified=NOW() WHERE id=?");
        $stmt->execute([$status, $_SERVER['REMOTE_ADDR'], $clinicId]);
        return $stmt->rowCount() > 0 ? "Successfully updated clinic." : "Failed to update clinic.";
    }

    public function addRange($name, $min, $max) {
        if ($min >= $max) {
            throw new InvalidArgumentException("Invalid range: min must be less than max.");
        }
        $this->ranges[$name] = [$min, $max];
        $this->refreshRanges();
    }

    public function removeRange($name) {
        if (!array_key_exists($name, $this->ranges)) {
            throw new KeyNotFoundException("Range not found.");
        }
        unset($this->ranges[$name]);
        $this->refreshRanges();
    }

    private function getRandomValuesFromRanges($ranges) {
        $randomValues = [];
        foreach ($ranges as $rangeName => $range) {
            if (!isset($this->rangeCache[$rangeName])) {
                $this->rangeCache[$rangeName] = array_merge([0, count($randomValues)], $range);
            }
            for ($i = $this->rangeCache[$rangeName][1]; $i > $this->rangeCache[$rangeName][2]; $i--) {
                $randomValues[] = $this->getRandomValue($rangeName);
                if (count($randomValues) >= $this->cacheSize) {
                    break;
                }
            }
        }
        return $randomValues;
    }

    private function getRandomValue($rangeName) {
        list($min, $currentCount, $max) = $this->rangeCache[$rangeName];
        if ($currentCount >= $max) {
            $this->refreshRanges();
        }
        $nextIndex = $min + rand(0, $currentCount - $min);
        $this->rangeCache[$rangeName][2] = $nextIndex;
        return $this->rangeCache[$rangeName][$nextIndex];
    }

    private function refreshRanges() {
        if (time() - $this->lastRefresh < $this->refreshInterval) {
            return; // Wait for the specified interval before refreshing ranges.
        }
        try {
            $newRanges = fetchRangesFromExternalService(); // Implement this method to integrate with your external service.
            $this->ranges = $newRanges;
            $this->rangeCache = [];
            $this->lastRefresh = time();
        } catch (Exception $e) {
            // Handle service unavailability and network errors gracefully, e.g., by retrying or using fallback strategies.
        }
    }
}
