#include <boost/archive/text_oarchive.hpp>
#include <boost/archive/text_iarchive.hpp>

class ValueRange {
public:
    ValueRange(float min, float max) : min_(min), max_(max) {}

    float min() const { return min_; }
    float max() const { return max_; }

private:
    friend class boost::serialization::access;
    template<class Archive>
    void serialize(Archive& ar, const unsigned int version) {
        ar & min_ & max_;
    }

    float min_;
    float max_;
};

std::mutex rangesMutex;
std::vector<ValueRange> ranges;
std::map<float, std::set<int>> rangeIds;
std::map<int, ValueRange> idToRange;
int nextId_ = 1;

class ValueRangeManager {
public:
    void addRange(const ValueRange& range) {
        std::lock_guard<std::mutex> lock(rangesMutex);
        auto it = std::lower_bound(ranges.begin(), ranges.end(), range, [](const auto& lhs, const auto& rhs) { return lhs.min() < rhs.min(); });
        int id = nextId_++;
        ranges.insert(it, range);
        rangeIds[range.min()].insert(id);
        idToRange[id] = range;
    }

    void removeRange(int id) {
        std::lock_guard<std::mutex> lock(rangesMutex);
        auto it = idToRange.find(id);
        if (it != idToRange.end()) {
            float min = it->second.min();
            rangeIds[min].erase(id);
            idToRange.erase(it);
            ranges.erase(std::remove_if(ranges.begin(), ranges.end(), [&](const auto& r) { return r.min() == min; }), ranges.end());
        }
    }

    void setDefaultRange(int id) {
        std::lock_guard<std::mutex> lock(rangesMutex);
        if (rangeIds.find(defaultId_) != rangeIds.end()) {
            defaultId_ = id;
        }
        for (const auto& [min, ids] : rangeIds) {
            if (!ids.empty() && (defaultId_ == 0 || min < idToRange[defaultId_].min())) {
                defaultId_ = *ids.begin();
            }
        }
    }

    float getDefaultRangeMin() const {
        std::lock_guard<std::mutex> lock(rangesMutex);
        return idToRange[defaultId_].min();
    }

    int generateRandomInt(int rangeId) {
        auto it = rangeIds.find(rangeId);
        if (it != rangeIds.end()) {
            std::uniform_int_distribution<int> distr(static_cast<int>(idToRange[*it].min()), static_cast<int>(idToRange[*it].max()));
            return distr(generator_);
        }
        return static_cast<int>(idToRange[defaultId_].min()) + static_cast<int>(std::uniform_real_distribution<float>({ 0, idToRange[defaultId_].max() - idToRange[defaultId_].min() }).operator()(generator_));
    }

    float generateRandomFloat(int rangeId) {
        auto it = rangeIds.find(rangeId);
        if (it != rangeIds.end()) {
            std::uniform_real_distribution<float> distr(idToRange[*it].min(), idToRange[*it].max());
            return distr(generator_);
        }
        return idToRange[defaultId_].min() + static_cast<float>(std::uniform_real_distribution<float>({ 0, idToRange[defaultId_].max() - idToRange[defaultId_].min() }).operator()(generator_));
    }

    void loadRangesFromFile(const std::string& filename) {
        std::ifstream ifs(filename);
        boost::archive::text_iarchive ia(ifs);
        ia >> ranges;
        for (const auto& range : ranges) {
            addRange(range);
        }
    }

    void saveRangesToFile(const std::string& filename) const {
        std::ofstream ofs(filename);
        boost::archive::text_oarchive oa(ofs);
        oa << ranges;
    }

private:
    static std::random_device rd_;
    static std::mt19937 generator_;
};

std::random_device ValueRangeManager::rd_;
std::mt19937 ValueRangeManager::generator_(ValueRangeManager::rd_);
```

