```java
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class CommandExecutor {
    private static final String COMMAND_DIR = "command_dir";
    private ProcessBuilder processBuilder;

    public CommandExecutor(String command, Map<String, String> env, Map<String, String> params) {
        cleanDirectory(COMMAND_DIR);
        processBuilder = new ProcessBuilder(command.split(" "), (List<String>) params.values()).directory(new File(COMMAND_DIR));
        processBuilder.inheritIO(); // Inherit standard input and output streams from the current process
        processBuilder.environment().putAll(env);
    }

    public void start() {
        try {
            Process process = processBuilder.start();
            handleProcessInterruptions(process);
        } catch (IOException e) {
            System.err.println("Error starting the process: " + e.getMessage());
        }
    }

    private void handleProcessInterruptions(Process process) {
        Thread thread = new Thread(() -> {
            try {
                process.waitFor();
            } catch (InterruptedException e) {
                System.err.println("Error waiting for the process: " + e.getMessage());
            } finally {
                process.destroy();
            }
        });
        thread.setDaemon(true);
        thread.start();
    }

    private void cleanDirectory(String dir) {
        try {
            Files.walk(Paths.get(dir))
                    .sorted(Comparator.reverseOrder())
                    .map(Path::toFile)
                    .forEach(File::delete);
        } catch (IOException e) {
            System.err.println("Error cleaning the directory: " + e.getMessage());
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Map<String, String> env = new HashMap<>();
        env.put("VAR1", "VALUE1");

        Map<String, String> params = new HashMap<>();
        params.put("param1", "value1");
        params.put("param2", "value2");

        CommandExecutor executor = new CommandExecutor("/path/to/your_executable", env, params);
        executor.start();
    }
}
```

