#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    char *name;
    void *session_metadata;
    void (*notification_callback)(void*);
    pthread_mutex_t mutex;
    time_t last_notified;
} UserSession;

enum ErrorCode {
    NO_ERROR = 0,
    INVALID_NAME,
    INACTIVE_SESSION,
    NULL_CALLBACK
};

ErrorCode validate_and_update(UserSession *session) {
    if (!session || !session->name || !*session->name) {
        return INVALID_NAME;
    }

    pthread_mutex_lock(&session->mutex);
    if (static_cast<SessionMetadata*>(session->session_metadata)->is_inactive) {
        pthread_mutex_unlock(&session->mutex);
        return INACTIVE_SESSION;
    }

    if (!session->notification_callback) {
        pthread_mutex_unlock(&session->mutex);
        return NULL_CALLBACK;
    }
    pthread_mutex_unlock(&session->mutex);

    time_t current_time = time(NULL);
    session->last_notified = current_time;
    return NO_ERROR;
}
```

