#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include "cJSON.h"

bool is_valid_access_token(const char *json_str) {
    cJSON *root = cJSON_Parse(json_str);

    if (!root) {
        fprintf(stderr, "Error: Invalid JSON format\n");
        return false;
    }

    const char *token_type = cJSON_GetObjectItem(root, "token_type")->valuestring;
    const char *access_token = cJSON_GetObjectItem(root, "access_token")->valuestring;
    const char *refresh_token = cJSON_GetObjectItem(root, "refresh_token")->valuestring;
    int expires_in = cJSON_GetObjectItem(root, "expires_in")->valueint;

    if (strcmp(token_type, "'Bearer'") != 0) {
        fprintf(stderr, "Error: Invalid 'token_type'\n");
        cJSON_Delete(root);
        return false;
    }

    if (expires_in <= 0 || expires_in > 3600) {
        fprintf(stderr, "Error: Invalid 'expires_in'\n");
        cJSON_Delete(root);
        return false;
    }

    if (!access_token || (refresh_token && !refresh_token[0])) {
        fprintf(stderr, "Error: Missing or invalid 'access_token' or 'refresh_token'\n");
        cJSON_Delete(root);
        return false;
    }

    cJSON_Delete(root);
    return true;
}
```

