public class DataProcessor
{
    private Aes _aes;
    private byte[] _key;
    private byte[] _iv;

    public DataProcessor(byte[] key, string configurationSource)
    {
        LoadKey(key, configurationSource);
    }

    private void LoadKey(byte[] key, string configurationSource)
    {
        // Implement key loading logic from the external configuration source.
        // This could involve reading the key from a file, database, or other storage system.
        // Ensure secure handling of keys and proper error handling for invalid keys.
    }

    public void GenerateIV()
    {
        _iv = new RNGCryptoServiceProvider().GetBytes(16);
    }

    private byte[] CreateMAC(byte[] data)
    {
        using (HMACSHA256 hmac = new HMACSHA256(_key))
        {
            return hmac.ComputeHash(data);
        }
    }

    public byte[] Encrypt(bool generateNewIV, byte[] data)
    {
        if (data == null || data.Length <= 0)
        {
            throw new ArgumentException("Data cannot be null or empty.");
        }

        if (!generateNewIV && _iv == null)
        {
            throw new InvalidOperationException("No IV has been generated yet.");
        }

        GenerateIVIfNeeded(generateNewIV);

        using (MemoryStream ms = new MemoryStream())
        {
            using (CryptoStream cs = new CryptoStream(ms, _aes.CreateEncryptor(_key, _iv), CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
            }

            return ms.ToArray();
        }
    }

    private void GenerateIVIfNeeded(bool generateNewIV)
    {
        if (generateNewIV && _iv != null)
        {
            _iv = null; // Reset IV to force generation of a new one on the next call.
        }

        if (_iv == null)
        {
            GenerateIV();
        }
    }

    public byte[] Decrypt(byte[] data, byte[] mac)
    {
        if (data == null || data.Length <= 0 || mac == null || mac.Length != 32)
        {
            throw new ArgumentException("Invalid input data or MAC.");
        }

        GenerateIVIfNeeded(false); // Ensure an IV has been generated before decryption.

        byte[] decryptedData;
        using (MemoryStream ms = new MemoryStream(data))
        {
            using (CryptoStream cs = new CryptoStream(ms, _aes.CreateDecryptor(_key, _iv), CryptoStreamMode.Read))
            {
                decryptedData = new byte[ms.Length];
                cs.Read(decryptedData, 0, decryptedData.Length);
            }
        }

        byte[] computedMac = CreateMAC(decryptedData);
        if (!Array.Equals(computedMac, mac))
        {
            throw new InvalidOperationException("MAC verification failed.");
        }

        return decryptedData;
    }
}
```

