using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class DynamicRandomValueGenerator : RandomValueGenerator
{
    private readonly Dictionary<Type, Func<Random, object>> _generators = new Dictionary<Type, Func<Random, object>>();
    private readonly ConcurrentDictionary<(int min, int max), List<object>> _cache = new ConcurrentDictionary<(int, int), List<object>>();
    private readonly SemaphoreSlim _resourcePool = new SemaphoreSlim(100); // Adjust as needed
    private readonly ILoggingService _loggingService;
    private Random _random;
    private (int min, int max) _currentRange;

    public DynamicRandomValueGenerator(ILoggingService loggingService)
    {
        _loggingService = loggingService;
        InitializeGenerators();
    }

    public void SetRange((int min, int max) range)
    {
        _currentRange = range;
    }

    private void InitializeGenerators()
    {
        _generators.Add(typeof(int), r => r.Next(_currentRange.min, _currentRange.max));
        // Add more generators for other numeric types as needed
    }

    public T Generate<T>()
    {
        if (!_cache.TryGetValue(_currentRange, out var values))
        {
            values = new List<object>();
            Parallel.ForEach(Enumerable.Range(0, _random.Next(100) + 1), i =>
            {
                lock (_cache)
                {
                    if (!_cache.TryGetValue(_currentRange, out values))
                        values = new List<object>();
                }
                values.Add(_generators[typeof(T)](_random));
            });
        }

        _resourcePool.Wait();
        try
        {
            var value = values.Dequeue();
            _loggingService.Log($"Generated {value} of type {typeof(T)}", LogLevel.Info);
            return (T)value;
        }
        finally
        {
            _resourcePool.Release();
        }
    }

    // Implement other methods for logging, state persistence, error handling, etc.
}
