using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Text;
using System.Threading;
using Newtonsoft.Json;

public class DynamicValueGenerator
{
    private readonly ConcurrentDictionary<string, (float min, float max)> _ranges = new ConcurrentDictionary<string, (float, float)>();
    private readonly (float min, float max) _defaultRange = (0f, 1f);
    private readonly HttpClient _httpClient;

    public DynamicValueGenerator()
    {
        _httpClient = new HttpClient();
        LoadRangesFromExternalSource();
    }

    private async void LoadRangesFromExternalSource()
    {
        try
        {
            var response = await _httpClient.GetAsync("https://your-api-url/ranges");
            response.EnsureSuccessStatusCode();
            var json = await response.Content.ReadAsStringAsync();
            var ranges = JsonConvert.DeserializeObject<List<(string id, float min, float max)>>(json);
            foreach (var range in ranges)
            {
                _ranges[range.id] = (range.min, range.max);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading ranges from external source: {ex.Message}");
        }
    }

    public void AddRange(string id, float min, float max)
    {
        _ranges[id] = (min, max);
    }

    public void RemoveRange(string id)
    {
        _ranges.TryRemove(id, out (_));
    }

    public void SetDefaultRange(string id)
    {
        if (_ranges.TryGetValue(id, out var range))
        {
            _defaultRange = range;
        }
    }

    public float GetRandomFloatInRange(string id = null)
    {
        return id == null ? GetDefaultRandomFloat() : GetRandomFloatFromRange(id);
    }

    private float GetDefaultRandomFloat()
    {
        return new Random().NextFloat(_defaultRange.min, _defaultRange.max);
    }

    private float GetRandomFloatFromRange(string id)
    {
        if (_ranges.TryGetValue(id, out var range))
        {
            return new Random().NextFloat(range.min, range.max);
        }
        else
        {
            Console.WriteLine($"No range found for ID: {id}");
            return GetDefaultRandomFloat();
        }
    }

    public override string ToString()
    {
        var builder = new StringBuilder();
        builder.AppendLine("Ranges:");
        foreach (var range in _ranges)
        {
            builder.AppendLine($"ID: {range.Key}, Min: {range.Value.min}, Max: {range.Value.max}");
        }
        builder.AppendLine($"Default Range: ID: null, Min: {_defaultRange.min}, Max: {_defaultRange.max}");
        return builder.ToString();
    }
}
```

