```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public static class TripleDesEncryption
{
    public static string Encrypt(string plainText, byte[] key, byte[] iv)
    {
        using (TripleDESCryptoServiceProvider tripleDES = new TripleDESCryptoServiceProvider())
        {
            tripleDES.Key = key;
            tripleDES.IV = iv;

            ICryptoTransform cryptoTransform = tripleDES.CreateEncryptor();
            byte[] encryptedData = cryptoTransform.TransformFinalBlock(Encoding.UTF8.GetBytes(plainText), 0, plainText.Length);

            return Convert.ToBase64String(encryptedData);
        }
    }

    public static string Decrypt(string base64EncodedData, byte[] key, byte[] iv)
    {
        byte[] encryptedData = Convert.FromBase64String(base64EncodedData);

        using (TripleDESCryptoServiceProvider tripleDES = new TripleDESCryptoServiceProvider())
        {
            tripleDES.Key = key;
            tripleDES.IV = iv;

            ICryptoTransform cryptoTransform = tripleDES.CreateDecryptor();
            byte[] decryptedData = cryptoTransform.TransformFinalBlock(encryptedData, 0, encryptedData.Length);

            return Encoding.UTF8.GetString(decryptedData);
        }
    }
}
