```javascript
const fs = require('fs');
const regex = /[a-zA-Z0-9]+/;

function loadConfig() {
  const config = JSON.parse(fs.readFileSync('languages.json', 'utf8'));
  return config.supported_languages;
}

function isLanguage(word, languages) {
  for (const lang of languages) {
    if (lang.name === word || lang.aliases.includes(word)) {
      return lang;
    }
  }
  return null;
}

function extractLanguagesFromText(text) {
  const languages = loadConfig();
  const words = text.match(regex) || [];
  const results = [];

  for (const word of words) {
    const language = isLanguage(word, languages);
    if (language) {
      results.push(language);
    }
  }

  return results;
}

// Usage example:
const text = `
function helloWorld() {
  console.log("Hello, World!");
}
`;

console.log(extractLanguagesFromText(text));
```

