function retry($callback, int $maxAttempts = 5, float $backoffFactor = 2) {
    for ($attempt = 1; $attempt <= $maxAttempts; ++$attempt) {
        try {
            return $callback();
        } catch (Exception $e) {
            if ($attempt >= $maxAttempts) {
                throw $e;
            }
            usleep($backoffFactor ** ($attempt - 1));
        }
    }
}
