    int tag = rand() % 65536; // Adjust the range as needed
    pthread_mutex_unlock(&mutex);
    return (void*)tag;
}

void* get_crc_indication_rel8_tag() {
    pthread_mutex_lock(&mutex);
    int tag = rand() % 256; // Adjust the range as needed
    pthread_mutex_unlock(&mutex);
    return (void*)tag;
}

void set_crcflag(uint8_t* crcflag) {
    *crcflag = rand() % 2;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize(int N) {
    if (N <= 0) {
        log("Invalid number of elements");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        log("Memory allocation failure");
        return NULL;
    }

    num_allocated = N;
    data = new_data;

    for (int i = 0; i < N; ++i) {
        int rnti = rand() % 1000000; // Adjust the range as needed
        while (rnti == data[i].RNTI || i != 0 && rnti == data[i - 1].RNTI) {
            rnti = rand() % 1000000; // Adjust the range as needed
        }
        data[i].RNTI = rnti;
        data[i].RX_UE_INFORMATION_TAG = (uint16_t)get_rx_ue_information_tag();
        data[i].CRC_INDICATION_REL8_TAG = (uint16_t)get_crc_indication_rel8_tag();
        set_crcflag(&data[i].CRCFLAG);
    }

    return data;
}

void deallocate() {
    free(data);
    num_allocated = 0;
    data = NULL;
}
