```csharp
using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class DynamicValueGenerator
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, TimeSpan> _cacheDurations;
    private readonly ConcurrentDictionary<string, TimeSpan> _refreshIntervals;

    public DynamicValueGenerator(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _cacheDurations = new ConcurrentDictionary<string, TimeSpan>();
        _refreshIntervals = new ConcurrentDictionary<string, TimeSpan>();
    }

    public void SetCacheDuration(string resourceKey, TimeSpan cacheDuration)
    {
        _cacheDurations[resourceKey] = cacheDuration;
    }

    public void SetRefreshInterval(string resourceKey, TimeSpan refreshInterval)
    {
        _refreshIntervals[resourceKey] = refreshInterval;
    }

    public T GetFromCache<T>(string resourceKey)
    {
        if (_cache.TryGetValue(resourceKey, out var cachedData))
            return JsonConvert.DeserializeObject<T>(cachedData);
        return default;
    }

    public async Task<T> FetchAndCacheAsync<T>(string resourceUrl, Func<HttpResponseMessage, T> deserializer)
    {
        if (_cache.TryGetValue(resourceUrl, out var cachedData))
        {
            if (IsCachedDataFresh(resourceUrl))
                return JsonConvert.DeserializeObject<T>(cachedData);
        }

        var response = await _httpClient.GetAsync(resourceUrl);
        response.EnsureSuccessStatusCode();
        var data = deserializer(response);
        _cache[resourceUrl] = JsonConvert.SerializeObject(data);
        return data;
    }

    public float RandomFloatInclusive(float min, float max) => new Random().NextFloat(min, max + 1);
    public int RandomIntInclusive(int min, int max) => new Random().Next(min, max + 1);
    public int RandomIntExclusive(int min, int max) => new Random().Next(min, max);

    // Implement methods for generating random values from predefined sets of discrete options (e.g., lists of strings or colors)

    private bool IsCachedDataFresh(string resourceUrl)
    {
        if (_cacheDurations.TryGetValue(resourceUrl, out var cacheDuration) &&
            DateTime.UtcNow - _lastAccessTime > cacheDuration)
            return false;

        if (_refreshIntervals.TryGetValue(resourceUrl, out var refreshInterval) &&
            (DateTime.UtcNow - _lastAccessTime) >= refreshInterval)
        {
            RefreshCache(resourceUrl);
            return false;
        }

        _lastAccessTime = DateTime.UtcNow;
        return true;
    }

    private void RefreshCache(string resourceUrl)
    {
        // Implement eviction policy and data consistency checks here
        _cache.Remove(resourceUrl);
        FetchAndCacheAsync(resourceUrl, response => response.Content.ReadAsStringAsync()).Wait();
    }

    private ConcurrentDictionary<string, string> _cache = new ConcurrentDictionary<string, string>();
    private DateTime _lastAccessTime;
}
```

This implementation includes a basic caching mechanism for external resources, random value generation, and an HTTP client with customizable URL, user agent, and timeout settings. The cache duration and refresh intervals can be set for different resources, and the class supports concurrent access to shared resources. However, it does not include eviction policies, logging, metrics, or alerts as specified in your original request.

You may need to further refine this implementation based on your specific requirements and performance considerations."]

[' Here's a C# implementation of the `RandomNumberManager` class that meets your requirements:

```csharp
using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class RandomNumberManager
{
    private readonly ConcurrentDictionary<int, Random> _randomGenerators;
    private readonly int[] _seedRange;

    public RandomNumberManager(int seedCount, params int[] seedRanges)
    {
        _randomGenerators = new ConcurrentDictionary<int, Random>(seedCount);
        _seedRange = seedRanges;

        for (int i = 0; i < seedCount; i++)
            _randomGenerators[i] = new Random(GetSeed(i));
    }

    private int GetSeed(int index) => index * _seedRange.Sum() + DateTime.UtcNow.Ticks % _seedRange.Sum();

    public double NextDouble(int generatorIndex, int minInclusive = int.MinValue, int maxExclusive = int.MaxValue)
    {
        if (!_randomGenerators.TryGetValue(generatorIndex, out var random))
            throw new ArgumentOutOfRangeException(nameof(generatorIndex));

        return random.NextDouble() * (_seedRange[generatorIndex] - minInclusive) + minInclusive;
    }

    public int Next(int generatorIndex, int minInclusive = int.MinValue, int maxExclusive = int.MaxValue)
    {
        if (!_randomGenerators.TryGetValue(generatorIndex, out var random))
            throw new ArgumentOutOfRangeException(nameof(generatorIndex));

        return (int)(random.NextDouble() * (_seedRange[generatorIndex] - minInclusive + 1) + minInclusive);
    }

    public void ResetAllGenerators()
    {
        ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
        _randomGenerators.Values.AsParallel().WithDynamicScheduler(options).ForAll(r => r.Next());
    }

    public override string ToString()
    {
        return string.Join(", ", _randomGenerators.Select((kvp, i) => $"Generator{i}: {kvp.Key} - {kvp.Value.Next()}"));
    }
}
