struct DnsError {
    enum class Type { Success, InvalidIp, DnsError, Timeout, Other };
    Type type;
};

std::vector<u_char> resolve(const std::string& hostname) {
    try {
        boost::asio::io_context io_context;
        boost::asio::ip::udp resolver(io_context);
        boost::asio::ip::udp::resolver::query query(hostname, "");
        boost::asio::ip::udp::endpoint endpoint;

        auto results = resolver.resolve(query);

        if (results.begin() == results.end()) {
            throw DnsError{DnsError::Type::DnsError};
        }

        auto it = results.begin();
        endpoint = *it++;

        std::vector<u_char> ip(endpoint.data(), endpoint.data() + endpoint.size());
        return ip;
    } catch (const std::exception& e) {
        std::cerr << "DNS resolution failed: " << e.what() << '\n';
        throw DnsError{DnsError::Type::Other};
    }
}

DnsError deserialize(const std::vector<u_char>& data, std::string& ip) {
    try {
        auto address = inet_ntop(AF_INET, &data[0], ip.data(), sizeof(ip.data()));
        if (!address) {
            throw DnsError{DnsError::Type::InvalidIp};
        }
        return DnsError{DnsError::Type::Success};
    } catch (const std::exception& e) {
        std::cerr << "Deserialization failed: " << e.what() << '\n';
        throw DnsError{DnsError::Type::Other};
    }
}
