#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <chrono>
#include <random>
#include <fstream>
#include <stdexcept>

struct Record {
    long timestamp;
    std::string message;
};

struct DataContainer {
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<Record> records;
};

DataContainer* create_data(unsigned int n, unsigned int max_message_length) {
    auto now = std::chrono::system_clock::now().time_since_epoch().count();
    std::default_random_engine generator;
    std::uniform_int_distribution<long> offset_dist(0, n - 1);
    std::uniform_int_distribution<int> key_dist(0, INT32_MAX);
    std::uniform_int_distribution<unsigned int> message_dist(0, max_message_length - 1);

    DataContainer* data = new DataContainer();

    try {
        data->offsets.resize(n);
        data->keys.resize(n);
        data->records.resize(n);

        for (unsigned int i = 0; i < n; ++i) {
            data->offsets[i] = offset_dist(generator);
            data->keys[i] = key_dist(generator);

            std::stringstream ss;
            ss << now + data->offsets[i];
            auto message = ss.str();
            if (message.length() > max_message_length) {
                message.resize(max_message_length - 1);
            }
            data->records[i].timestamp = now + data->offsets[i];
            data->records[i].message = message;
        }
    } catch (...) {
        delete data;
        throw std::runtime_error("Failed to allocate memory");
    }

    return data;
}
```

