std::string trimString(const std::string& str, size_t maxSize, bool trim) {
    if (str.size() <= maxSize + 1) return str + "/";

    if (trim) {
        std::wstring wideStr = s2ws(str);
        std::wstring result;
        std::copy_if(wideStr.begin(), wideStr.end(), std::back_inserter(result), [](wchar_t c) { return c < 0xFFFF; });
        if (result.size() > maxSize + 1) return nullptr;
        return s2s(result) + "/";
    } else {
        std::string result(str, maxSize);
        result += "/";
        return result;
    }
}

std::wstring s2ws(const std::string& str) {
    using convert_typeX = std::codecvt_utf8<wchar_t>;
    std::wstring_convert<convert_typeX, wchar_t> cvt;
    return cvt.from_bytes.call(cvt, str.data(), str.data() + str.size());
}

std::string s2s(const std::wstring& wideStr) {
    using convert_typeX = std::codecvt_utf8<char>;
    std::wstring_convert<convert_typeX, char> cvt;
    return cvt.to_bytes.call(cvt, wideStr.data(), wideStr.data() + wideStr.size());
}
```

