        EVP_DigestInit_ex(&pdus[i].md_ctx, NULL);
        EVP_DigestUpdate(&pdus[i].md_ctx, &pdus[i], sizeof(PDU_T));
        EVP_DigestFinal(&pdus[i].md_ctx, md5, NULL); // MD5 digest
        EVP_DigestInit_ex(&pdus[i].md_ctx, NULL);
        EVP_DigestUpdate(&pdus[i].md_ctx, &pdus[i], sizeof(PDU_T));
        EVP_DigestFinal(&pdus[i].md_ctx, sha1, NULL); // SHA1 digest
        EVP_DigestInit_ex(&pdus[i].md_ctx, NULL);
        EVP_DigestUpdate(&pdus[i].md_ctx, &pdus[i], sizeof(PDU_T));
        EVP_DigestFinal(&pdus[i].md_ctx, sha256, NULL); // SHA256 digest
        HMAC_Final(&pdus[i].hmac_ctx, hmac, NULL); // HMAC with SHA256 and RSA key
