#include <time.h>

typedef struct {
    uint32_t rnti;
    void* session_metadata;
} session_data_t;

typedef struct {
    uint8_t rnti[4];
    uint8_t rx_ue_information_tag[16];
    uint8_t crc_indication_rel8_tag[2];
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t session_data_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t session_data_cond = PTHREAD_COND_INITIALIZER;
static uint16_t num_sessions = 0;
session_data_t* sessions = NULL;

void generate_crcflag() {
    return rand() % 256;
}

void* generate_pdu(void* arg) {
    session_data_t* session_data = (session_data_t*)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu;

    pthread_mutex_lock(&session_data_mutex);

    memcpy(pdu.rnti, session_data->rnti, 4);
    memcpy(pdu.rx_ue_information_tag, session_data->session_metadata, 16);
    pdu.crc_indication_rel8_tag[0] = generate_crcflag();
    pdu.crc_indication_rel8_tag[1] = generate_crcflag();

    num_sessions++;
    pthread_mutex_unlock(&session_data_mutex);

    free(session_data->session_metadata);
    free(session_data);

    return NULL;
}

void add_session(uint32_t rnti, void* session_metadata) {
    pthread_t thread_id;
    session_data_t* new_session = (session_data_t*)malloc(sizeof(session_data_t));
    new_session->rnti = rnti;
    new_session->session_metadata = session_metadata;

    pthread_mutex_lock(&session_data_mutex);
    sessions = realloc(sessions, sizeof(session_data_t) * (num_sessions + 1));
    sessions[num_sessions] = new_session;
    pthread_create(&thread_id, NULL, generate_pdu, new_session);
    pthread_mutex_unlock(&session_data_mutex);
}

void remove_session(uint32_t rnti) {
    session_data_t* found = NULL;
    size_t i;

    pthread_mutex_lock(&session_data_mutex);
    for (i = 0; i < num_sessions; ++i) {
        if (sessions[i]->rnti == rnti) {
            found = sessions[i];
            break;
        }
    }

    if (found != NULL) {
        for (size_t j = i; j < num_sessions - 1; ++j) {
            sessions[j] = sessions[j + 1];
        }
        free(sessions[num_sessions - 1]);
        sessions = realloc(sessions, sizeof(session_data_t) * (num_sessions - 1));
        num_sessions--;
    }

    pthread_mutex_unlock(&session_data_mutex);
}
```

