class DynamicArray {
public:
    void add(const NetworkEventLogEntry& entry) {
        auto it = std::lower_bound(logEntries.begin(), logEntries.end(), entry,
            [](const auto& a, const auto& b) { return a.timestamp < b.timestamp; });

        if (it != logEntries.begin() && it != logEntries.end() && it->uniqueIdentifier == entry.uniqueIdentifier) {
            std::cerr << "Error: Duplicate identifier detected." << std::endl;
            return;
        }

        logEntries.insert(it, entry);
        identifiers[entry.uniqueIdentifier] = it;
    }

