    }

    void garbageCollect() {
        auto now = std::chrono::system_clock::now().time_since_epoch().count();
        for (auto it = logEntries.begin(); it != logEntries.end();) {
            if ((it->timestamp + GARBAGE_COLLECTION_INTERVAL) < now) {
                identifiers.erase(it->uniqueIdentifier);
                it = logEntries.erase(it);
            } else {
                ++it;
            }
        }
    }

    const NetworkEventLogEntry& getLatest() const {
        return logEntries.empty() ? NetworkEventLogEntry{} : *logEntries.rbegin();
    }

    void merge(const DynamicArray& other) {
        for (const auto& entry : other.logEntries) {
            add(entry);
        }
    }

private:
