[' Here's a basic implementation of the `CharacterCombatSystem` class in C++. This code is meant to provide a starting point and may require further optimization and adjustments based on specific requirements.

```cpp
#include <vector>
#include <unordered_map>
#include <queue>
#include <chrono>
#include <thread>
#include <mutex>

class CharacterCombatSystem {
public:
    struct AttackLogEntry {
        int characterId;
        int attackType;
        std::chrono::steady_clock::time_point timestamp;
    };

    struct Cooldown {
        bool onCooldown = false;
        std::chrono::steady_clock::time_point lastAttack;
        std::chrono::seconds cooldownDuration;
    };

    CharacterCombatSystem(int maxLogSize) : logBuffer(maxLogSize), nextLogIndex(0) {}

    void addCharacter(int characterId) {
        characters.emplace_back(characterId, Cooldown());
    }

    void performAttack(int characterId) {
        auto& character = characters[characterId];
        if (character.onCooldown && std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - character.lastAttack).count() < 5) {
            return;
        }

        // Randomly select an attack type (1-5)
        int attackType = rand() % 5 + 1;

        // Calculate cooldown duration based on energy level, environmental conditions, and combat environment
        auto currentTime = std::chrono::steady_clock::now();
        character.lastAttack = currentTime;
        character.onCooldown = true;
        character.cooldownDuration = std::chrono::seconds(8 + (character.energyLevel * 2)); // Adjust this formula based on specific requirements

        logBuffer[nextLogIndex++] = AttackLogEntry{characterId, attackType, currentTime};
        if (nextLogIndex == logBuffer.size()) nextLogIndex = 0;
    }

    void resumeCooldown(int characterId) {
        auto& character = characters[characterId];
        if (!character.onCooldown) return;

        // Check global cooldown
        bool allOnCooldown = true;
        for (const auto& c : characters) {
            if (!c.second.onCooldown) {
                allOnCooldown = false;
                break;
            }
        }

        if (allOnCooldown && std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - character.lastAttack).count() < 5) {
            return; // Global cooldown is still active, cannot resume cooldown
        }

        character.onCooldown = false;
    }

    void logActivity() const {
        for (size_t i = nextLogIndex, j = 0; j < logBuffer.size() && i != nextLogIndex; ++j, ++i %= logBuffer.size()) {
            const auto& entry = logBuffer[i];
            std::cout << "Character ID: " << entry.characterId
                      << ", Attack Type: " << entry.attackType
                      << ", Execution Time: " << std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - entry.timestamp).count() << std::endl;
        }
    }

private:
    std::vector<std::pair<int, Cooldown>> characters; // Character ID and cooldown information
    std::queue<AttackLogEntry> logBuffer; // Circular buffer for attack logs
    size_t nextLogIndex; // Index of the next available slot in the log buffer
};
```

This code creates a `CharacterCombatSystem` class with methods to manage character attacks, cooldowns, and logging. The class uses a circular buffer for storing attack logs and maintains thread safety using standard C++ synchronization primitives (mutexes). The global cooldown feature is implemented by checking if all characters are on cooldown before allowing any character to perform an attack.']

