```cpp
#include <iostream>
#include <vector>
#include <random>
#include <mutex>
#include <unordered_map>
#include <chrono>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct CRC_INDICATION_REL8_TAG {
        bool CRCFLAG;
    } crcIndicationRel8Tag;
};

std::unordered_map<uint32_t, std::vector<NFAPI_CRC_INDICATION_PDU_T>> pduLists;
std::mutex pduListsMutex;
std::unordered_map<uint16_0, bool> activeCellContexts;
std::unordered_map<uint32_t, std::vector<NFAPI_CRC_INDICATION_PDU_T>> pduListCache;
std::mutex pduListCacheMutex;
std::unordered_map<uint16_0, std::chrono::system_clock::time_point> lastRNTIUpdate;
std::mutex rntiUpdateMutex;

void updatePduList(uint32_t frequencyBand, NFAPI_CRC_INDICATION_PDU_T pdu) {
    std::lock_guard<std::mutex> lock(pduListsMutex);

    if (activeCellContexts.find(pdu.RNTI) != activeCellContexts.end() &&
        pdu.RNTI >= 128 && pdu.RNTI <= 511) {

        pdu.crcIndicationRel8Tag.CRCFLAG = rand() % 2;

        if (pduListCache.find(frequencyBand) == pduListCache.end()) {
            pduListCache[frequencyBand] = std::vector<NFAPI_CRC_INDICATION_PDU_T>();
        }

        auto it = pduListCache[frequencyBand].end();
        it = std::prev(it);

        if (it != pduListCache[frequencyBand].begin()) {
            it->crcIndicationRel8Tag.CRCFLAG = pdu.crcIndicationRel8Tag.CRCFLAG;
        }

        pduLists[frequencyBand].push_back(pdu);
    } else {
        std::cout << "Invalid PDU structure generated: RNTI out of range or inactive cell context" << std::endl;
    }
}

NFAPI_CRC_INDICATION_PDU_T getPduFromList(uint32_t frequencyBand, uint16_t rnti) {
    std::lock_guard<std::mutex> lock(pduListsMutex);

    if (activeCellContexts.find(rnti) != activeCellContexts.end() && pduLists.find(frequencyBand) != pduLists.end()) {
        auto it = std::find_if(pduLists[frequencyBand].begin(), pduLists[frequencyBand].end(),
                               [rnti](const NFAPI_CRC_INDICATION_PDU_T& pdu) { return pdu.RNTI == rnti; });
        if (it != pduLists[frequencyBand].end()) {
