void init_data_structures(int* offsets, int* keys, record** records, int num_records, int max_offset, int max_key, int max_value, size_t max_string_len, const char* METADATA) {
    pthread_t threads[num_records];
    record* records_array = calloc(num_records, sizeof(record));
    if (!records_array) {
        fprintf(stderr, "Failed to allocate memory for records array.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; ++i) {
        records_array[i].metadata = NULL;
        records[i] = &records_array[i];
        pthread_create(&threads[i], NULL, init_record, &records_array[i]);
    }

    for (int i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Initialize offsets and keys arrays
    offsets[0] = 0;
    keys[0] = 1;

    for (int i = 1; i < num_records; ++i) {
        while (offsets[i - 1] + max_offset >= max_key) {
            keys[i] = keys[i - 1] + 1;
        }
        offsets[i] = offsets[i - 1] + 1;
    }

    free(records_array);
}

void cleanup() {
    for (int i = 0; i < num_records; ++i) {
        if (records[i]->metadata) {
