            element = static_cast<NFAPI_CRUC_INDICATION_PDU_T*>(element->link.raw());
        }

        if (element->infoTag.rnti == infoTag.rnti) {
            return false; // Duplicate RNTI found
        }

        std::memcpy(element, &infoTag, sizeof(RX_UE_INFORMATION_TAG));
        return true;
    }

