u_char* resolve_ip(const char* hostname) {
    dns_resolver_t* resolver = dns_resolver_init();
    if (!resolver) return NULL; // Initialization failure

    dns_query_t* query = dns_resolver_query(resolver, hostname, DNS_TYPE_A);
    if (!query) {
        dns_resolver_free(resolver);
        return NULL; // Query failure
    }

    dns_response_t* response = dns_resolver_poll(resolver, query, 5000); // Poll for response within 5 seconds
    if (!response) {
        dns_query_free(query);
        dns_resolver_free(resolver);
        return NULL; // Timeout or other network issues
    }

    dns_answer_t* answer = dns_response_find_first_answer(response, DNS_TYPE_A);
    if (!answer) {
        dns_response_free(response);
        dns_query_free(query);
        dns_resolver_free(resolver);
        return NULL; // No A record found
    }

    u_char* ip = malloc(sizeof(u_char) * 4);
    if (!ip) {
        dns_answer_free(answer);
        dns_response_free(response);
        dns_query_free(query);
        dns_resolver_free(resolver);
        return NULL; // Allocation failure
