Node* head = NULL;
unsigned int capacity = 0;

void resize(unsigned int new_capacity) {
    Node* temp = head;
    head = NULL;
    capacity = new_capacity;

    for (unsigned int i = 0; i < new_capacity && temp != NULL; ++i) {
        Node* node = malloc(sizeof(Node));
        if (!node) break;
        node->data = temp->data;
        node->next = NULL;
        if (!head) head = node;
        else tail()->next = node;
        temp = temp->next;
    }
}

void push(const NFAPI_CRC_INDICATION_PDU_T& data) {
    if (capacity == 0) resize(16);

    Node* node = malloc(sizeof(Node));
    if (!node) return;

    node->data = data;
    node->next = NULL;

    if (!head) head = node;
    else tail()->next = node;
    capacity++;
}

Node* pop() {
    if (capacity == 0) return NULL;

    Node* temp = head;
    head = head->next;
    capacity--;
    return temp;
}

Node* tail() {
    Node* current = head;
    while (current && current->next != NULL) current = current->next;
    return current;
}
