```python
import os
import sys
import hashlib
from functools import lru_cache

class FileIntegrityError(Exception):
    pass

def md5_file(file_path, chunk_size=65536):
    file_size = os.path.getsize(file_path)
    hasher = hashlib.md5()

    def update_hasher(chunk):
        if file_size is not None:
            nonlocal file_size
            file_size -= len(chunk)
        hasher.update(chunk)

    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(min(chunk_size, file_size))
            if not chunk:
                break
            update_hasher(chunk)

    if file_size is None or file_size == os.path.getsize(file_path):
        return hasher.hexdigest()
    else:
        raise FileIntegrityError("File was truncated or altered during the hashing process.")

@lru_cache(maxsize=None)
def get_file_size(file_path):
    try:
        return os.path.getsize(file_path)
    except (OSError, IOError) as e:
        if e.errno == 2:  # No such file or directory
            raise FileNotFoundError(f"File {file_path} not found.")
        else:
            raise e
```

