class ListManager {
public:
    ListManager(size_t maxMemory, size_t elementSize) : _maxMemory(maxMemory), _elementSize(elementSize), _elements(), _evictionPolicy() {}

    void setEvictionPolicy(std::function<void(const NFAPI_CRC_INDICATION_PDU_T&)> evictionPolicy) {
        _evictionPolicy = std::move(evictionPolicy);
    }

