```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <malloc.h>
#include <string.h>
#include <inttypes.h>

typedef struct {
    void* data;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_T_MEM_MANAGER;

NFAPI_CRC_INDICATION_PDU_T_MEM_MANAGER* create_mem_manager(size_t size) {
    NFAPI_CRC_INDICATION_PDU_T_MEM_MANAGER* manager = (NFAPI_CRC_INDICATION_PDU_T_MEM_MANAGER*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T_MEM_MANAGER));
    if (!manager) {
        perror("malloc");
        return NULL;
    }

    manager->data = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->data) {
        perror("calloc");
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->size = size;

    return manager;
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(NFAPI_CRC_INDICATION_PDU_T_MEM_MANAGER* manager) {
    pthread_mutex_lock(&manager->lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*) ((char*)manager->data + manager->allocated * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->allocated++;
    pthread_mutex_unlock(&manager->lock);

    return pdu;
}

void release_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, NFAPI_CRC_INDICATION_PDU_T_MEM_MANAGER* manager) {
    pthread_mutex_lock(&manager->lock);
    if (--manager->allocated == 0) {
        free(manager->data);
        free(manager);
    }
    pthread_mutex_unlock(&manager->lock);
}
```

