struct data_entry {
    double timestamp;
    uint32_t identifier;
};

class DataManager {
public:
    void insert(const data_entry& entry) {
        std::unique_lock<std::mutex> lock(m_);
        data_.emplace_back(entry);
        sortData();
    }

    const data_entry* findLatest() const {
        std::unique_lock<std::mutex> lock(m_);
        if (data_.empty()) return nullptr;
        return &data_.back();
    }

private:
    void sortData() {
        auto it = data_.begin();
        for (auto jt = ++it; jt != data_.end(); ) {
            if (it->timestamp > jt->timestamp) {
                std::iter_swap(it, jt);
                it = jt;
            } else {
                ++it;
            }
        }
    }

    std::vector<data_entry> data_;
    std::mutex m_;
};

class DataFlusher {
public:
    DataFlusher(DataManager& manager, int retentionSeconds, const std::string& storageBackend)
        : manager_(manager), retention_(retensionSeconds * 1000), storageBackend_(storageBackend) {}

    void start() {
        thread_ = std::thread([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(manager_.m_);
                auto now = std::chrono::steady_clock::now();
                auto it = data_.begin();
                for (auto jt = ++it; jt != data_.end(); ) {
                    if ((now - jt->timestamp.time_since_epoch()) > retention_) {
                        flush(jt);
                        data_.erase(jt++);
                    } else {
                        break;
                    }
                }
                lock.unlock();
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        });
    }

private:
