        // Implement flushing logic based on the chosen storageBackend_
    }

    DataManager& manager_;
    int retention_;
    std::string storageBackend_;
    boost::lockfree::slist<data_entry> data_;
    std::thread thread_;
};

int main() {
    DataManager manager;
    DataFlusher flusher(manager, 60, "file"); // Set retention period to 1 minute and choose file storage backend
    flusher.start();

    // Simulate concurrent access from multiple threads
    std::vector<std::thread> threads;
    for (size_t i = 0; i < 10; ++i) {
        threads.emplace_back([&]() {
            for (size_t j = 0; j < 1000; ++j) {
                manager.insert({ std::chrono::steady_clock::now().time_since_epoch().count(), i });
                std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 50 + 10));
