[' I'm providing a simplified version of the requested C function, focusing on the core requirements. For a complete implementation, you would need to consider additional factors such as error handling, logging, coordination with other components, and integration with external storage solutions.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
} ListNode;

typedef struct list {
    ListNode* head;
    ListNode* tail;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} List;

List* list_create(size_t initial_capacity) {
    List* list = malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->not_full, NULL);
    pthread_cond_init(&list->not_empty, NULL);

    return list;
}

void list_destroy(List* list) {
    if (!list) return;

    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->not_full);
    pthread_cond_destroy(&list->not_empty);
    free(list);
}

void list_resize(List* list, size_t new_capacity) {
    if (new_capacity <= list->size) return;

    ListNode** nodes = realloc(list->head, sizeof(ListNode*) * new_capacity);
    if (!nodes) return;

    list->capacity = new_capacity;
    list->head = nodes;
}

int list_push(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= list->capacity) return -1; // List is full

    pthread_mutex_lock(&list->lock);

    while (list->size == list->capacity && list->head != list->tail) {
        pthread_cond_wait(&list->not_empty, &list->lock);
    }

    ListNode* new_node = malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    new_node->data = data;
    new_node->next = NULL;

    if (list->tail) list->tail->next = new_node;
    else list->head = new_node;
    list->tail = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    pthread_cond_signal(&list->not_full);

    return 0; // Success
}

void list_log(List* list) {
    printf("List size: %zu\n", list->size);
    ListNode* current = list->head;
    for (size_t i = 0; i < list->size && current; ++i, current = current->next) {
        printf("Element %zu:\n", i);
        printf("\tTag: %d\n", current->data.tag);
        printf("\tRNTI: %d\n", current->data.rnti);
        printf("\tCRC_INDICATION_REL8_TAG: %d\n", current->data.crc_indication);
        printf("\tCRCFLAG: %d\n", current->data.crcflag);
    }
}
```

