```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <cstdlib>
#include <ctime>
#include <pthread.h>
#include <atomic>

struct RNTI { std::atomic<uint32_t> value = 1; };

struct CRC_INDICATION_REL8_TAG {
    uint32_t crcFlag;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    RNTI rnti;
    CRC_INDICATION_REL8_TAG tag;
};

class LinkedList {
public:
    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> list;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    void allocate(size_t count) {
        for (size_t i = 0; i < count; ++i) {
            std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> pdu(new NFAPI_CRC_INDICATION_PDU_T);
            pdu->rnti.value = list.size() + 1;
            pdu->tag.crcFlag = rand() % 2;
            {
                pthread_mutex_lock(&mutex);
                list.push_back(std::move(pdu));
            }
        }
    }

    void deallocate() {
        for (auto& pdu : list) {
            pdu.reset();
        }
        list.clear();
    }
};
