class TextProcessor {
public:
    void process(const std::string& inputFile, const std::string& outputFile, bool caseSensitive) {
        std::ifstream ifs(inputFile, std::ios::binary);
        if (!ifs) {
            std::cerr << "Error opening file: " << inputFile << '\n';
            return;
        }

        std::ofstream ofs(outputFile, std::ios::binary | std::ios::trunc);
        if (!ofs) {
            std::cerr << "Error creating output file: " << outputFile << '\n';
            return;
        }

        uint64_t totalBytes = getFileSize(inputFile);
        const double maxMemoryUsage = 0.25 * getTotalPhysicalMemory();
        const size_t bufferSize = std::min(totalBytes, maxMemoryUsage * (1024 * 1024)); // Limit to 256 MB

        boost::iostreams::mapped_file_source mappedSource(inputFile.c_str(), totalBytes, O_RDONLY);
        boost::iostreams::filtering_streambuf<boost::iostreams::input> inputStreamBuf;
        inputStreamBuf.push(boost::iostreams::gzip_decompressor());
        inputStreamBuf.push(boost::iostreams::raw_source(&mappedSource));

        std::string line;
        uint64_t linesCount = 0;
        MD5_CTX ctx;
        MD5_Init(&ctx);

        while (getline(inputStreamBuf, line, '\n')) {
            if (!caseSensitive) {
                std::transform(line.begin(), line.end(), line.begin(), ::tolower);
            }

            ++linesCount;
            MD5_Update(&ctx, line.data(), line.size());
        }

        ofs << linesCount << '\n'; // Write the number of lines to the output file
        ofs << MD5_Final(static_cast<unsigned char*>(md5Sum), &ctx); // Write the MD5 hash to the output file
    }

private:
    uint64_t getFileSize(const std::string& path) {
        struct stat st;
        if (stat(path.c_str(), &st) == -1) {
            throw boost::system_error{errno, boost::system_category(), "Error getting file size"};
        }
        return st.st_size;
    }

    uint64_t getTotalPhysicalMemory() {
        // Implement a method to get total physical memory in bytes
        // This is platform-specific and may require additional libraries or system calls
    }

    std::vector<uint8_t> md5Sum;
};

int main(int argc, char* argv[]) {
    TextProcessor processor;

    if (argc < 4) {
        std::cout << "Usage: " << argv[0] << " inputFile outputFile [caseSensitive] [outputRedirection]\n";
        return 1;
    }

    std::string inputFile = argv[1];
    std::string outputFile = argv[2];
    bool caseSensitive = argc >= 4 && atoi(argv[3]) == 1;
    bool outputRedirection = argc >= 5 && strcmp(argv[4], ">") == 0;

    if (outputRedirection) {
        std::ofstream ofs(outputFile, std::ios::trunc);
        if (!ofs) {
            std::cerr << "Error creating output file: " << outputFile << '\n';
            return 1;
        }
        std::cout.rdbuf()->swap(ofs.rdbuf());
    }

    try {
        processor.process(inputFile, outputFile, caseSensitive);
    } catch (const boost::system_error& e) {
        std::cerr << "Error: " << e.what() << '\n';
        return 1;
    }

    if (outputRedirection) {
        std::cout.rdbuf()->swap(std::cin.rdbuf()); // Restore original output stream
    }

    return 0;
}
```

