// Custom memory pool structure
typedef struct {
    void *pool;
    size_t size;
    size_t allocated;
    size_t free;
} MemoryPool;

MemoryPool create_memory_pool(size_t size, size_t num_elements) {
    MemoryPool pool = {NULL, size, 0, num_elements * size};
    pool.pool = mmap(NULL, pool.size * num_elements, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool.pool == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    return pool;
}

void *allocate_from_pool(MemoryPool *pool) {
    if (pool->free > 0) {
        void *ptr = pool->pool + pool->allocated - pool->free;
        pool->free--;
        return ptr;
    } else {
        void *ptr = realloc(pool->pool, pool->size * (pool->allocated + 1));
        if (!ptr) {
            perror("realloc failed");
            exit(EXIT_FAILURE);
        }
        pool->size *= 2;
        pool->pool = ptr;
        return pool->pool + pool->allocated++;
    }
}

void free_to_pool(MemoryPool *pool, void *ptr) {
    pool->free++;
    memset(ptr, 0, pool->size);
}

