[' Here's a C function that meets the requirements you've outlined, using standard library functions and adhering to best practices in memory management. I'll provide comments explaining each step of the process.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <stdbool.h>

// Define necessary structures and constants
typedef struct {
    int value;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    NFAPI_RX_UE_INFORMATION_TAG tag;
} record;

typedef enum { MIN_RNTI = 1, MAX_RNTI = 9999 } RNTI_RANGE;

// Function to generate a unique random RNTI within the specified range
uint32_t generateUniqueRNTI(uint32_t* used_rntis, size_t num_used) {
    uint32_t rnti;
    do {
        rnti = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
    } while (binary_search(used_rntis, num_used, rnti) != -1);
    used_rntis[num_used] = rnti;
    return rnti;
}

// Binary search function for finding an element in a sorted array
int binary_search(uint32_t* arr, size_t n, uint32_t x) {
    int l = 0, r = n - 1, mid;
    while (l <= r) {
        mid = l + (r - l) / 2;
        if (arr[mid] == x) return mid;
        if (arr[mid] < x) l = mid + 1;
        else r = mid - 1;
    }
    return -1;
}

// Function to dynamically allocate memory for the arrays and initialize them
record** initArrays(size_t* offsets_len, size_t* keys_len, size_t* records_len, size_t* rntis_len) {
    record** records = malloc(*records_len * sizeof(record*));
    if (!records) {
        fprintf(stderr, "Memory allocation for records failed\n");
        exit(EXIT_FAILURE);
    }

    long* offsets = malloc(*offsets_len * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation for offsets failed\n");
        free(records);
        exit(EXIT_FAILURE);
    }

    int* keys = malloc(*keys_len * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation for keys failed\n");
        free(offsets);
        free(records);
        exit(EXIT_FAILURE);
    }

    uint32_t* rntis = malloc(*rntis_len * sizeof(uint32_t));
    if (!rntis) {
        fprintf(stderr, "Memory allocation for RNTIs failed\n");
        free(keys);
        free(offsets);
        free(records);
        exit(EXIT_FAILURE);
    }

    // Initialize RNTI array with unique values within the specified range
    size_t num_used_rntis = 0;
    for (size_t i = 0; i < *rntis_len; ++i) {
        rntis[i] = generateUniqueRNTI(rntis, num_used_rntis);
    }

    return records;
}

// Cleanup function to free all allocated memory when no longer needed
void cleanup(record** records, long* offsets, int* keys, uint32_t* rntis, size_t offsets_len, size_t keys_len, size_t records_len, size_t rntis_len) {
    free(offsets);
    free(keys);
    for (size_t i = 0; i < records_len; ++i) {
        free(records[i]);
    }
    free(records);
    free(rntis);
}
```

This code defines a function `initArrays()` that dynamically allocates memory for the arrays and initializes them. The RNTI identifiers are generated uniquely within the specified range using the `generateUniqueRNTI()` function. A binary search function `binary_search()` is provided to find an element in a sorted array efficiently.

The cleanup function `cleanup()` frees all allocated memory when no longer needed. It's important to note that this example does not handle external data sources or partial data loads, as those requirements were not explicitly stated in the original task description.

Regarding performance implications, using arrays for small to medium-sized datasets is generally more efficient than linked lists due to their constant time complexity for accessing elements (O(1)). However, when dealing with large datasets, linked lists may be more suitable as they can handle dynamic resizing and avoid the need for reallocating memory frequently.

In this example, I've used arrays for simplicity and efficiency, but you could modify the code to use linked lists if needed by replacing the array declarations with appropriate data structures and adjusting the `generateUniqueRNTI()` function accordingly.']

