    std::vector<int> tags;
};

std::mutex mtx; // Mutex for thread safety
std::unordered_map<int, std::list<NetworkEvent>> eventList; // Hash table to store events

void addEvent(const NetworkEvent& event) {
    std::unique_lock<std::mutex> lock(mtx);
    eventList[event.ueId].emplace_back(event);
}

std::list<NetworkEvent> getEventsByUeId(int ueId, std::chrono::steady_clock::time_point startTime, std::chrono::steady_clock::time_point endTime) {
    std::list<NetworkEvent> result;
    std::unique_lock<std::mutex> lock(mtx);

    for (auto& event : eventList[ueId]) {
        if (event.timestamp >= startTime && event.timestamp <= endTime) {
