int processMediaFilesAndGenerateReports(const char* input_files_path, const char* output_reports_path, const char* config_path) {
    json_t* config = load_config(config_path);

    // Load and validate all media files
    int num_files = 0;
    media_file_t** files = malloc(sizeof(media_file_t*) * MAX_FILES);
    for (int i = 0; i < MAX_FILES; ++i) {
        char path[MAX_PATH];
        snprintf(path, sizeof(path), "%s/%d", input_files_path, i);
        if (!access(path, F_OK)) {
            files[num_files] = load_media_file(path);
            validate_media_file(path, config);
            ++num_files;
        }
    }

    // Process valid media files concurrently using threads
    pthread_t threads[num_files];
    for (int i = 0; i < num_files; ++i) {
        if (files[i]) {
            create_structures(files[i], config);
            pthread_create(&threads[i], NULL, convert_to_pdf, files[i]);
        }
    }

    // Wait for all threads to finish and handle errors
    int failed_conversions = 0;
    for (int i = 0; i < num_files; ++i) {
        if (files[i]) {
            pthread_join(threads[i], NULL);
            if (pthread_errno != 0) {
                failed_conversions++;
            }
        }
    }

    // Generate report and free memory
    json_t* results = json_object();
    json_array_append_new(results, json_integer(num_files));
    json_array_append_new(results, json_integer(num_files - failed_conversions));
    // ... add more details to the report
    generate_report(results);

    for (int i = 0; i < num_files; ++i) {
        if (files[i]) {
            free(files[i]->path);
            fclose(files[i]->file);
            free(files[i]->structures);
            free(files[i]);
        }
    }
    free(files);

    // Return 0 if all input files are successfully processed and converted, or if no files were processed due to validation failures.
    return failed_conversions > 0 ? 1 : 0;
}
```

