```cpp
#include <vector>
#include <algorithm>
#include <cstdint>
#include <random>
#include <stdexcept>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

constexpr uint32_t MIN_RNTI = 1;
constexpr uint32_t MAX_RNTI = 65535;

std::vector<NFAPI_CRC_INDICATION_PDU_T> createList(uint32_t n, bool sortByRNTI) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> list;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(MIN_RNTI, MAX_RNTI);

    for (uint32_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rnti = dis(gen);
        pdu.crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG
        list.emplace_back(pdu);
    }

    if (sortByRNTI) {
        std::sort(list.begin(), list.end(), [](const auto& a, const auto& b) { return a.rnti < b.rnti; });
    }

    return list;
}
```

