    std::map<std::string, std::vector<int>> operationalParameters; // key: parameter name, value: vector of power levels or modulation schemes
};

class MACList {
public:
    void initialize() {
        entities.reserve(100);
    }

    MACEntity& getEntity(const std::string& id) {
        auto it = entities.find(id);
        if (it != entities.end()) return it->second;
        entities.emplace_back();
        it = entities.rbegin();
        it->first = id;
        return it->second;
    }

    void updateOperationalParameters(const std::string& id, const std::map<std::string, std::vector<int>>& newParams) {
        auto it = entities.find(id);
        if (it != entities.end()) {
            it->second.operationalParameters = newParams;
        } else {
            // Handle missing entity case
        }
    }

private:
    std::vector<MACEntity> entities;
    boost::lockfree::queue<std::pair<std::string, std::map<std::string, std::vector<int>>>> updatesQueue;
    boost::asio::io_service ioService;
    boost::asio::strand strand(ioService);

    void processUpdates() {
        while (true) {
            auto update = updatesQueue.pop();
            if (!update.first.empty()) {
                auto it = std::find_if(entities.begin(), entities.end(), [&](const MACEntity& entity) { return entity.id == update.first; });
                if (it != entities.end()) {
                    it->operationalParameters = update.second;
                } else {
                    // Handle missing entity case
                }
            }
        }
    }
};
