impl NFAPIRequest {
    async fn send(&self, pdu: &NFAPI_CRC_INDICATION_PDU_T) -> Result<(), reqwest::Error> {
        let mut request = self.client.post(self.url.as_str()).body(format!("{}", pdu));
        for _ in 0..self.max_retries {
