    const privateKey = fs.readFileSync(path.join(__dirname, 'private_key.pem'));
    const certificate = fs.readFileSync(path.join(__dirname, 'certificate.pem'));

    const auth = new Buffer.allocUnsafe(64);
    crypto.randomFill(auth);

    const params = {
        client_id: 'your_client_id',
        scope: 'your_scope',
        auth,
    };

    const query = util.format(
        '?%s=%s&%s=%s&%s=%s',
        url.parse(options.path).search ? url.parse(options.path).search.slice(1) : '',
        params.client_id,
        'scope',
        params.scope,
        'auth',
        auth.toString('base64')
    );

    const oauthRequestOptions = {
        ...options,
        path: options.path + query,
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
        },
    };

    const oauthRequest = request(oauthRequestOptions);

    let responseData = [];
    let dataStream = new streamBuffer.Stream();
    oauthRequest.on('data', chunk => {
        dataStream.write(chunk);
        responseData.push(chunk);
    });

    oauthRequest.on('end', () => {
        const combinedResponseData = Buffer.concat(responseData);
        callback({
            pem: combinePEM(privateKey, certificate, auth),
            data: combinedResponseData,
        });
    });

    oauthRequest.on('error', error => {
        console.error(`Error during OAuth request: ${error}`);
        callback(null);
    });
}

function combinePEM(privateKey, certificate, auth) {
    const privateKeyHeader = `-----BEGIN PRIVATE KEY-----\n`;
    const privateKeyFooter = `-----END PRIVATE KEY-----`;
    const certificateHeader = `-----BEGIN CERTIFICATE-----\n`;
    const certificateFooter = `-----END CERTIFICATE-----`;
    const authHeader = `-----BEGIN OAuth AUTHORIZATION DATA-----\n`;
    const authFooter = `-----END OAuth AUTHORIZATION DATA-----`;

    let pem = privateKeyHeader + privateKey.toString('base64') + privateKeyFooter + '\n';
    pem += certificateHeader + certificate.toString('base64') + certificateFooter + '\n';
    pem += authHeader + auth.toString('base64') + authFooter;

    return pem;
}
```']

