```c
#include <openssl/aes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} record;

int processDecryptedRecords(int keyLength, unsigned char *key, unsigned char *iv, const char *encryptedData) {
    AES_KEY aesKey;
    EVP_CIPHER_CTX ctx;
    unsigned char *decryptedData = NULL;
    size_t decryptedDataLen = 0;
    int errorCode = 0;

    // Initialize Triple DES encryption context
    AES_set_encrypt_key(key, AES_BLOCK_SIZE * keyLength, &aesKey);
    EVP_CIPHER_CTX_init(&ctx);
    EVP_EncryptInit_ex(&ctx, EVP_triple_des_cbc(), NULL, &aesKey, iv, 0);

    // Decrypt encryptedData and store the result in decryptedData
    int plaintextLen = strlen(encryptedData);
    size_t ciphertextLen = (plaintextLen + AES_BLOCK_SIZE) / AES_BLOCK_SIZE * AES_BLOCK_SIZE;
    unsigned char *ciphertext = malloc(ciphertextLen);
    if (!ciphertext) {
        fprintf(stderr, "Memory allocation for ciphertext failed\n");
        return -1;
    }
    int decryptResult = 0;
    for (size_t i = 0; i < plaintextLen; ++i) {
        ciphertext[i] = (unsigned char)encryptedData[i];
    }
    EVP_CIPHER_CTX_set_padding(&ctx, 1); // PKCS#7 padding
    decryptResult = EVP_EncryptUpdate(&ctx, ciphertext + plaintextLen, &decryptedDataLen, ciphertext, plaintextLen);
    if (decryptResult != 1) {
        fprintf(stderr, "Error during encryption update\n");
        free(ciphertext);
        return -2;
    }
    decryptResult = EVP_EncryptFinal_ex(&ctx, ciphertext + plaintextLen, &decryptedDataLen);
    if (decryptResult != 1) {
        fprintf(stderr, "Error during encryption final\n");
        free(ciphertext);
        return -3;
    }
    decryptedData = realloc(ciphertext, decryptedDataLen + 1); // Add null terminator for string handling
    if (!decryptedData) {
        fprintf(stderr, "Memory allocation for decryptedData failed\n");
        free(ciphertext);
        return -4;
    }
    free(ciphertext);

    // Parse the decrypted message into integers to determine range limits
    int min = 0, max = 0;
    char *token = strtok((char *)decryptedData, ",");
    while (token != NULL) {
        int value = atoi(token);
        if (value < min || min == 0) {
            min = value;
        }
        if (value > max) {
            max = value;
        }
        token = strtok(NULL, ",");
    }

    // Allocate memory for and initialize an array of record structures
    size_t recordsCount = (max - min + 1) / 20 + 1; // Assuming each record contains 20 integers on average
    record *records = malloc(sizeof(record) * recordsCount);
    if (!records) {
        fprintf(stderr, "Memory allocation for records failed\n");
        free(decryptedData);
        return -5;
    }

    // Populate the array with random values within the specified range
    srand((unsigned int)time(NULL)); // Use current time as seed value
    char *token = strtok((char *)decryptedData, ",");
    for (size_t i = 0; token != NULL && i < recordsCount * 20; ++i) {
        int value = atoi(token);
        if (value >= min && value <= max) {
            records[i / 20].value = rand() % (max - min + 1) + min;
        }
        token = strtok(NULL, ",");
    }

    // Free memory and return the populated array of records
    free(decryptedData);
    return records;
}
```

This function decrypts the provided data, determines the range limits for generating random values, allocates memory for an array of record structures, populates it with random values within the specified range, and returns the populated array. The function handles potential errors such as memory allocation failures or invalid input formats by implementing appropriate error checking mechanisms.']

[' Here's a simplified implementation using a doubly-linked list for efficient memory allocation and deallocation, handling varying sizes of input data, and incorporating a logging mechanism. I've also included basic validation checks and null pointer exception handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct RRConnectionStatus {
    NFAPI_RRC_PDU_T rrc_pdu;
    struct RRConnectionStatus *prev, *next;
} RRConnectionStatus;

RRConnectionStatus* create_node(const NFAPI_RRC_PDU_T* rrc_pdu) {
    RRConnectionStatus* node = (RRConnectionStatus*)malloc(sizeof(RRConnectionStatus));
    if (!node) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }
    memcpy(&node->rrc_pdu, rrc_pdu, sizeof(NFAPI_RRC_PDU_T));
    node->prev = node->next = NULL;
    return node;
}

void insert_node(RRConnectionStatus** head, RRConnectionStatus* node) {
    if (!head || !node) return;

    if (*head == NULL) {
        *head = node;
        return;
    }

    node->next = *head;
    (*head)->prev = node;
    *head = node;
}

void remove_node(RRConnectionStatus** head, RRConnectionStatus* node) {
    if (!head || !(*head)) return;

    if ((*head) == node) {
        *head = (*head)->next;
        if (*head) (*head)->prev = NULL;
        free(node);
        return;
    }

    RRConnectionStatus* current = *head;
    while (current->next != node) {
        current = current->next;
        if (!current->next) break;
    }

    if (!current->next) return; // Not found

    current->next = node->next;
    if (node->next) node->next->prev = current;
    free(node);
}

void log_error(const char* message) {
    fprintf(stderr, "[Error] %s\n", message);
}

void manage_list(RRConnectionStatus** head, const NFAPI_RRC_PDU_T* data, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        RRConnectionStatus* node = create_node(&data[i]);
        if (!node) continue; // Handle out of memory errors

        insert_node(head, node);
    }
}
