    uint32_t cell_id;
    uint32_t l1_api_version;
    pthread_mutex_t lock;
} NFAPI_L1_API_CONTEXT_T;

typedef struct {
    size_t capacity;
    size_t size;
    NFAPI_L1_API_CONTEXT_T *data;
    void (*resize)(size_t new_capacity);
} DynamicArray;

void init_dynamic_array(DynamicArray *array, size_t initial_capacity, void (*resize_func)(size_t)) {
    array->capacity = initial_capacity;
    array->size = 0;
    array->data = malloc(initial_capacity * sizeof(NFAPI_L1_API_CONTEXT_T));
    if (!array->data) {
        fprintf(stderr, "Failed to allocate memory for dynamic array\n");
        exit(EXIT_FAILURE);
    }
    array->resize = resize_func;
}

void resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    NFAPI_L1_API_CONTEXT_T *new_data = realloc(array->data, new_capacity * sizeof(NFAPI_L1_API_CONTEXT_T));
    if (!new_data) {
        fprintf(stderr, "Failed to resize dynamic array\n");
        exit(EXIT_FAILURE);
    }
    array->data = new_data;
    array->capacity = new_capacity;
}

void add_context(DynamicArray *array, NFAPI_L1_API_CONTEXT_T context) {
    pthread_mutex_lock(&context.lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].ue_id == context.ue_id && array->data[i].cell_id == context.cell_id) {
            // Update existing context and unlock
            array->data[i] = context;
            pthread_mutex_unlock(&context.lock);
            return;
        }
    }

    if (array->size >= array->capacity) {
        resize_dynamic_array(array, array->capacity * 2);
    }

    // Add new context and unlock
    array->data[array->size] = context;
    array->size++;
    pthread_mutex_unlock(&context.lock);
}

void garbage_collect(DynamicArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        pthread_mutex_lock(&array->data[i].lock);
        if (!array->data[i].ue_id) { // unused context
            memmove(&array->data[i], &array->data[array->size - 1], sizeof(NFAPI_L1_API_CONTEXT_T));
            --array->size;
        }
        pthread_mutex_unlock(&array->data[i].lock);
    }
}
