Here's a simplified example of how the processing function might look like:

```java
import org.apache.commons.collections4.unionfind.DisjointSet;
import java.util.*;
import java.util.stream.Collectors;

public class DisjointPairCounter {
    private final DisjointSet<Integer> unionFind;
    private long totalTime = 0;

    public DisjointPairCounter(int[] array) {
        this.unionFind = new DisjointSet<>(array.length);
        Arrays.stream(array).forEach(element -> unionFind.makeRoot(element));
    }

    public void processPairs() {
        List<Pair> pairs = Arrays.stream(unionFind.getRoots())
                .mapToObj(root -> new Pair(root, find(root)))
                .collect(Collectors.toList());

        Collections.sort(pairs, Comparator.comparingInt(pair -> pair.sum()));

        long startTime;
        for (Pair pair : pairs) {
            startTime = System.nanoTime();
            unionFind.union(pair.first, pair.second);
            totalTime += (System.nanoTime() - startTime);
            System.out.println("Pair " + pair + ": " + ((System.nanoTime() - startTime) / 1_000_000) + " ms");
        }
    }

    private int find(int element) {
        return unionFind.find(element);
    }

    record Pair(int first, int second, int sum) {
        public Pair {
            this(first, second, first + second);
        }
    }
}
```']

