[' I'll provide a simplified C++ version of the dynamic array management with the specified requirements. Note that this is a high-level solution and may require adjustments based on specific project constraints and standards.

```cpp
#include <vector>
#include <unordered_map>
#include <mutex>
#include <stdexcept>

struct DL_FRAME_TRANSPORTBLOCK_INFO {
    DL_FRAME_TRANSPORTBLOCK_INFO_TAG tag;
    RRC_CQI_REPORT cqiReport;
    RRC_DLSCH_HARQ_PROCESS_INFO harqInfo;
};

class DynamicArray {
private:
    std::vector<DL_FRAME_TRANSPORTBLOCK_INFO> data;
    std::unordered_map<uint32_t, size_t> rntiToIndex;
    std::mutex mtx;

public:
    DynamicArray() {}

    void add(const DL_FRAME_TRANSPORTBLOCK_INFO& info, uint32_t rnti) {
        std::lock_guard<std::mutex> lock(mtx);
        data.push_back(info);
        rntiToIndex[rnti] = data.size() - 1;
    }

    bool remove(uint32_t rnti) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = rntiToIndex.find(rnti);
        if (it == rntiToIndex.end()) return false;

        data[it->second] = data.back();
        data.pop_back();
        rntiToIndex.erase(it);
        return true;
    }

    void updateCQI(uint32_t rnti, const RRC_CQI_REPORT& cqiReport) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = rntiToIndex.find(rnti);
        if (it == rntiToIndex.end()) throw std::runtime_error("RNTI not found");

        data[it->second].cqiReport = cqiReport;
    }

    const DL_FRAME_TRANSPORTBLOCK_INFO& get(uint32_t rnti) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = rntiToIndex.find(rnti);
        if (it == rntiToIndex.end()) throw std::runtime_error("RNTI not found");

        return data[it->second];
    }
};
```

