class DistributedGraph {
public:
    void addVertex(int id, double property);
    void addEdge(int src, int dest, double property);

private:
    boost::interprocess::managed_shared_memory segment;
    boost::interprocess::containers::vector<int> vertices;
    boost::interprocess::containers::vector<std::pair<int, int>> edges;
    boost::interprocess::sync::mutex mutex;

    void createSegment();
};

void DistributedGraph::createSegment() {
    segment.create_only("DistributedGraph", sizeof(int) + sizeof(double), 0644);
    vertices = segment.construct<boost::interprocess::containers::vector<int>>("vertices")(0);
    edges = segment.construct<boost::interprocess::containers::vector<std::pair<int, int>>>("edges")(0);
}

void DistributedGraph::addVertex(int id, double property) {
    boost::interprocess::scoped_lock lock(mutex);
    vertices.push_back(id);
    auto vertexData = segment.find<double>("vertexData").get();
    vertexData[vertices.size() - 1] = property;
}

void DistributedGraph::addEdge(int src, int dest, double property) {
    boost::interprocess::scoped_lock lock(mutex);
    edges.push_back({src, dest});
    auto edgeData = segment.find<double>("edgeData").get();
    edgeData[edges.size() - 1] = property;
}

