```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int key;
    int value;
} Record;

Record* create_record(int key, int value) {
    Record *record = (Record *) malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    return record;
}

void destroy_record(Record **record) {
    free(*record);
    *record = NULL;
}

int* create_offsets(unsigned int size) {
    int *offsets = (int *) malloc(sizeof(int) * (size + 1));
    for (unsigned int i = 0; i < size + 1; ++i) offsets[i] = 0;
    return offsets;
}

void destroy_offsets(int **offsets) {
    free(*offsets);
    *offsets = NULL;
}

int* create_keys(unsigned int size) {
    int *keys = (int *) malloc(sizeof(int) * size);
    for (unsigned int i = 0; i < size; ++i) keys[i] = -1;
    return keys;
}

void destroy_keys(int **keys) {
    free(*keys);
    *keys = NULL;
}

Record** create_records(unsigned int size, unsigned int record_size) {
    Record **records = (Record **) malloc(sizeof(Record *) * size);
    for (unsigned int i = 0; i < size; ++i) records[i] = NULL;
    return records;
}

void destroy_records(Record ***records, unsigned int size) {
    for (unsigned int i = 0; i < size; ++i) {
        if ((*records)[i]) destroy_record(&(*records)[i]);
    }
    free(*records);
    *records = NULL;
}

void resize(Record ***records, int **keys, int *offsets, unsigned int new_size, unsigned int record_size) {
    Record **new_records = create_records(new_size, record_size);
    for (unsigned int i = 0; i < offsets[new_size]; ++i) {
        Record *record = (*records)[offsets[i]];
        unsigned int new_index = offsets[i];
        if (new_index >= new_size) {
            printf("Error: Out of bounds while resizing\n");
            return;
        }
        new_records[new_index] = record;
        keys[record->key] = new_index;
    }
    destroy_records(records, offsets[0]);
    *records = new_records;
    for (unsigned int i = 0; i <= new_size; ++i) offsets[i] += new_size - offsets[i];
}

void init_records(Record ***records, int **keys, int *offsets, unsigned int size, unsigned int record_size, unsigned int min_value, unsigned int max_value) {
    for (unsigned int i = 0; i < size; ++i) {
        if (offsets[i] == offsets[i + 1]) {
            resize(records, keys, offsets, offsets[i + 1], record_size);
        }
        Record *record = create_record(offsets[i], rand() % (max_value - min_value + 1) + min_value);
        (*records)[offsets[i]] = record;
        keys[record->key] = offsets[i];
        offsets[i + 1]++;
    }
}

Record* find(int **keys, int key) {
    if (keys[key] == -1) return NULL;
    return (*keys)[keys[key]];
}
```

This code provides functions for creating and destroying the data structures, resizing them dynamically, initializing records with random values, and finding a record based on its key. The memory management is handled by manually allocating and freeing blocks of memory as needed.']

