[' Here's a C function that meets your requirements. I've used `struct entry` for the object structure, `json-c` library for handling JSON data from the external API, and `libcurl` for making HTTP requests. The code includes a simple LRU cache for storing file type metadata.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <json-c/json.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct {
    float value;
    char *path;
    size_t length;
} entry;

struct lru_cache {
    size_t capacity;
    size_t count;
    GHashTable *table;
};

void lru_cache_init(struct lru_cache *cache, size_t capacity) {
    cache->capacity = capacity;
    cache->count = 0;
    cache->table = g_hash_table_new_full(g_direct_hash, NULL, NULL, g_free);
}

void lru_cache_put(struct lru_cache *cache, const char *key, void *value) {
    if (cache->count >= cache->capacity) {
        char *least_recently_used = g_hash_table_min(cache->table);
        g_hash_table_remove(cache->table, least_recently_used);
        free(least_recently_used);
    }

    g_hash_table_insert(cache->table, g_strdup(key), value);
    cache->count++;
}

void *lru_cache_get(struct lru_cache *cache, const char *key) {
    return g_hash_table_lookup(cache->table, key);
}

size_t write_entry(void *ptr, size_t size, size_t nmemb, void *userdata) {
    entry *entry = userdata;
    memcpy(entry->path, ptr, size * nmemb);
    entry->length = size * nmemb;
    return size * nmemb;
}

CURLcode get_file_type_metadata(const char *url, json_object **metadata) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_entry);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &entry);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Failed to fetch metadata: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    } else {
        perror("Failed to initialize curl");
    }

    *metadata = json_tokener_parse(entry->path);
    free(entry->path);
    return res;
}

entry **create_entries(size_t num_entries, size_t seed, size_t file_types_count) {
    entry **entries = malloc(num_entries * sizeof(entry*));
    struct lru_cache cache;

    for (size_t i = 0; i < num_entries; ++i) {
        entries[i] = malloc(sizeof(entry));
        srand(seed + i);
        size_t file_type = rand() % file_types_count;
        char file_type_url[128];
        snprintf(file_type_url, sizeof(file_type_url), "http://example.com/file-metadata/%d", file_type);

        json_object *metadata = NULL;
        CURLcode res = get_file_type_metadata(file_type_url, &metadata);
        if (res != CURLE_OK) {
            perror("Failed to fetch metadata");
            continue;
        }

        json_object *extension = json_object_object_get(metadata, "extension");
        if (!extension) {
            fprintf(stderr, "Invalid metadata: missing extension\n");
            json_object_put(metadata);
            continue;
        }

        char *extension_str = json_object_get_string(extension);
        size_t extension_len = strlen(extension_str);
        entries[i]->path = malloc(extension_len + 1);
        strcpy(entries[i]->path, extension_str);
        entries[i]->length = extension_len;

        json_object *mime_type = json_object_object_get(metadata, "mime_type");
        if (mime_type) {
            lru_cache_put(&cache, extension_str, mime_type);
        } else {
            fprintf(stderr, "Invalid metadata: missing mime_type\n");
        }
    }

    lru_cache_init(&cache, 1024); // Adjust cache size as needed
    return entries;
}
```

This code creates a function `create_entries()` that takes the number of entries, seed for reproducibility, and file types count as arguments. It dynamically allocates memory for an array of `entry` objects, fetches metadata from an external API, and initializes each object with the appropriate file path, MIME type, and length. The LRU cache is used to store frequently requested file type metadata to improve performance.']

