    uint32_t RNTI;
    bool CRCFLAG;
    uint16_t CRC_INDICATION_REL8_TAG;
};

class DynamicArray {
public:
    void add(const NFAPI_L1_API_CONTEXT_T& context, const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        auto it = m_contexts.find(context.UE_ID);
        if (it != m_contexts.end()) {
            // Update existing context with new PDU
            it->second.push_back(pdu);
        } else {
            // Add new context and PDU if memory budget allows
            if (m_memoryUsage + ELEMENT_SIZE <= MAX_MEMORY) {
                m_contexts[context.UE_ID] = std::vector<NFAPI_CRC_INDICATION_PDU_T>{pdu};
                m_elements++;
                m_memoryUsage += ELEMENT_SIZE;
            } else {
                // Handle memory overflow by dropping older elements or suspending new additions
                std::cout << "Memory overflow! Dropping an element." << std::endl;
                dropOldestElement();
                m_contexts[context.UE_ID] = std::vector<NFAPI_CRC_INDICATION_PDU_T>{pdu};
            }
        }

        validateRNTI(pdu.RNTI);
    }

    void dropOldestElement() {
        // Implement an eviction policy that minimizes data loss
        if (!m_contexts.empty()) {
            auto it = m_contexts.begin();
            m_memoryUsage -= ELEMENT_SIZE;
            m_elements--;
            it->second.erase(it->second.begin());
        }
    }

private:
    void validateRNTI(uint32_t rnti) {
        if (rnti > MAX_RNTI || rnti == FALLBACK_RNTI) {
            std::cout << "Invalid RNTI value! Setting to fallback value." << std::endl;
            pdu.RNTI = FALLBACK_RNTI;
        }
    }

    std::unordered_map<uint32_t, std::vector<NFAPI_CRC_INDICATION_PDU_T>> m_contexts;
    size_t m_elements = 0;
    size_t m_memoryUsage = 0;
};
