public:
    void add(const LTE_DL_FRAME_TRANSPORTBLOCK_INFO& info) {
        std::lock_guard<std::mutex> lock(m_);
        data_.push_back(info);
    }

    bool remove(uint32_t rnti) {
        std::lock_guard<std::mutex> lock(m_);
        auto it = std::find_if(data_.begin(), data_.end(), [rnti](const auto& info) { return info.tag.rnti == rnti; });
        if (it != data_.end()) {
            data_.erase(it);
            return true;
        }
        return false;
    }

    void updateCQI(uint32_t rnti, const RRC_CQI_REPORT& newCqi) {
        std::lock_guard<std::mutex> lock(m_);
        for (auto& info : data_) {
            if (info.tag.rnti == rnti) {
                info.cqiReport = newCqi;
                break;
            }
        }
    }

    void flush() {
        std::lock_guard<std::mutex> lock(m_);
        auto now = std::chrono::system_clock::now();
        data_.remove_if([now](const auto& info) {
            return (now - info.cqiReport.timestamp) > expirationThreshold;
        });
    }

private:
    std::vector<LTE_DL_FRAME_TRANSPORTBLOCK_INFO> data_;
    std::mutex m_;
    std::chrono::seconds expirationThreshold; // configure this value as needed
};

// Implement a multi-threaded function to manage the dynamic array
void manageArray(DynamicArray& array, boost::asio::io_context& ioContext) {
    // Create a worker thread for each available CPU core
    std::vector<std::thread> workers;
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        workers.emplace_back([&array, &ioContext]() {
            ioContext.run();
        });
    }

    // Add a periodic timer to flush outdated entries
    boost::asio::steady_timer timer(ioContext, std::chrono::seconds(flushInterval));
    timer.async_wait([&array](const boost::system::error_code& ec) {
        if (!ec) {
            array.flush();
            timer.expires_at(timer.expiry() + std::chrono::seconds(flushInterval));
            timer.async_wait(ec);
        }
    });

    // Process incoming requests and add them to the dynamic array
    // ... (assuming there's a function to process requests)
}
```

This example uses Boost.Asio for multi-threading, synchronization, and timers. The `DynamicArray` class manages the data structure with locking mechanisms to ensure concurrent access safety. The `manageArray()` function creates worker threads to process incoming requests and a periodic timer to flush outdated entries.

You'll need to adapt this code to fit your specific use case, including integrating it into an existing signal processing framework, handling incoming requests, and configuring the flush interval (`flushInterval`) as needed."]

