#include <atomic>
#include <queue>
#include <condition_variable>

struct NFAPI_CRC_INDICATION_PDU_T {
    std::uint32_t RX_UE_INFORMATION_TAG;
    std::uint32_t RNTI;
    std::uint32_t CRC_INDICATION_REL8_TAG;
    std::atomic<bool> isValid{true};
};

class DataSource {
public:
    virtual NFAPI_CRC_INDICATION_PDU_T getUEInfo() = 0;
};

class CustomAllocator {
private:
    std::mutex mtx;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> freeList;
    std::queue<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> allocatedList;
    const int maxSize = 10000;

public:
    CustomAllocator() {
        for (int i = 0; i < maxSize; ++i) {
            freeList.emplace_back();
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* allocate() {
        std::unique_lock<std::mutex> lock(mtx);
        if (!freeList.empty()) {
            auto result = &freeList.back();
            freeList.pop_back();
            return result;
        }

        if (!allocatedList.empty()) {
            auto result = allocatedList.front().get();
            allocatedList.pop();
            return result;
        }

        throw std::runtime_error("Out of memory");
    }

    void free(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        std::unique_lock<std::mutex> lock(mtx);
        if (pdu->isValid) {
            freeList.push_back(*pdu);
        } else {
            allocatedList.emplace(std::move(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>(pdu)));
        }
    }
};

class DataSourceImpl : public DataSource {
private:
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> distr;

public:
    NFAPI_CRC_INDICATION_PDU_T getUEInfo() override {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = distr(gen);
        pdu.RNTI = distr(gen);
        pdu.CRC_INDICATION_REL8_TAG = distr(gen) & 1; // Set CRCFLAG randomly
        return pdu;
    }
};

class Processor {
private:
    CustomAllocator allocator;
    DataSource& dataSource;
    std::condition_variable cv;
    std::mutex mtx;
    std::atomic<bool> running{true};

public:
    Processor(DataSource& dataSource) : dataSource(dataSource) {}

    void start() {
        std::thread([this]() {
            for (;;) {
                auto pdu = dataSource.getUEInfo();
                std::unique_lock<std::mutex> lock(mtx);
                allocator.free(allocator.allocate()); // Free old PDUs if any
                *allocator.allocate() = pdu;
                lock.unlock();
                cv.notify_one();
            }
        }).detach();
    }

    void stop() { running = false; }

    NFAPI_CRC_INDICATION_PDU_T getNextPDU() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !allocator.freeList.empty(); });
        auto pdu = allocator.freeList.back();
        freeList.pop_back();
        return pdu;
    }
};
```

