use execwrap::CommandExt;

fn processAndConvertImage(input_file: &str, output_file: &str, directory: &str, num_crc_indications: u32) -> i32 {
    let temp_dir = match env::var("TEMP_DIR") {
        Ok(val) => Path::new(&val),
        Err(_) => {
            let temp_file = NamedTempFile::new().unwrap();
            let temp_dir = temp_file.path();
            fs::create_dir_all(temp_dir).unwrap();
            temp_dir
        }
    };

    let input_path = Path::new(input_file);
    let output_path = Path::new(output_file);
    let image_data = match read_image(input_path) {
        Ok(img) => img,
        Err(_) => return 1,
    };

    let mut rng = rand::thread_rng();
    let mut crc_indications: Vec<NFAPI_CRC_INDICATION_PDU_T> = vec![];
    for _ in 0..num_crc_indications {
        let crc_flag = rng.gen::<u32>() & ((1 << 32) - 1);
        crc_indications.push(NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag: RX_UE_INFORMATION_TAG::new(),
            rnti: RNTI::new(rng.gen::<u32>()),
            crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG {
                crcflag: crc_flag,
            },
        });
    }

    let output_dir = temp_dir.join(directory);
    fs::create_dir_all(&output_dir).unwrap();
    let output_path = output_dir.join(output_file);

    if env::set_var("TEMP_DIR", output_dir.to_str().unwrap()).is_err() {
        return 1;
    }

    let (tx, rx) = channel();
    let _ = std::thread::spawn(move || {
        convert_image(input_path, output_path, tx);
    });

    for indication in &crc_indications {
        if !write_to_file(&output_path, indication) {
            return 1;
        }
    }

    let _ = rx.recv(); // Wait for the conversion thread to finish

    if output_path.exists() && output_path.is_file() {
        0
    } else {
        1
    }
}

fn read_image(path: &Path) -> std::io::Result<ImageBuffer<Rgb8>> {
    let mut file = File::open(path)?;
    image::imageops::colored(image::GenericImageView::new(file)?, Rgb([0, 0, 0]))
}

fn write_to_file<T: Write>(path: &Path, data: &T) -> std::io::Result<()> {
    let mut file = File::create(path)?;
    data.write_to(&mut file)?;
    Ok(())
}

fn convert_image(input_path: &Path, output_path: &Path, tx: std::sync::mpsc::Sender<()>) {
    let command = format!("third_party_tool {} {}", input_path.to_str().unwrap(), output_path.to_str().unwrap());
    let mut cmd = Command::new("sh")
        .arg("-c")
        .arg(&command);

    for attempt in 1..=3 {
        if let Ok(output) = cmd.status() {
            if output.success() {
                tx.send(()).unwrap();
                return;
            }
        } else {
            println!("Attempt {}: Error executing command: {}", attempt, command);
        }
    }
}
```

