import io.netty.bootstrap.Bootstrap;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.nio.NioSocketChannel;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.IntStream;

public class ConnectionManager {
    private final List<String> serverAddresses;
    private final ConcurrentHashMap<Long, NioSocketChannel> connections;
    private final ConcurrentHashMap<String, AtomicInteger> serverFailureCounts;
    private final int maxRetriesPerServer;
    private final EventLoopGroup group;
    private final Bootstrap bootstrap;

    public ConnectionManager(List<String> serverAddresses, int maxConnections, int maxRetriesPerServer) {
        this.serverAddresses = serverAddresses;
        this.connections = new ConcurrentHashMap<>();
        this.serverFailureCounts = new ConcurrentHashMap<>();
        this.maxRetriesPerServer = maxRetriesPerServer;
        this.group = new NioEventLoopGroup();
        this.bootstrap = new Bootstrap()
                .group(group)
                .channel(NioSocketChannel.class);
    }

    public void start() {
        IntStream.range(0, serverAddresses.size())
                .parallel()
                .forEach(i -> connectToServer(serverAddresses.get(i)));
    }

    private void connectToServer(String address) {
        AtomicInteger failureCount = serverFailureCounts.computeIfAbsent(address, k -> new AtomicInteger(0));
        int retriesLeft = maxRetriesPerServer - failureCount.get();

        if (retriesLeft > 0) {
            bootstrap.handler(new ChannelInitializer<NioSocketChannel>() {
                @Override
                protected void initChannel(NioSocketChannel ch) throws Exception {
                    // Add your custom handler here to handle the connection lifecycle and data processing
                }
            });

            bootstrap.connect(address).addListener((future) -> {
                if (future.isSuccess()) {
