};

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

std::mutex cacheMutex;
std::unordered_map<RNTI, NFAPI_CRC_INDICATION_PDU_T*> cache;

NFAPI_CRC_INDICATION_PDU_T* create_structure(const RX_UE_INFORMATION_TAG& tag, const RNTI& rnti) {
    std::lock_guard<std::mutex> lock(cacheMutex);

    if (cache.find(rnti) != cache.end()) {
        return cache[rnti];
    }

    auto structure = new NFAPI_CRC_INDICATION_PDU_T;
    structure->rx_ue_information_tag = tag;
    structure->rnti = rnti;
    structure->crc_indication_rel8_tag.crcFlag = rand() % 2; // Randomly set CRCFLAG

    cache[rnti] = structure;
    Logging::logSuccessfulCreation(structure);
    return structure;
}

void destroy_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    std::lock_guard<std::mutex> lock(cacheMutex);
    auto it = cache.find(structure->rnti);
    if (it != cache.end()) {
        delete it->second;
        cache.erase(it);
        Logging::logDestruction(structure);
    } else {
        Validation::validateRNTIInRange(structure->rnti); // External validation function call
        delete structure;
    }
}
