#include <random>
#include <unordered_map>

struct Attack {
    int id;
    int minDuration;
    int maxDuration;
    int cooldown;
};

std::vector<Attack> attacks = {
    {1, 5, 12, 15},
    {2, 6, 14, 20},
    {3, 7, 13, 25},
    {4, 8, 15, 30}
};

std::unordered_map<int, std::chrono::steady_clock::time_point> cooldowns;

void manageAttackPattern(const std::vector<Attack>& attacks) {
    if (cooldowns.empty()) {
        // Initialize the first attack
        int currentAttack = std::rand() % attacks.size();
        auto startTime = std::chrono::steady_clock::now();
        cooldowns[currentAttack] = startTime;
    }

    auto now = std::chrono::steady_clock::now();
    for (auto& entry : cooldowns) {
        int currentAttack = entry.first;
        auto attackCooldownEnd = entry.second + std::chrono::seconds(entry.second->cooldown);

        if (now >= attackCooldownEnd) {
            // Attack is ready, select a new one
            int nextAttack = std::rand() % attacks.size();
            auto startTime = now;
            cooldowns[nextAttack] = startTime;

            std::cout << "Selected attack: " << currentAttack << std::endl;
        }
    }
}
```

