    SRB1_SETUP_REQUEST* request = NULL;

    if (pthread_create(&thread, NULL, get_init_params, &request)) {
        fprintf(stderr, "Thread creation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex);
    while (!request) {
        pthread_mutex_unlock(&mutex);
        sleep(1); // Wait for the external data source to respond
        pthread_mutex_lock(&mutex);
    }

    MAC_PDU* mac_pdus = (MAC_PDU*)malloc(N * sizeof(MAC_PDU));
    if (!mac_pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    uint16_t id = 0;
    for (int i = 0; i < N; ++i) {
        while (true) {
            if (id > UINT16_MAX / N) {
                id = 1;
                break;
            }

            pthread_mutex_lock(&mutex);
            bool unique = true;
            for (int j = 0; j < i; ++j) {
                if (mac_pdus[j].SRB1_ID == id) {
                    unique = false;
                    break;
                }
            }
            pthread_mutex_unlock(&mutex);

            if (unique) {
                break;
            }

            ++id;
        }

        mac_pdus[i] = create_mac_pdu(id, request);
        ++id;
    }

    free(request);
    pthread_mutex_unlock(&mutex);
    pthread_join(thread, NULL);

    return mac_pdus;
}

void deallocate_mac_pdus(MAC_PDU* mac_pdus, int N) {
    for (int i = 0; i < N; ++i) {
        free(mac_pdus[i]);
    }
    free(mac_pdus);
}
