struct RNTI { int value; };
struct CRC_INDICATION_REL8_TAG { bool CRCFLAG; };

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

std::vector<NFAPI_CRC_INDICATION_PDU_T> create_pdus(int N, std::function<RX_UE_INFORMATION_TAG()> init_func, int min_rnti = 0, int max_rnti = INT32_MAX) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdus;
    pdus.reserve(N);
    std::mt19937 rng(std::chrono::system_clock::now().time_since_epoch().count());
    std::uniform_int_distribution<int> distr(min_rnti, max_rnti);

    std::mutex mtx;
    std::map<int, bool> used_rntis;

    for (int i = 0; i < N; ++i) {
        int rnti = distr(rng);
        while (used_rntis.count(rnti)) {
            std::unique_lock<std::mutex> lock(mtx);
            rnti = distr(rng);
            lock.unlock();
        }
        used_rntis[rnti] = true;

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rnti.value = rnti;
        pdu.crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        RX_UE_INFORMATION_TAG tag = init_func();
        pdu.rx_ue_information_tag = tag;

        pdus.push_back(pdu);
    }

    return pdus;
}
```

This function creates an array of `NFAPI_CRC_INDICATION_PDU_T` structures with unique RNTI values and randomly set CRCFLAG flags. It uses a mutex to ensure thread safety when generating RNTI values, as multiple threads may be accessing the same range of numbers.

The function takes an initializer function `init_func` that returns a valid `RX_UE_INFORMATION_TAG`. If the external data source is unavailable or provides incomplete or inconsistent data, the function should gracefully fall back to default initialization values.

