struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

std::mutex mtx;
std::map<int, bool> rntiMap; // To store unique RNTIs

void generatePDU(boost::asio::io_service& io_service, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    std::lock_guard<std::mutex> lock(mtx);
    if (rntiMap.find(pdu->RNTI) != rntiMap.end()) {
        // RNTI already exists, generate a new one
        do {
            pdu->RNTI = rand();
        } while (rntiMap.find(pdu->RNTI) != rntiMap.end());
        rntiMap[pdu->RNTI] = true;
