    }
    pdu->CRCFLAG = validateCRCFLAG(pdu->RX_UE_INFORMATION_TAG, pdu->RNTI); // Placeholder for your CRCFLAG validation function
}

void handle_generatePDU(boost::asio::yield_context yield, const boost::system::error_code& error, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!error) {
        // Process the generated PDU here
        std::cout << "Generated PDU: RX_UE_INFORMATION_TAG=" << pdu->RX_UE_INFORMATION_TAG << ", RNTI=" << pdu->RNTI << ", CRCFLAG=" << pdu->CRCFLAG << std::endl;
    } else {
        std::cerr << "Error generating PDU: " << error.message() << std::endl;
    }
}

void managePDUGeneration(boost::asio::io_service& io_service, int N) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdus;
    pdus.reserve(N); // Reserve memory to minimize reallocations

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        boost::asio::post(io_service, [pdu]() { generatePDU(io_service, &pdu); });
        pdus.push_back(pdu);
    }

    for (auto& pdu : pdus) {
        boost::asio::async_read_until(io_service, pdu, '\n', boost::asio::yield_context{}, [pdu](const boost::system::error_code& error, std::size_t /*bytes_transferred*/) {
            if (!error) {
                handle_generatePDU(boost::asio::yield_context{}, error, &pdu);
            }
        });
    }
}
```

