    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, UINT16_MAX);
    return dis(gen);
}

// RNTI uniqueness check and generation function
unsigned int generateRNTI(const std::map<unsigned int, bool>& rntiMap) {
    unsigned int rnti;
    do {
        rnti = std::uniform_int_distribution<>(1, UINT32_MAX)(rd);
    } while (rntiMap.find(rnti) != rntiMap.end());
    return rnti;
}

