    // ... (Include necessary fields here)
};

// NFAPI_CRC_INDICATION_PDU_T structure
struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

// Function to create and populate the list with unique RNTIs
std::vector<NFAPI_CRC_INDICATION_PDU_T> createList(int N, const DataSource& dataSource, std::mutex& rntiMutex) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> list;
    std::map<unsigned int, bool> rntiMap;

    for (int i = 0; i < N; ++i) {
        RX_UE_INFORMATION_TAG tag = dataSource.getTag();
        unsigned int rnti = generateRNTI(rntiMap);
        rntiMap[rnti] = true;
        CRC_INDICATION_REL8_TAG crcIndicationRel8Tag{generateCRCFlag()};

        NFAPI_CRC_INDICATION_PDU_T pdu{tag, rnti, crcIndicationRel8Tag};
        list.push_back(pdu);
    }

    return list;
}

// Function to dynamically resize the array and revalidate RNTI uniqueness
void resizeAndValidate(std::vector<NFAPI_CRC_INDICATION_PDU_T>& list, int newSize, const DataSource& dataSource, std::mutex& rntiMutex) {
    if (newSize > list.size()) {
        auto newList = createList(newSize - list.size(), dataSource, rntiMutex);
        list.insert(list.end(), newList.begin(), newList.end());
    } else {
        std::vector<NFAPI_CRC_INDICATION_PDU_T> newList;
        for (const auto& pdu : list) {
            if (!rntiMap.at(pdu.rnti)) {
                newList.push_back(pdu);
                rntiMap[pdu.rnti] = true;
            }
        }
        list.swap(newList);
    }
}

// Function to periodically revalidate RNTI uniqueness
void validateRNTIs(std::vector<NFAPI_CRC_INDICATION_PDU_T>& list, const DataSource& dataSource, std::mutex& rntiMutex, unsigned int interval) {
    using namespace std::chrono;
    std::unique_ptr<std::thread> validatorThread;

    if (validatorThread == nullptr) {
        validatorThread = std::make_unique<std::thread>([list, dataSource, rntiMutex, interval]() {
            while (true) {
                std::this_thread::sleep_for(interval);
                resizeAndValidate(list, list.size(), dataSource, rntiMutex);
            }
        });
    }
}
