typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint32_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static struct node* head = NULL;

void init_node(struct node** node) {
    *node = (struct node*) malloc(sizeof(struct node));
    if (*node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    (*node)->next = NULL;
    (*node)->data.RX_UE_INFORMATION_TAG = 0;
    (*node)->data.RNTI = 0;
    (*node)->data.CRC_INDICATION_REL8_TAG = 0;
    (*node)->data.CRCFLAG = rand();
}

void insert(NFAPI_CRC_INDICATION_PDU_T* data) {
    struct node* new_node, *current;
    init_node(&new_node);
    new_node->data = *data;

    pthread_mutex_lock(&mutex);
    current = head;
    while (current != NULL && current->data.RNTI < new_node->data.RNTI) {
        current = current->next;
    }
    if (current == NULL || current->data.RNTI > new_node->data.RNTI) {
        new_node->next = head;
        head = new_node;
    } else {
        while (current->next != NULL && current->next->data.RNTI < new_node->data.RNTI) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&mutex);
}

void print_list() {
    struct node* current = head;
    printf("List:\n");
    while (current != NULL) {
        printf("RNTI: %u, CRCFLAG: %u\n", current->data.RNTI, current->data.CRCFLAG);
        current = current->next;
    }
}
```

