[' Here is a C function named `populateNfarecordsWithRandomCrc` that meets your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/des.h>
#include <time.h>

typedef struct {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_NFA_RECORDS 100000

int populateNfarecordsWithRandomCrc(int nfaApiCrcCount, int crcRangeLow, int crcRangeHigh, unsigned char *key, unsigned char *iv, const char *encryptedData) {
    NFAPI_CRC_INDICATION_PDU_T *nfaRecords = (NFAPI_CRC_INDICATION_PDU_T *)malloc(nfaApiCrcCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaRecords) {
        perror("Memory allocation failure");
        return -1;
    }

    srand((unsigned int)(time(NULL) * getpid()));
    unsigned long sessionId = (unsigned long)getpid();
    unsigned seed = sessionId ^ time(NULL);
    srand(seed);

    DES_cblock iv_des, key_des;
    memcpy(iv_des, iv, sizeof(iv_des));
    memcpy(key_des, key, sizeof(key_des));

    DES_key_schedule ks;
    DES_set_key_unchecked(&ks, key_des);

    unsigned char decryptedData[MAX_NFA_RECORDS * 16];
    int decryptedDataLen = DES_decrypt3_EDE3(encryptedData, decryptedData, (unsigned char *)iv_des, &ks, strlen(encryptedData));
    if (decryptedDataLen <= 0) {
        perror("Decryption failure");
        free(nfaRecords);
        return -1;
    }

    int recordIndex = 0;
    for (int i = 0; i < decryptedDataLen; i += 16) {
        NFAPI_CRC_INDICATION_PDU_T *record = &nfaRecords[recordIndex];
        record->RX_UE_INFORMATION_TAG = *(unsigned short *)(&decryptedData[i]);
        record->RNTI = *(unsigned int *)(&decryptedData[i + 2]);
        memcpy(record->CRC_INDICATION_REL8_TAG, &decryptedData[i + 6], sizeof(record->CRC_INDICATION_REL8_TAG));
        record->CRCFLAG = decryptedData[i + 14] & crcRangeHigh;
        recordIndex++;
    }

    if (recordIndex < nfaApiCrcCount) {
        free(nfaRecords);
        return -1; // Insufficient data for the requested number of records
    }

    return 0;
}
```

This function uses the OpenSSL library for Triple DES encryption and handles memory allocation failures, decryption errors, and insufficient data. The random number generator is seeded using a combination of the current timestamp and the process ID to ensure reproducibility across different sessions. The function optimizes large-scale data processing by handling chunks of 16 bytes at a time during decryption and parsing.']

