#define SEPARATOR "/"

void processFilePath(const char* filePath, size_t sizeLimit, char* buffer, size_t bufferSize, size_t* bufferUsed) {
    if (!filePath || !buffer || !bufferSize || !bufferUsed) return;

    size_t pathLength = strlen(filePath);
    size_t separatorLength = strlen(SEPARATOR);

    // Check if the file path is empty or contains only a separator
    if (pathLength < 1 || (pathLength == separatorLength && memcmp(filePath, SEPARATOR, separatorLength) == 0)) {
        *bufferUsed = 0;
        return;
    }

    // Check if the file path with a separator fits within the size limit
    if (pathLength + separatorLength <= sizeLimit) {
        strcpy(buffer, filePath);
        strcat(buffer, SEPARATOR);
        *bufferUsed = pathLength + separatorLength;
    } else {
        // Truncate the file path to fit within the size limit and append the separator
