```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    char* path;
    size_t depth;
    size_t max_depth;
    char* buffer;
    size_t buffer_size;
} PathContext;

static void traverse(const char* path, PathContext* ctx) {
    if (ctx->depth > ctx->max_depth || ctx->depth < 1)
        return;

    struct stat st;
    if (stat(path, &st) != 0)
        return;

    if (S_ISDIR(st.st_mode)) {
        char new_path[PATH_MAX];
        strcpy(new_path, path);
        if (new_path[strlen(new_path) - 1] != '/')
            strcat(new_path, "/");

        ctx->depth++;
        PathContext child_ctx = *ctx;
        child_ctx.path = new_path;
        traverse(opendir(new_path), &child_ctx);
        ctx->depth--;
    } else if (ctx->buffer && ctx->buffer_size > 0) {
        size_t len = strlen(path);
        if (path[len - 1] == '/')
            len--;

        if (ctx->buffer_size <= len + 2)
            ctx->buffer = realloc(ctx->buffer, ctx->buffer_size * 2);

        memcpy(ctx->buffer + ctx->buffer_size - len - 1, path, len + 1);
        ctx->buffer[ctx->buffer_size] = '/';
        ctx->buffer_size += len + 1;
    }
}

char* constructPathHierarchy(const char* file_path, size_t max_depth, size_t buffer_size, char* buffer) {
    PathContext ctx = { .path = (const char*)file_path, .max_depth = max_depth, .buffer = buffer, .buffer_size = buffer_size };
    traverse(file_path, &ctx);

    if (ctx.buffer && ctx.buffer[ctx.buffer_size - 1] == '/')
        ctx.buffer[--ctx.buffer_size] = '\0';

    return ctx.buffer;
}
```

