void free_buffer_pool() {
    Node* current = buffer_pool;
    while (buffer_pool != NULL) {
        buffer_pool = buffer_pool->next;
        free(current);
        current = buffer_pool;
    }
    num_allocated = 0;
}

Node* allocate_node() {
    if (num_allocated >= max_elements) {
        log_error("Buffer pool is full. Cannot allocate more elements.\n");
        return NULL;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_error("Failed to allocate memory for a new node.\n");
        free_buffer_pool();
        return NULL;
    }

    num_allocated++;
    return new_node;
}

void insert_node(Node* node, Node** head) {
    if (*head == NULL) {
        *head = node;
        node->next = NULL;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
        node->next = NULL;
    }
}

void print_array(Node* head) {
