    std::mutex mtx;
    static std::random_device rd;
    static std::mt19937 gen;

public:
    UESessionManager(size_t num_sessions) {
        if (num_sessions < 1000 || num_sessions > 10000) {
            throw std::invalid_argument("Number of sessions must be between 1000 and 10000");
        }

        sessions.resize(num_sessions);

