        static uint32_t next_tag = 0;
        auto it = tag_to_index.find(next_tag);
        if (it != tag_to_index.end()) {
            next_tag++;
            return generateUniqueTag();
        }
        tag_to_index[next_tag] = sessions.size();
        return next_tag;
    }

