        auto it = tag_to_index.find(next_rnti);
        if (it != tag_to_index.end()) {
            next_rnti++;
            return generateRNTI();
        }
        tag_to_index[next_rnti] = sessions.size();
        return {next_rnti};
    }

    uint32_t generateCRCFLAG() {
        static std::uniform_int_distribution<uint32_t> dist(0, 0xFFFFFFFF);
        return dist(rd);
    }
};

