    memcpy(&node->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->rnti = rnti;
    node->next = NULL;
    return node;
}

hashmap_t* create_hashmap(size_t capacity) {
    hashmap_t *map = (hashmap_t *)mempool_alloc(sizeof(hashmap_t));
    map->capacity = capacity;
    map->count = 0;
    map->buckets = (node_t **)mempool_alloc(capacity * sizeof(node_t*));
    memset(map->buckets, 0, capacity * sizeof(node_t*));
    return map;
}

uint32_t hash(uint32_t key, size_t capacity) {
    return key % capacity;
}

void insert_node(hashmap_t *map, node_t *node) {
    uint32_t index = hash(node->rnti, map->capacity);
    if (map->buckets[index] == NULL) {
        map->buckets[index] = node;
        map->count++;
    } else {
        node_t *current = map->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
        map->count++;
    }
}

node_t* find_node(hashmap_t *map, uint32_t rnti) {
    uint32_t index = hash(rnti, map->capacity);
    node_t *current = map->buckets[index];
    while (current != NULL) {
        if (current->rnti == rnti) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* generate_list(size_t n, size_t *rx_ue_information_tags, hashmap_t *map) {
    for (size_t i = 0; i < n && map->count < 1000; ++i) {
