        node_t *node = find_node(map, rnti);
        if (node == NULL) {
            node = create_node(rnti, &NFAPI_CRC_INDICATION_PDU_T_default);
            insert_node(map, node);
        }
    }

    node_t *head = NULL;
    node_t *current = map->buckets[0];
    while (current != NULL) {
        node_t *next = current->next;
        if (head == NULL) {
            head = current;
        } else {
            current->next = head;
            head = current;
        }
        current = next;
    }

    return &head->pdu;
}
