#include <pthread.h>

// Global variables
char log_file[256];
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

int convert_image(const char*, const char*);
void log_message(const char*, ...);

// Function to process a directory containing images
int batch_image_converter(const char* dir) {
    DIR* dp = opendir(dir);
    if (!dp) return 1; // Error opening the directory

    struct dirent* entry;
    while ((entry = readdir(dp)) != NULL) {
        char path[512];
        snprintf(path, sizeof(path), "%s/%s", dir, entry->d_name);
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue; // Skip . and .. directories

        // Check if the file is a JPEG image
        if (strchr(entry->d_name, '.') && strcasecmp(strchr(entry->d_name, '.'), ".jpg") != 0 && strcasecmp(strchr(entry->d_name, '.'), ".jpeg") != 0) continue;

        char src[256], dest[256];
        snprintf(src, sizeof(src), "%s", path);
        snprintf(dest, sizeof(dest), "%s.pdf", path);

        // Check if the destination file already exists and ask for confirmation before overwriting
        struct stat st;
        if (stat(dest, &st) == 0 && S_ISREG(st.st_mode)) {
            char confirm[256];
            printf("File %s already exists. Overwrite? (y/n): ", dest);
            scanf("%s", confirm);
            if (strcmp(confirm, "y") != 0 && strcmp(confirm, "Y") != 0) continue;
        }

        // Convert the image to PDF using a third-party tool
        int ret = convert_image(src, dest);
        if (ret == 1) return 1; // Error during conversion

        // Log the operation's outcome
        log_message("Converted %s -> %s\n", src, dest);
    }

    closedir(dp);
    return 0;
}

// Function to convert an image to PDF using a third-party tool
int convert_image(const char* src, const char* dest) {
    // Command for converting JPEG to PDF using imagemagick's 'convert' tool
    char cmd[1024] = "convert ";
    strcat(cmd, src);
    strcat(cmd, " ");
    strcat(cmd, dest);

    pid_t pid = fork();
    if (pid == -1) return 1; // Error forking

    if (!pid) { // Child process
        execlp("convert", "convert", cmd, NULL);
        _exit(1); // Exit with error code 1 if execlp fails
    }

    // Parent process
    int status;
    waitpid(pid, &status, 0);

    // Handle potential errors from the tool and retry up to three times with a delay between attempts
    for (int i = 0; i < 3 && WIFEXITED(status) && WEXITSTATUS(status) != 0; ++i) {
        sleep(1 << i);
        pid_t new_pid = fork();
        if (new_pid == -1) return 1; // Error forking

        if (!new_pid) { // Child process
            execlp("convert", "convert", cmd, NULL);
            _exit(1); // Exit with error code 1 if execlp fails
        }

        waitpid(new_pid, &status, 0);
    }

    // Log detailed error messages to the specified log file, including timestamps and retry counts
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        pthread_mutex_lock(&log_mutex);
        log_file_write(log_file, timestamp, " Failed to convert ", src, " -> ", dest, "\n");
        pthread_mutex_unlock(&log_mutex);
    }

    // Cleanup temporary files created during the process
    remove(dest);

    return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 0 : 1;
}

// Function to write log messages to a file
void log_file_write(const char* path, const char* format, ...) {
    va_list args;
    va_start(args, format);

    FILE* fp = fopen(path, "a");
    if (!fp) return; // Error opening the log file

    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    vfprintf(fp, format, args);
    fputc('\n', fp);
    fclose(fp);

    va_end(args);
}
```

