[' List initialization and population function in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint32_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* list = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_list(unsigned int size, unsigned int seed) {
    srand(seed);

    for (unsigned int i = 0; i < size; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failure\n");
            free_list();
            return;
        }

        new_node->data.tag = generate_tag(); // Implement tag generation function here
        new_node->data.rnti = generate_rnti(); // Implement RNTI generation function here
        new_node->data.crc_indication.CRCFLAG = rand() % UINT32_MAX;

        pthread_mutex_lock(&mutex);
        new_node->next = list;
        list = new_node;
        pthread_mutex_unlock(&mutex);
    }
}

void free_list() {
    Node* current = list;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list = NULL;
}

bool is_valid_token(const char* token_str) {
    bool valid = true;
    json_t* root = json_loads(token_str, 0, NULL);
    if (!root) return false;

    json_t* access_token = json_object_get(root, "access_token");
    json_t* expires_in = json_object_get(root, "expires_in");
    json_t* token_type = json_object_get(root, "token_type");
    json_t* refresh_token = json_object_get(root, "refresh_token");

    if (!access_token || !expires_in || !token_type) {
        valid = false;
    } else {
        const char* access_token_str = json_string_value(access_token);
        const char* expires_in_str = json_string_value(expires_in);
        const char* token_type_str = json_string_value(token_type);

        if (strcmp(token_type_str, "Bearer") != 0 || strcmp(expires_in_str, "") == 0) {
            valid = false;
        } else {
            int expires_in_int = atoi(expires_in_str);
            if (expires_in_int <= 0) {
                valid = false;
            }
        }
    }

    json_decref(root);
    return valid;
}
```

