    struct node* next;
} Node;

Node** createList() {
    Node** list = (Node**)malloc(sizeof(Node*) * 10000);
    for (int i = 0; i < 10000; ++i) {
        list[i] = NULL;
    }
    return list;
}

void addEntry(Node** list, int index, NFAPI_CRC_INDICATION_PDU_T data) {
    if (index >= 10000 || list[index]) {
        fprintf(stderr, "Error: List exceeded capacity or already contains an entry at the given index.\n");
        return;
    }
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = list[index];
    list[index] = node;
}

void removeEntryByRNTI(Node** list, uint32_t rnti) {
    for (int i = 0; i < 10000; ++i) {
        Node* current = list[i];
        while (current != NULL) {
            if (current->data.rnti == rnti) {
                Node* temp = current;
                current = current->next;
                free(temp);
                break;
            }
            current = current->next;
        }
    }
}

