    if (!sessions) return NULL;

    sessions->capacity = capacity;
    sessions->count = 0;
    sessions->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!sessions->data) {
        free(sessions);
        return NULL;
    }

    pthread_mutex_init(&sessions->lock, NULL);
    return sessions;
}

bool add_ue_session(UE_SESSIONS* sessions, RX_UE_INFORMATION_TAG tag, uint32_t rnti) {
    for (size_t i = 0; i < sessions->count; ++i) {
        if (sessions->data[i].tag == tag) return false;
    }

    NFAPI_CRC_INDICATION_PDU_T* session = &sessions->data[sessions->count];
    session->tag = tag;
    session->rnti = rnti;
    session->crc_indication.crcflag = rand();

    pthread_mutex_lock(&sessions->lock);
    sessions->count++;
    pthread_mutex_unlock(&sessions->lock);

    return true;
}

void free_ue_sessions(UE_SESSIONS* sessions) {
    if (!sessions) return;

    free(sessions->data);
    pthread_mutex_destroy(&sessions->lock);
    free(sessions);
}

