} MessagePayload;
```

2. Implement a memory pool for efficient allocation and deallocation of `MessagePayload` structures:

```c
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    size_t capacity;
    size_t allocated;
    MessagePayload* data;
} MessagePool;

void initMessagePool(MessagePool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->allocated = 0;
    pool->data = malloc(sizeof(MessagePayload) * capacity);
}

MessagePayload* acquireFromPool(MessagePool* pool) {
    if (pool->allocated < pool->capacity) {
        return &pool->data[pool->allocated++];
    }
    return NULL;
}

void releaseToPool(MessagePool* pool, MessagePayload* message) {
    pool->allocated--;
}
```

3. Implement a thread-safe queue for managing messages:

```c
#include <pthread.h>

typedef struct {
    MessagePool* pool;
    pthread_mutex_t lock;
    pthread_cond_t notEmpty;
    pthread_cond_t notFull;
    size_t head;
    size_t tail;
    size_t count;
} MessageQueue;

void initMessageQueue(MessageQueue* queue, MessagePool* pool) {
    queue->pool = pool;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->notEmpty, NULL);
    pthread_cond_init(&queue->notFull, NULL);
    queue->head = 0;
    queue->tail = 0;
    queue->count = 0;
}

void enqueue(MessageQueue* queue, MessagePayload message) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == queue->pool->capacity) {
        pthread_cond_wait(&queue->notFull, &queue->lock);
    }
    queue->data[queue->head] = message;
    queue->head = (queue->head + 1) % queue->pool->capacity;
    queue->count++;
    pthread_mutex_unlock(&queue->lock);
    pthread_cond_signal(&queue->notEmpty);
}

MessagePayload dequeue(MessageQueue* queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->notEmpty, &queue->lock);
    }
    MessagePayload message = queue->data[queue->tail];
    queue->tail = (queue->tail + 1) % queue->pool->capacity;
    queue->count--;
    pthread_mutex_unlock(&queue->lock);
    pthread_cond_signal(&queue->notFull);
    return message;
}
```

4. Implement the main function to fetch and enqueue messages from the external broker:

```c
