    initMessageQueue(&message_queue, &message_pool);

    while (1) {
        fetchMessages();
        // Handle potential network latency and errors
        MessagePayload message = acquireFromPool(&message_pool);
        if (message != NULL) {
            enqueue(message_queue, message);
        }
        sleep(1);
    }

