};

class CustomAllocator {
public:
    std::mutex mtx;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pool;
    size_t allocated = 0;
    size_t deallocated = 0;

    NFAPI_CRC_INDICATION_PDU_T* allocate() {
        std::lock_guard<std::mutex> lock(mtx);
        if (pool.empty()) {
            pool.emplace_back();
        }
        auto result = &pool.back();
        allocated++;
        return result;
    }

    void deallocate(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        std::lock_guard<std::mutex> lock(mtx);
        if (pdu != nullptr) {
            pool.pop_back();
            deallocated++;
        }
    }
};

class ThreadPool {
public:
    ThreadPool(size_t numThreads) : workers(numThreads), taskQueue(numThreads + 1) {}

    template<typename F, typename... Args>
    auto enqueue(F&& f, Args&&... args) {
        using return_type = std::invoke_result_t<F, Args...>;
        auto task = std::make_shared<std::packaged_task<return_type()>> (
            std::forward<F>(f)
        );

        auto future = task->get_future();
        {
            std::lock_guard<std::mutex> lock(taskQueue.mutex);
            taskQueue.tasks.emplace([task]() { (*task)(); });
        }
        taskQueue.cond.notify_one();
        return future;
    }

    void start() {
        for (auto& worker : workers) {
            worker = std::thread([this] { for (;;) this->work(); });
        }
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(taskQueue.mutex);
            taskQueue.done = true;
        }
        taskQueue.cond.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

private:
    void work() {
        std::function<void()> task;

        while (!taskQueue.done) {
            {
                std::unique_lock<std::mutex> lock(taskQueue.mutex);
                taskQueue.cond.wait(lock, [this] { return !taskQueue.tasks.empty() || taskQueue.done; });
                if (taskQueue.done && taskQueue.tasks.empty()) {
                    return;
                }
                task = std::move(taskQueue.tasks.front());
                taskQueue.tasks.pop_front();
            }
            task();
        }
    }

    std::vector<std::thread> workers;
    std::queue<std::function<void()>> taskQueue{};
    mutable std::mutex taskQueue.mutex;
    bool taskQueue.done = false;
    std::condition_variable taskQueue.cond;
};

CustomAllocator allocator;
ThreadPool pool(1024);

NFAPI_CRC_INDICATION_PDU_T* create_pdu(size_t N) {
