#include <vector>
#include <algorithm>
#include <map>
#include <chrono>
#include <cstdint>
#include <stdexcept>

struct DataChunk_T {
    std::uint32_t packetSize;
    std::uint16_t checksum;
    std::uint64_t timestamp;
};

enum class PacketTag : uint8_t {
    // Define your packet tags here
};

struct CustomDataPacket {
    PacketTag tag;
    uint32_t sessionID;
    std::vector<DataChunk_T> data;
};

class SessionManager {
public:
    void initialize(uint32_t maxSessions) {
        sessions.resize(maxSessions);
        for (auto& session : sessions) {
            session.sessionID = std::numeric_limits<uint32_t>::max();
            session.data.clear();
        }
    }

    CustomDataPacket* getSession(uint32_t sessionID) {
        auto it = sessions.find(sessionID);
        if (it != sessions.end() && it->second.sessionID == sessionID) {
            return &it->second;
        }
        return nullptr;
    }

    void addData(CustomDataPacket* packet, const DataChunk_T& data) {
        packet->data.push_back(data);
        std::sort(sessions.begin(), sessions.end(), [](const auto& lhs, const auto& rhs) {
            return lhs.second.sessionID < rhs.second.sessionID;
        });
    }

    void updateSessionTime(uint32_t sessionID) {
        auto it = sessions.find(sessionID);
        if (it != sessions.end()) {
            it->second.lastActivity = std::chrono::steady_clock::now();
        }
    }

    void checkSessionTimeouts(std::chrono::seconds timeout) {
        auto now = std::chrono::steady_clock::now();
        sessions.erase(
            std::remove_if(sessions.begin(), sessions.end(), [&](const auto& session) {
                return (session.second.lastActivity + timeout) < now;
            }),
            sessions.end()
        );
    }
};

SessionManager sessionManager;
```

