```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    uint32_t rnti;
    RNTI_TAG rnti_tag;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    struct node* next;
    NFAPI_CRC_INDICATION_PDU_T data;
} Node;

struct slab {
    size_t obj_size;
    size_t n_objs;
    size_t cache_size;
    Node** cache;
    size_t allocations;
    size_t reallocations;
};

void* allocate(struct slab* slab) {
    if (slab->n_objs > 0 && slab->cache[slab->n_objs - 1]) {
        Node* node = slab->cache[slab->n_objs - 1];
        slab->cache[slab->n_objs - 1] = node->next;
        slab->n_objs--;
        return node;
    }

    if (slab->n_objs == slab->cache_size) {
        size_t new_cache_size = slab->cache_size ? slab->cache_size * 2 : slab->obj_size;
        Node** new_cache = realloc(slab->cache, sizeof(Node*) * new_cache_size);
        if (!new_cache) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        slab->cache = new_cache;
        slab->cache[slab->cache_size - 1] = NULL;
    }

    Node* node = &slab->cache[slab->n_objs++]->data;
    memset(node, 0, slab->obj_size);
    return node;
}

void free_node(struct slab* slab, void* ptr) {
    Node* node = (Node*)ptr;
    node->next = slab->cache[slab->n_objs - 1];
    slab->cache[slab->n_objs++] = node;
}

struct slab* create_slab(size_t obj_size, size_t cache_size) {
    struct slab* slab = malloc(sizeof(struct slab));
    if (!slab) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    slab->obj_size = obj_size;
    slab->cache_size = cache_size;
    slab->n_objs = 0;
    slab->allocations = 0;
    slab->reallocations = 0;
    slab->cache = malloc(sizeof(Node*) * slab->cache_size);
    if (!slab->cache) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    slab->cache[slab->cache_size - 1] = NULL;

    return slab;
}
```

This code defines a `slab` structure that manages a cache of allocated objects. The `allocate()` function retrieves an object from the cache if available, and if not, it allocates a new one or performs a reallocation when necessary. The `free_node()` function frees a previously allocated object back to the cache.

The `create_slab()` function initializes a slab with a specified object size and cache size. It also keeps track of the number of allocations and reallocations for monitoring memory management efficiency.']

