            NFAPI_CRHC_INDICATION_PDU_T* new_pool = realloc(pool, sizeof(NFAPI_CRHC_INDICATION_PDU_T) * (num_allocated + 100));
            if (!new_pool) {
                pthread_mutex_unlock(&mutex);
                return -2; // Failed to allocate memory for pool expansion
            }
            pool = new_pool;
            num_allocated++;
        }
    }

    NFAPI_CRHC_INDICATION_PDU_T* structure = &pool[num_used];
    structure->tag = rx_ue_tags[num_used];
    structure->rnti = rntis[num_used];
