MemoryPool* create_memory_pool(size_t initial_capacity, size_t alignment) {
    // Allocate the buffer and initialize the pool structure
    void* buffer = malloc(initial_capacity);
    check_ptr(buffer, "Failed to allocate memory for the pool");

    MemoryPool pool = { .buffer = buffer, .capacity = initial_capacity, .allocated = 0 };
    return &pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->buffer);
}

void* allocate(MemoryPool* pool, size_t size) {
    // Align the requested memory to the specified alignment
    size_t aligned_size = (size + pool->alignment - 1) & ~(pool->alignment - 1);

    if (aligned_size > pool->capacity - pool->allocated) {
        void* new_buffer = realloc(pool->buffer, pool->capacity * 2);
        check_ptr(new_buffer, "Failed to reallocate memory for the pool");
        pool->capacity *= 2;
    }

    void* ptr = (char*)pool->buffer + pool->allocated;
    pool->allocated += aligned_size;
    return ptr;
}

void deallocate(MemoryPool* pool, void* ptr) {
    check_ptr(ptr, "Trying to deallocate NULL pointer");
    pool->allocated -= (char*)ptr - (char*)pool->buffer;
}
