```cpp
#include <boost/lockfree/queue.hpp>
#include <boost/circular_buffer.hpp>
#include <boost/optional.hpp>
#include <cstdint>
#include <memory>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
};

using PduPtr = std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>;
using PduQueue = boost::lockfree::queue<PduPtr>;
using CircularBuffer = boost::circular_buffer<PduPtr>;

class MemoryPool {
public:
    explicit MemoryPool(size_t capacity) : buffer_(capacity), head_(0), tail_(0) {}

    PduPtr allocate() {
        if (head_ == tail_) {
            return boost::none;
        }
        auto index = (tail_ + 1) % buffer_.capacity();
        auto pdu = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>();
        // Initialize PDUs with random CRCFLAG here
        buffer_[index] = std::move(pdu);
        tail_ = index;
        return buffer_[index];
    }

    void free(PduPtr pdu) {
        head_ = (head_ + 1) % buffer_.capacity();
        buffer_[head_] = std::move(*pdu);
    }

private:
    CircularBuffer buffer_;
    size_t head_, tail_;
};

class PduManager {
public:
    explicit PduManager(size_t capacity, size_t queueSize)
        : pool_(capacity), queue_(queueSize) {}

    void insert(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        auto pduPtr = pool_.allocate();
        if (pduPtr) {
            *pduPtr = pdu;
            queue_.enqueue(*pduPtr);
        }
    }

    boost::optional<NFAPI_CRC_INDICATION_PDU_T> pop() {
        auto pduPtr = queue_.try_dequeue();
        if (pduPtr) {
            pool_.free(std::move(*pduPtr));
        }
        return *pduPtr;
    }
};
