#include <random>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct CRC_INDICATION_REL8_TAG {
        bool CRCFLAG;
    } crc_indication;
};

std::set<uint16_t> valid_RNTIs; // Preloaded set of valid RNTIs
std::atomic<uint32_t> processed_elements{0};
boost::circular_buffer<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> buffer(1024);

void process_data(const boost::system_error& error) {
    if (!error) {
        auto pdu = buffer.pop_front();
        if (pdu) {
            if (valid_RNTIs.find((*pdu)->RNTI) == valid_RNTIs.end()) {
                std::cerr << "Invalid RNTI: " << (*pdu)->RNTI << std::endl;
            } else {
                (*pdu)->crc_indication.CRCFLAG = (std::bernoulli_distribution(0.5))(std::mt19937{std::random_device{}()});
                ++processed_elements;
            }
        }
    } else {
        std::cerr << "Error processing data: " << error.code().message() << std::endl;
    }
}

void cleanup_resources() {
    while (!buffer.empty()) {
        auto pdu = buffer.pop_front();
        if (!pdu) continue;
        pdu.reset(); // Release memory
    }
}

void start_processing() {
    boost::asio::io_context ioc;
    boost::asio::io_service cleanup_ioc;

    boost::asio::ip::udp::socket socket(ioc);
    boost::asio::ip::udp::endpoint endpoint;

    socket.open(boost::asio::ip::udp::v4());
    socket.bind(endpoint);

    boost::asio::async_read_until(socket, boost::asio::buffer(reinterpret_cast<char*>(buffer.push_back(std::make_unique<NFAPI_CRC_INDICATION_PDU_T>())) + sizeof(NFAPI_CRC_INDICATION_PDU_T)), '\0', process_data, boost::asio::placeholders::error);

    std::thread cleanup_thread([&]() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(10));
            cleanup_ioc.post(cleanup_resources);
        }
    });

    ioc.run();
}
```

