// Custom allocator/deallocator pair
struct StringAllocator {
    using value_type = char;
    using pointer = char*;
    using size_type = std::size_t;

    static pointer allocate(size_type n) {
        // Call the custom allocator function
        auto ptr = custom_allocator(n);
        if (!ptr) throw std::bad_alloc();
        return ptr;
    }

    static void deallocate(pointer p, size_type n) {
        custom_deallocator(p, n);
    }

    static pointer reallocate(pointer p, size_type old_size, size_type new_size) {
        auto new_ptr = allocate(new_size);
        if (!new_ptr) throw std::bad_alloc();

        // Copy the data from the old string to the new one
        std::memcpy(new_ptr, p, std::min(old_size, new_size));

        // Deallocate the old memory
        deallocate(p, old_size);
        return new_ptr;
    }

    static void construct(pointer p, const std::string& value) {
        new (static_cast<std::unique_ptr<char, decltype(custom_deallocator)>>(p, custom_deallocator)) char[value.length() + 1];
        std::memcpy(p, value.c_str(), value.length() + 1);
    }

    static void destroy(pointer p) {
        static_cast<std::unique_ptr<char, decltype(custom_deallocator)>*>(p)->~unique_ptr();
    }

    // Custom allocator and deallocator functions should be provided here
};

// Thread-safe custom allocator/deallocator wrapper
struct ThreadSafeAllocator {
    std::mutex mtx;
    StringAllocator sa;

    pointer allocate(size_type n) {
        std::lock_guard<std::mutex> lock(mtx);
        return sa.allocate(n);
    }

    void deallocate(pointer p, size_type n) {
        std::lock_guard<std::mutex> lock(mtx);
        sa.deallocate(p, n);
    }

    pointer reallocate(pointer p, size_type old_size, size_type new_size) {
        std::lock_guard<std::mutex> lock(mtx);
        return sa.reallocate(p, old_size, new_size);
    }

    void construct(pointer p, const std::string& value) {
        std::lock_guard<std::mutex> lock(mtx);
        sa.construct(p, value);
    }

    void destroy(pointer p) {
        std::lock_guard<std::mutex> lock(mtx);
        sa.destroy(p);
    }
};

// Function to create a new string with the given rules
std::unique_ptr<char, ThreadSafeAllocator> createString(const char* input, size_t limit, bool appendSpecialChar, char specialChar1, char specialChar2) {
    auto allocator = ThreadSafeAllocator();
    std::string str(input);

    if (str.length() > limit) {
        // Truncate the string and append a special character
        str.resize(limit - 1);
        allocator.construct(allocator.reallocate(allocator.allocate(limit), str.length(), limit + 1));
        std::memcpy(allocator.get(), str.c_str(), str.length());
        allocator.construct(allocator.get() + str.length(), specialChar2);
    } else if (appendSpecialChar) {
        // Append a special character to the end of the string
        auto ptr = allocator.allocate(limit + 1);
        allocator.construct(ptr, str);
        allocator.construct(ptr + str.length(), specialChar1);
    } else {
        // Allocate the exact size and construct the string
        auto ptr = allocator.allocate(str.length());
        allocator.construct(ptr, str);
    }

    return std::move(allocator);
}
