#include <iostream>
#include <vector>
#include <unordered_map>
#include <cstdint>
#include <random>
#include <atomic>
#include <memory>
#include <sys/mman.h>
#include <arpa/inet.h>

struct RX_UE_INFORMATION_TAG {
    uint32_t tag;
};

struct CRC_INDICATION_REL8_TAG {
    std::atomic<uint32_t> crcflag;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxi;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG cindication;
};

class DynamicArray {
public:
    DynamicArray() : data_(nullptr), cache_, lock_(), nextRNTI_(1) {}

    ~DynamicArray() {
        if (data_) munmap(data_.get(), capacity_ * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    bool add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(lock_);
        if (cache_.count(pdu.rnti)) return false; // RNTI already exists

        if (nextIndex_ == capacity_) resize();

        auto& pduAtIndex = data_[nextIndex_++];
        pduAtIndex.rxi = pdu.rxi;
        pduAtIndex.rnti = pdu.rnti;
        pduAtIndex.cindication.crcflag.store(rand(), std::memory_order_relaxed);
        cache_[pdu.rnti] = nextIndex_ - 1;
        return true;
    }

    bool remove(uint32_t rnti) {
        std::lock_guard<std::mutex> lock(lock_);
        auto it = cache_.find(rnti);
        if (it == cache_.end()) return false; // RNTI not found

        data_[it->second].~NFAPI_CRC_INDICATION_PDU_T();
        cache_.erase(it);
        --nextIndex_;
        return true;
    }

    const NFAPI_CRC_INDICATION_PDU_T* get(uint32_t rnti) const {
        std::lock_guard<std::mutex> lock(lock_);
        auto it = cache_.find(rnti);
        if (it == cache_.end()) return nullptr; // RNTI not found
        return &data_[it->second];
    }

private:
    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[], decltype(&munmap)> data_;
    std::unordered_map<uint32_t, size_t> cache_;
    std::mutex lock_;
    size_t nextIndex_{0};
    size_t capacity_{0};

