        auto process = std::process::process_options()
            .command("cmd", "/c", "start", "/w", "\"", siteName, ".exe\"")
            .directory(fs::path(directory))
            .launch();

        if (!process.wait_for(std::chrono::seconds(10))) {
            std::cerr << "Failed to start the website." << std::endl;
        }
    } catch (const std::system_error& e) {
        std::cerr << "Error starting the website: " << e.code().message() << std::endl;
    }
}

std::vector<NFAPI_CRC_INDICATION_PDU_T>* createStructuresAndAllocateMemory(size_t size, const std::string& directory, const std::string& siteName) {
    if (!checkWebConfig(directory, siteName)) return nullptr;

    startWebsite(directory, siteName);

    auto structures = allocateStructures(size);

    if (structures == nullptr) {
        std::cerr << "Failed to allocate memory for the structures." << std::endl;
        return nullptr;
    }

    return reallocateStructures(structures, size);
}
