#include <pthread.h>
#include <semaphore.h>

const int MAX_CONCURRENT = 50;
sem_t semaphore; // Semaphore for managing concurrent processes

void convertImage(const std::string &input, const std::string &output, const std::string &format) {
    boost::process::child imgConv("convert", boost::process::std_out > boost::iostreams::null,
                                   boost::process::std_err > boost::iostreams::null);
    imgConv % input % "-output" % output % format;
}

void worker(std::vector<std::string> &files, std::string outDir) {
    while (!files.empty()) {
        sem_wait(&semaphore); // Wait for a free slot to run a process

        auto file = files.front();
        files.erase(files.begin());

        std::string inputPath = "input/" + file;
        std::string outputPath = outDir + "/" + boost::filesystem::path(file).filename().replace_extension(".pdf");
        convertImage(inputPath, outputPath, getFormatFromFile(inputPath));

        sem_post(&semaphore); // Release a slot after the process is done
    }
}

int processBatch(const std::vector<std::string> &files, const std::string &outDir, int maxConcurrent = MAX_CONCURRENT) {
    sem_init(&semaphore, 0, maxConcurrent); // Initialize the semaphore with the maximum allowed concurrency limit

    std::vector<std::thread> workers;
    for (size_t i = 0; i < std::min(files.size(), MAX_CONCURRENT); ++i) {
        workers.emplace_back(worker, std::ref(files), outDir);
    }

    int failures = 0;
    for (auto &worker : workers) {
        worker.join();
    }

    sem_destroy(&semaphore); // Destroy the semaphore after all processes are done

    if (files.size() > MAX_CONCURRENT) {
        return -1; // Batch size exceeded the dynamically calculated maximum allowed limit
    }

    if (failures > 0) {
        return 1; // At least one conversion failed
    }

    return 0; // All conversions were successful
}
```

