[' Here's a simplified version of the `Nfareader` utility class in Java. This implementation uses the `java.util.Random` for random number generation, `java.security.MessageDigest` for hashing, and is designed to be thread-safe using the `java.util.concurrent.locks.ReentrantLock`. The class supports MD5 and SHA-256 hashing mechanisms.

```java
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.locks.ReentrantLock;

public final class Nfareader {
    private static final int RX_UE_INFORMATION_TAG = 0x01;
    private static final int RNTI = 4;
    private static final int CRC_INDICATION_REL8_TAG = 0x23;

    private final ReentrantLock lock = new ReentrantLock();
    private final List<NFAPI_CRC_INDICATION_PDU_T> buffer = new ArrayList<>();
    private MessageDigest md;
    private boolean isMD5;

    public Nfareader(boolean useMD5) {
        this.isMD5 = useMD5;
        try {
            if (useMD5) {
                md = MessageDigest.getInstance("MD5");
            } else {
                md = MessageDigest.getInstance("SHA-256");
            }
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public void addData(byte[] data) {
        lock.lock();
        try {
            if (buffer.isEmpty()) {
                NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
                pdu.tag = RX_UE_INFORMATION_TAG;
                pdu.rnti = RNTI;
                pdu.crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG;
                pdu.crcFlag = new Random().nextBoolean();
                pdu.dataLength = data.length;
                pdu.data = ByteBuffer.wrap(data);
                buffer.add(pdu);
            } else {
                NFAPI_CRC_INDICATION_PDU_T lastPdu = buffer.get(buffer.size() - 1);
                byte[] combinedData = new byte[lastPdu.dataLength + data.length];
                System.arraycopy(lastPdu.data.array(), 0, combinedData, 0, lastPdu.dataLength);
                System.arraycopy(data, 0, combinedData, lastPdu.dataLength, data.length);
                lastPdu.data = ByteBuffer.wrap(combinedData);
                lastPdu.dataLength += data.length;
            }
        } finally {
            lock.unlock();
        }
    }

    public List<NFAPI_CRC_INDICATION_PDU_T> getAndClearBuffer() {
        lock.lock();
        try {
            List<NFAPI_CRC_INDICATION_PDU_T> result = new ArrayList<>(buffer);
            buffer.clear();
            return result;
        } finally {
            lock.unlock();
        }
    }

    public byte[] calculateHash(byte[] data) {
        md.reset();
        md.update(data);
        return md.digest();
    }
}
```

The `NFAPI_CRC_INDICATION_PDU_T` structure is not provided in the question, so I've assumed a simple representation with fields for tag, rnti, crcIndicationRel8Tag, crcFlag, dataLength, and data. You may need to adjust this according to your specific requirements.

For unit testing, you can create separate test classes for individual hash calculations and batch processing, using JUnit and Mockito libraries.']

