using System;
using System.Collections.Generic;
using System.Security.Cryptography;

public class DynamicValueGenerator {
    private readonly Dictionary<string, (double min, double max)> ranges;
    private string defaultRangeName = "default";
    private double defaultMin = 0;
    private double defaultMax = 1;

    public DynamicValueGenerator() {
        ranges = new Dictionary<string, (double min, double max)>();
        AddRange(defaultRangeName, defaultMin, defaultMax);
    }

    public void AddRange(string name, double min, double max) {
        if (min > max) throw new ArgumentException("Minimum value must be less than maximum value.");
        ranges[name] = (min, max);
    }

    public void RemoveRange(string name) {
        if (!ranges.ContainsKey(name)) throw new KeyNotFoundException($"Range '{name}' not found.");
        ranges.Remove(name);
    }

    public double GetRandomDouble(string rangeName = null) {
        if (rangeName == null || !ranges.TryGetValue(rangeName, out var range)) {
            range = (defaultMin, defaultMax);
        }
        return new Random().NextDouble() * (range.max - range.min) + range.min;
    }

    public int GetRandomInt(string rangeName = null) {
        double d = GetRandomDouble(rangeName);
        return (int)Math.Floor(d);
    }

    public string GetMD5Hash(string input) {
        using (var md5 = MD5.Create()) {
            byte[] hash = md5.ComputeHash(Encoding.ASCII.GetBytes(input));
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) sb.AppendFormat("{0:x2}", b);
            return sb.ToString();
        }
    }
}
