#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <sys/types.h>
#include <unistd.h>
#include <openssl/sha.h>

typedef struct {
    uint8_t rxi_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag[4];
} NFAPI_CRC_INDICATION_PDU_T;

const char *valid_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

int is_valid_charset(const char *charset) {
    int i;
    for (i = 0; charset[i]; ++i) {
        if (!isalnum(charset[i])) return 0;
    }
    return 1;
}

char *generate_random_string(size_t length, const char *charset) {
    if (!is_valid_charset(charset)) {
        fprintf(stderr, "Invalid character set\n");
        exit(EXIT_FAILURE);
    }

    char *str = malloc(length + 1);
    if (!str) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < length; ++i) {
        str[i] = valid_chars[(rand() % strlen(valid_chars))];
    }
    str[length] = '\0';
    return str;
}

void calculate_crcflag(const char *str, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    SHA256_CTX ctx;
    uint8_t hash[SHA256_DIGEST_LENGTH];
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, str, strlen(str));
    SHA256_Final(hash, &ctx);

    for (size_t i = 0; i < 4; ++i) {
        pdu->crcflag[i] = hash[i];
    }
}

void create_and_populate_pdus(int N, const char *charset, size_t length, NFAPI_CRC_INDICATION_PDU_T **pdus) {
    *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdus) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < N; ++i) {
