    for (size_t i = 0; i < list_pool.capacity; ++i) {
        if (!list_pool.pool[i]) {
            list_pool.pool[i] = malloc(sizeof(Node));
            if (!list_pool.pool[i]) {
                fprintf(stderr, "Out of memory\n");
                pthread_mutex_unlock(&list_pool.lock);
                return NULL;
