    for (size_t i = 0; i < list_pool.capacity; ++i) {
        if (!list_pool.pool[i]) {
            list_pool.pool[i] = node;
            list_pool.count--;
            pthread_mutex_unlock(&list_pool.lock);
            return;
        }
    }
    free(node);
}

void manage_list() {
    if (list_pool.count > list_pool.capacity * 0.9) { // Adjust threshold as needed
        Node* node = list_pool.pool[list_pool.capacity - 1];
        free(node);
        for (size_t i = list_pool.capacity - 2; i > 0; --i) {
