class MemoryPool {
public:
    MemoryPool(size_t maxElements) : buffer_(nullptr), capacity_(0), head_(0), tail_(0), numAllocations_(0), numReallocations_(0) {
        reserve(maxElements);
    }

    NFAPI_RX_INDICATION_PDU_T* allocate() {
        if (head_ == tail_) return nullptr;

        auto index = head_.fetch_add(1, std::memory_order_relaxed);
        if (index >= capacity_) grow();

        return &buffer_[index];
    }

    void deallocate(NFAPI_RX_INDICATION_PDU_T* pdu) {
        tail_.fetch_add(1, std::memory_order_relaxed);
    }

private:
    void grow() {
        ++numReallocations_;
        auto newCapacity = capacity_ * 2;
        auto newBuffer = static_cast<NFAPI_RX_INDICATION_PDU_T*>(::operator new(newCapacity * sizeof(NFAPI_RX_INDICATION_PDU_T)));

        if (newBuffer) {
            std::copy_n(buffer_, capacity_, newBuffer);
            ::operator delete(buffer_);
            buffer_ = newBuffer;
            capacity_ = newCapacity;
        } else {
            ++numAllocations_;
            std::cerr << "Memory allocation failed, increasing the number of elements to " << capacity_ * 2 << "\n";
            reserve(capacity_ * 2);
        }
    }

    void reserve(size_t newCapacity) {
        if (newCapacity > capacity_) {
            auto oldBuffer = buffer_;
            buffer_ = static_cast<NFAPI_RX_INDICATION_PDU_T*>(::operator new(newCapacity * sizeof(NFAPI_RX_INDICATION_PDU_T)));
            std::copy_n(oldBuffer, capacity_, buffer_);
            ::operator delete(oldBuffer);
            capacity_ = newCapacity;
        }
    }

    std::atomic<size_t> head_{0};
    std::atomic<size_t> tail_{0};
    std::vector<NFAPI_RX_INDICATION_PDU_T> buffer_;
    size_t capacity_{0};
    std::atomic<size_t> numAllocations_{0};
    std::atomic<size_t> numReallocations_{0};
};

class DynamicArray {
public:
    DynamicArray(MemoryPool& pool, size_t maxElements) : pool_(pool), maxElements_(maxElements), queue_(maxElements_) {}

    boost::lockfree::queue<std::unique_ptr<NFAPI_RX_INDICATION_PDU_T>>& getQueue() { return queue_; }

private:
    MemoryPool& pool_;
    size_t maxElements_;
    boost::lockfree::queue<std::unique_ptr<NFAPI_RX_INDICATION_PDU_T>> queue_;
};
