            ue_indication.RNTI = distr(gen); // Generate RNTI within valid range
            assert(ue_indication.RNTI >= MIN_VALID_RNTI && ue_indication.RNTI <= MAX_VALID_RNTI);
            ue_indication.CRC_INDICATION_REL8_TAG = static_cast<uint8_t>(distr(gen));
            ue_indication.CRCFlag = distr(gen) % 2 == 0; // Randomly set CRCFlag
        } else {
            std::cerr << "Warning: Failed to extract UE information for UE #" << i << std::endl;
            ue_indication.RNTI = DEFAULT_RNTI;
            ue_indication.RX_UE_INFORMATION_TAG = DEFAULT_TAG;
            ue_indication.CRC_INDICATION_REL8_TAG = DEFAULT_CRC_INDICATION_REL8_TAG;
            ue_indication.CRCFlag = false;
        }

        ue_indications.push_back(ue_indication);
    }

    return ue_indications;
}
