#include <iostream>
#include <string>
#include <vector>
#include <boost/circular_buffer.hpp>
#include <mutex>
#include <atomic>

constexpr size_t BUFFER_GROWTH = 1024;
constexpr char SEPARATOR = ';'; // Change this to ',' if needed

class SharedBuffer {
public:
    SharedBuffer(size_t capacity) : buffer_(capacity), head_(0), tail_(0), capacity_(capacity) {}

    void append(const std::string& str, bool addSeparator = true) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (head_ + str.size() > capacity_) {
            size_t newCapacity = std::min(capacity_ * BUFFER_GROWTH, 2 * capacity_);
            buffer_.resize(newCapacity);
            capacity_ = newCapacity;
        }
        if (addSeparator) {
            buffer_[head_++] = SEPARATOR;
        }
        std::copy(str.begin(), str.end(), &buffer_[head_]);
        head_ += str.size();
    }

    void resize(size_t newCapacity) {
        if (newCapacity > capacity_) {
            buffer_.resize(newCapacity);
            capacity_ = newCapacity;
        }
    }

    std::string get() {
        std::unique_lock<std::mutex> lock(mutex_);
        std::string result(buffer_.data() + tail_, head_ - tail_);
        if (result.size() > 0) {
            std::copy(buffer_.data() + head_, buffer_.data(), buffer_.data());
            head_ = buffer_.size();
            tail_ += result.size();
        }
        return result;
    }

private:
    std::vector<char> buffer_;
    size_t head_, tail_, capacity_;
    mutable std::mutex mutex_;
};

void worker(SharedBuffer& buffer, const std::string& str, bool addSeparator) {
    buffer.append(str, addSeparator);
}

int main() {
    SharedBuffer buffer(1024);
    std::vector<std::thread> workers;
    for (size_t i = 0; i < 10; ++i) {
        workers.emplace_back(worker, std::ref(buffer), "String" + std::to_string(i), true);
    }

    for (auto& worker : workers) {
        worker.join();
    }

    auto result = buffer.get();
    std::cout << result << std::endl;

    return 0;
}
```

