class Character {
public:
    int id;
    std::chrono::steady_clock::time_point lastAttackTime;
    bool cooldown;
    int cooldownPeriod;

    Character(int id, int cooldownPeriod) : id(id), cooldown(false), cooldownPeriod(cooldownPeriod) {}

    void attack() {
        if (!cooldown) {
            lastAttackTime = std::chrono::steady_clock::now();
            cooldown = true;
        }
    }

    void resumeCooldown() {
        if (cooldown && std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - lastAttackTime).count() >= 5) {
            cooldown = false;
        }
    }
