        // Simulate character interaction based on the received PDU
        auto it = std::find_if(characters.begin(), characters.end(), [pdu](const Character& c) { return c.rnti == pdu.rnti; });
        if (it != characters.end()) {
            it->attack();
            updateGlobalCooldown();
        }
