```csharp
using System;
using UnityEngine;

public class QuadTree
{
    public const int MaxDepth = 16;
    public Vector3 MinBounds { get; private set; }
    public Vector3 MaxBounds { get; private set; }
    public int Depth { get; private set; }
    public Node Root { get; private set; }
    public int ObjectCount { get; private set; }

    public QuadTree(Vector3 minBounds, Vector3 maxBounds)
    {
        MinBounds = minBounds;
        MaxBounds = maxBounds;
        Depth = 0;
        Root = new Node(this);
        ObjectCount = 0;
    }

    public void Add(GameObject obj)
    {
        if (Root.IsEmpty)
            Root.Add(obj);
        else
            Root.SubdivideIfNeeded().Add(obj);

        ObjectCount++;
    }

    public void Remove(GameObject obj)
    {
        if (Root == null || Root.IsEmpty) return;
        Root.Remove(obj);
        ObjectCount--;
    }

    public GameObject[] Query(Vector3 min, Vector3 max)
    {
        var results = new List<GameObject>();
        Query(Root, min, max, results);
        return results.ToArray();
    }

    private void Query(Node node, Vector3 min, Vector3 max, List<GameObject> results)
    {
        if (node == null || !node.Bounds.Overlaps(new Bounds(min, max - min))) return;

        foreach (var obj in node.Objects)
            if (obj.transform.position.WithinBounds(node.Bounds))
                results.Add(obj);

        for (int i = 0; i < 4; i++)
            Query(node.Children[i], min, max, results);
    }

    public override string ToString()
    {
        return $"QuadTree: Depth={Depth}, ObjectCount={ObjectCount}, MinBounds={MinBounds}, MaxBounds={MaxBounds}";
    }
}

public class Node
{
    public QuadTree Parent { get; private set; }
    public Vector3 Bounds { get; private set; }
    public GameObject[] Objects { get; private set; }
    public Node[,] Children { get; private set; }

    public bool IsEmpty => Objects == null || Objects.Length == 0;

    public Node(QuadTree parent)
    {
        Parent = parent;
        Bounds = parent.MinBounds + (parent.MaxBounds - parent.MinBounds) * 0.5f;
        Objects = new GameObject[4];
        Children = new Node[2, 2];
    }

    public Node SubdivideIfNeeded()
    {
        if (Depth >= Parent.MaxDepth || !IsEmpty) return this;

        var halfSize = (Parent.MaxBounds - Parent.MinBounds) * 0.5f;
        Bounds = new Vector3(Bounds.x, Bounds.y, Bounds.z) + halfSize;
        Children[0, 0] = new Node(Parent);
        Children[1, 0] = new Node(Parent);
        Children[0, 1] = new Node(Parent);
        Children[1, 1] = new Node(Parent);

        var boundsHalfSize = halfSize * 0.5f;
        Children[0, 0].Bounds = Parent.MinBounds + new Vector3(Bounds.x - boundsHalfSize.x, Bounds.y - boundsHalfSize.y, Bounds.z - boundsHalfSize.z);
        Children[1, 0].Bounds = Parent.MinBounds + new Vector3(Bounds.x + boundsHalfSize.x, Bounds.y - boundsHalfSize.y, Bounds.z - boundsHalfSize.z);
        Children[0, 1].Bounds = Parent.MinBounds + new Vector3(Bounds.x - boundsHalfSize.x, Bounds.y + boundsHalfSize.y, Bounds.z - boundsHalfSize.z);
        Children[1, 1].Bounds = Parent.MinBounds + new Vector3(Bounds.x + boundsHalfSize.x, Bounds.y + boundsHalfSize.y, Bounds.z - boundsHalfSize.z);

        Depth++;
        return this;
    }

    public void Add(GameObject obj)
    {
        if (IsEmpty)
        {
            Objects[0] = obj;
            return;
        }

        var bounds = new Bounds(obj.transform.position, Vector3.one * 10);
        for (int i = 0; i < Objects.Length; i++)
        {
            if (Objects[i] == null)
            {
                Objects[i] = obj;
                return;
            }

            if (!bounds.Overlaps(new Bounds(Objects[i].transform.position, Vector3.one * 10)))
            {
                SubdivideIfNeeded();
                Children[(int)(obj.transform.position.x >= Bounds.x), (int)(obj.transform.position.y >= Bounds.y)][(int)(obj.transform.position.z >= Bounds.z)].Add(obj);
                return;
            }
        }
    }

    public void Remove(GameObject obj)
    {
        for (int i = 0; i < Objects.Length; i++)
        {
            if (Objects[i] == null) continue;
            if (Objects[i] == obj)
            {
                Objects[i] = null;
                return;
            }
        }
    }
}

public static class Vector3Extensions
{
    public static bool WithinBounds(this Vector3 point, Bounds bounds) =>
        point.x >= bounds.min.x && point.x <= bounds.max.x &&
        point.y >= bounds.min.y && point.y <= bounds.max.y &&
        point.z >= bounds.min.z && point.z <= bounds.max.z;
}
```

This code defines a `QuadTree` class that manages game objects within a specified spatial range using a quadtree for spatial partitioning. The class supports adding and removing game objects, checking their presence within the spatial range, and retrieving all objects within a specified area. It also handles dynamic range updates, memory management, and provides a flexible interface for developers to integrate into their projects.

The `Node` class represents each node in the quadtree, managing its children, bounds, and game objects. The `Vector3Extensions` class contains an extension method for checking if a point is within a given Bounds.']

