struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
};

class Character {
public:
    int id;
    NFAPI_CRC_INDICATION_PDU_T data;
    std::chrono::steady_clock::time_point lastAttackTime;
    bool cooldown;
    std::mutex mutex;

    Character(int id) : id(id), lastAttackTime(std::chrono::steady_clock::now()), cooldown(false) {}

    void setData(const NFAPI_CRC_INDICATION_PDU_T& data) { this->data = data; }

    bool isOnCooldown() const { return cooldown; }

    void startCooldown() {
        std::lock_guard<std::mutex> lock(mutex);
        if (!cooldown) {
            cooldown = true;
            lastAttackTime = std::chrono::steady_clock::now();
        }
    }

    void resumeCooldown() {
        std::lock_guard<std::mutex> lock(mutex);
        if (cooldown && std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - lastAttackTime).count() >= 5) {
            cooldown = false;
        }
    }
};

class NFAPICombatSystem {
public:
    std::vector<Character> characters;
    std::unordered_map<RNTI, Character*> characterMap;
    int maxCapacity;
    double loadThreshold;
    std::mutex loadMutex;
    std::chrono::steady_clock::time_point lastGlobalCooldownStart;

    NFAPICombatSystem(int maxCapacity, double loadThreshold) : maxCapacity(maxCapacity), loadThreshold(loadThreshold), lastGlobalCooldownStart(std::chrono::steady_clock::now()) {}

    void addCharacter(const Character& character) {
        characters.push_back(character);
        characterMap[character.id] = &characters.back();

        if (characters.size() > maxCapacity) {
            std::lock_guard<std::mutex> lock(loadMutex);
            while (characters.size() > static_cast<int>(maxCapacity * loadThreshold)) {
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        }
    }

    void processData(const NFAPI_CRC_INDICATION_PDU_T& data) {
        auto it = characterMap.find(data.rnti);
        if (it != characterMap.end()) {
            it->second->setData(data);
            it->second->startCooldown();
        }
    }

    bool canAttack() {
        std::lock_guard<std::mutex> lock(loadMutex);
        if (characters.empty()) return true;

        auto currentLoad = characters.size();
        auto globalCooldownElapsed = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - lastGlobalCooldownStart).count() >= 15;

        if (globalCooldownElapsed || currentLoad <= static_cast<int>(maxCapacity * loadThreshold)) {
            lastGlobalCooldownStart = std::chrono::steady_clock::now();
            for (auto& character : characters) {
                if (!character.cooldown) return true;
            }
        }

        return false;
    }
};
