[' I'm providing you with a basic implementation of a thread-safe doubly linked list in C using pthreads for concurrency management. This example does not include all the features you requested but serves as a starting point for further development.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct List {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = malloc(sizeof(List));
    if (!list) {
        perror("Memory allocation failed");
        return NULL;
    }

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        perror("Memory allocation failed");
        return NULL;
    }

    node->data = data;
    node->next = NULL;
    node->prev = NULL;

    return node;
}

void add_to_list(List* list, Node* node) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

Node* remove_from_list(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* result = NULL;
    if (list->head) {
        result = list->head;
        list->head = list->head->next;
        if (list->head)
            list->head->prev = NULL;
        else
            list->tail = NULL;

        list->size--;
    }

    pthread_mutex_unlock(&list->lock);
    return result;
}

void destroy_node(Node* node) {
    free(node);
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        destroy_node(current);
        current = next;
    }

    free(list);
}
```

This code defines a `List` structure that manages a doubly linked list of `Node` structures. The `create_list()` function initializes the list, and the `create_node()` function creates new nodes. The `add_to_list()` function adds a node to the end of the list, while the `remove_from_list()` function removes the first node from the list.

The list is thread-safe due to the use of a mutex lock (`pthread_mutex_lock()` and `pthread_mutex_unlock()`) around all critical sections that modify the list's state. The `destroy_list()` function frees all allocated memory when the list is no longer needed.

You can further optimize this implementation by implementing object pooling, error handling, logging, and other features as per your requirements.']

