#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint32_t rrc_ue_id;
    uint16_t pdcp_sn;
    char* pdu_data;
    size_t max_length;
} LTE_PDCP_SDU_T;

pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_array(LTE_PDCP_SDU_T** array, size_t capacity, size_t max_length) {
    *array = calloc(capacity, sizeof(LTE_PDCP_SDU_T));
    if (!*array) {
        fprintf(stderr, "Failed to allocate memory for the dynamic array\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < capacity; ++i) {
        (*array)[i].pdu_data = calloc(max_length, sizeof(char));
        if (!(*array)[i].pdu_data) {
            fprintf(stderr, "Failed to allocate memory for PDU buffer\n");
            exit(EXIT_FAILURE);
        }
        (*array)[i].max_length = max_length;
    }
}

void destroy_array(LTE_PDCP_SDU_T* array, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        free((array)[i].pdu_data);
    }
    free(*array);
}

void add_to_array(LTE_PDCP_SDU_T* array, size_t* length, LTE_PDCP_SDU_T new_sdu) {
    pthread_mutex_lock(&array_mutex);

    if (*length >= capacity) {
        fprintf(stderr, "Array is full. Increase the capacity to add more elements\n");
        pthread_mutex_unlock(&array_mutex);
        return;
    }

    (*array)[*length] = new_sdu;
    ++(*length);

    pthread_mutex_unlock(&array_mutex);
}
```

