#include <list>
#include <memory>
#include <mutex>
#include <random>
#include <stdexcept>
#include <iostream>

struct Node {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG tagWithCrc;
    std::unique_ptr<Node> next;

    Node(const RX_UE_INFORMATION_TAG& tag, const RNTI& rnti, const CRC_INDICATION_REL8_TAG& tagWithCrc)
        : tag(tag), rnti(rnti), tagWithCrc(tagWithCrc), next(nullptr) {}
};

class List {
    std::list<std::unique_ptr<Node>> nodes;
    std::mutex mutex;

public:
    void push_back(const RX_UE_INFORMATION_TAG& tag, const RNTI& rnti, const CRC_INDICATION_REL8_TAG& tagWithCrc) {
        std::unique_ptr<Node> newNode = std::make_unique<Node>(tag, rnti, tagWithCrc);
        std::lock_guard<std::mutex> lock(mutex);
        nodes.push_back(std::move(newNode));
    }

    bool insert(const RX_UE_INFORMATION_TAG& tag, const RNTI& rnti, const CRC_INDICATION_REL8_TAG& tagWithCrc, Node* before) {
        std::unique_ptr<Node> newNode = std::make_unique<Node>(tag, rnti, tagWithCrc);
        std::lock_guard<std::mutex> lock(mutex);
        if (before == nullptr) {
            nodes.push_front(std::move(newNode));
        } else {
            auto it = nodes.begin();
            for (; it != nodes.end() && *it > before; ++it) {}
            nodes.insert(it, std::move(newNode));
        }
        return true;
    }

    Node* find(const RNTI& rnti) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto it = nodes.begin(); it != nodes.end(); ++it) {
            if ((*it)->rnti == rnti) {
                return *it;
            }
        }
        return nullptr;
    }
};
```

