    {
        RNTI = rnti;
        RxUeInformationTag = rxUeInformationTag;
        CrCIndicationRel8Tag = crcIndicationRel8Tag;
    }
}

public class UEInfoManager
{
    private ConcurrentDictionary<int, UEInfo> _ueInfos;
    private IExternalDataProvider _dataSource;
    private ILogger _logger;

    public UEInfoManager(IExternalDataProvider dataSource, ILogger logger)
    {
        _dataSource = dataSource;
        _logger = logger;
        _ueInfos = new ConcurrentDictionary<int, UEInfo>();
        Initialize();
    }

    private void Initialize()
    {
        var rntis = _dataSource.GetRNTIs();
        foreach (var rnti in rntis)
        {
            var rxUeInformationTag = _dataSource.GetRxUeInformationTag(rnti);
            var crcIndicationRel8Tag = _dataSource.GetCrCIndicationRel8Tag(rnti);
            Add(rnti, new UEInfo(rnti, rxUeInformationTag, crcIndicationRel8Tag));
        }
    }

    public void Add(int rnti, UEInfo ueInfo)
    {
        if (_ueInfos.TryAdd(rnti, ueInfo)) return;
        _logger.LogError($"Failed to add UE with RNTI {rnti} due to duplicate.");
    }

    public bool Remove(int rnti)
    {
        return _ueInfos.TryRemove(rnti, out _);
    }

    public UEInfo GetByRNTI(int rnti)
    {
        UEInfo ueInfo;
        if (_ueInfos.TryGetValue(rnti, out ueInfo)) return ueInfo;
        _logger.LogWarning($"Failed to find UE with RNTI {rnti}.");
        return null;
    }
}
```

