[" Here's a simplified C++ example using a doubly-linked list with a custom allocator, thread-safe mechanisms, and a background service for flushing old entries. This code is not fully optimized or production-ready, but it should give you a good starting point.

```cpp
#include <iostream>
#include <memory>
#include <list>
#include <mutex>
#include <chrono>
#include <thread>
#include <atomic>
#include <random>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
};

class Allocator {
public:
    Allocator(size_t blockSize) : _blockSize(blockSize), _freeList(nullptr) {}

    NFAPI_CRC_INDICATION_PDU_T* allocate() {
        if (_freeList == nullptr) {
            _freeList = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(operator new(_blockSize));
            std::fill(_freeList, _freeList + _blockSize, NFAPI_CRC_INDICATION_PDU_T{});
        }

        auto result = _freeList;
        _freeList = _freeList + 1;
        return result;
    }

    void deallocate(NFAPI_CRC_INDICATION_PDU_T* p) {
        std::fill(p, p + 1, NFAPI_CRC_INDICATION_PDU_T{}); // Clear data for safety
        _freeList = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(std::exchange(_freeList, p));
    }

private:
    size_t _blockSize;
    NFAPI_CRC_INDICATION_PDU_T* _freeList;
};

class List {
public:
    List(size_t blockSize) : _allocator(blockSize), _head(nullptr), _tail(nullptr), _mutex() {}

    void push_back(NFAPI_CRC_INDICATION_PDU_T* data) {
        std::unique_lock<std::mutex> lock(_mutex);

        auto node = std::make_unique<Node>(data, nullptr, nullptr);
        if (_head == nullptr) {
            _head = node.get();
            _tail = _head;
        } else {
            _tail->next = node.get();
            _tail = _tail->next;
        }
    }

    bool pop_front(NFAPI_CRC_INDICATION_PDU_T*& data) {
        std::unique_lock<std::mutex> lock(_mutex);

        if (_head == nullptr) return false;

        data = _head;
        _head = _head->next;
        if (_head == nullptr) _tail = nullptr;
        return true;
    }

private:
    struct Node {
        NFAPI_CRC_INDICATION_PDU_T* data;
        Node* next;
        Node* prev;

        Node(NFAPI_CRC_INDICATION_PDU_T* d, Node* n, Node* p) : data(d), next(n), prev(p) {}
    };

    Allocator _allocator;
    Node* _head;
    Node* _tail;
    std::mutex _mutex;
};

class BackgroundService {
public:
    BackgroundService(List& list, size_t retentionPeriodSecs) : _list(list), _retentionPeriod(retentionPeriodSecs), _thread() {
        _thread = std::thread([this]() {
            while (true) {
                std::this_thread::sleep_for(std::chrono::seconds(_retentionPeriod));
                flush();
            }
        });
    }

    ~BackgroundService() {
        _running.store(false);
        _thread.join();
    }

    void flush() {
        std::unique_lock<std::mutex> lock(_list._mutex);

        auto current = _list._head;
        while (current != nullptr) {
            auto next = current->next;
            if (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count() - current->data->timestamp > _retentionPeriod) {
                _list._allocator.deallocate(current->data);
                if (next == nullptr) _list._tail = nullptr;
                _list._head = next;
            } else {
                current = next;
            }
        }
    }

private:
    List& _list;
    size_t _retentionPeriod;
    std::atomic<bool> _running{true};
    std::thread _thread;
};
```

This code defines a custom allocator, a doubly-linked list, and a background service for flushing old entries. The `NFAPI_CRC_INDICATION_PDU_T`, `RX_UE_INFORMATION_TAG`, and `CRC_INDICATION_REL8_TAG` structures are not defined in this example, but you can replace them with your actual data types.

The custom allocator manages a block of memory to minimize allocations and deallocations. The doubly-linked list is thread-safe using a mutex for concurrent modifications. The background service periodically flushes old entries older than the specified retention period, which can be dynamically adjusted via configuration changes.

You'll need to implement logging, error handling, and integration with a persistent storage backend according to your specific requirements. Additionally, you may want to consider optimizing data structures and algorithms for better performance under high-load scenarios."]

