```c
#include <arpa/inet.h>
#include <netdb.h>
#include <resolv.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

#define MAX_CONCURRENT 10
#define TIMEOUT 5

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int num_requests = 0;

u_char* resolveHostnameWithLimit(const char* hostname) {
    struct addrinfo hints, *res, *tmp;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    pthread_mutex_lock(&mutex);
    num_requests++;
    pthread_mutex_unlock(&mutex);

    if (num_requests > MAX_CONCURRENT) {
        return NULL; // Limit exceeded, return error
    }

    status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        perror("getaddrinfo");
        return NULL; // DNS resolution failed, return error
    }

    tmp = res;
    while (tmp->ai_next) {
        tmp = tmp->ai_next;
    }

    free(res); // Free the initial result

    struct hostent *host_entry = getnameinfo(tmp->ai_addr, tmp->ai_addrlen, NULL, 0, NULL, 0, NI_NUMERICHOST);
    if (host_entry == NULL) {
        perror("getnameinfo");
        return NULL; // DNS resolution failed, return error
    }

    size_t ip_length = strlen(host_entry->h_addr_list[0]);
    u_char* ip_address = malloc(ip_length);
    memcpy(ip_address, host_entry->h_addr_list[0], ip_length);

    pthread_mutex_lock(&mutex);
    num_requests--;
    pthread_mutex_unlock(&mutex);

    return ip_address; // Successfully resolved IP address
}
```

