using System.Data.SqlClient;
using System.Collections.Generic;
using System.Threading;

public class DatabaseConnectionPool
{
    private static readonly object _lock = new object();
    private static readonly List<SqlConnection> _connections = new List<SqlConnection>();
    private const int MaxConnections = 10;

    public SqlConnection GetConnection()
    {
        lock (_lock)
        {
            if (_connections.Count > 0)
            {
                var connection = _connections[^1];
                _connections.RemoveAt(^1);
                return connection;
            }

            var newConnection = new SqlConnection("Your Connection String");
            newConnection.Open();
            _connections.Add(newConnection);
            return newConnection;
        }
    }
}

public IDataReader ExecuteParameterizedQuery(List<object> parameters, string commandText)
{
    using (var connection = new DatabaseConnectionPool().GetConnection())
    {
        var cmd = new SqlCommand(commandText, connection);

        foreach (var parameter in parameters)
        {
            cmd.Parameters.AddWithValue($"@{cmd.Parameters.Count}", parameter);
        }

        try
        {
            return cmd.ExecuteReader();
        }
        catch (SqlException ex)
        {
            Console.WriteLine(ex.Message);
            throw;
        }
    }
}
