    NFAPI_CRFC_INDICATION_PDU_T* data;
    uint32_t rnti_cache[MAX_RNTI]; // Cache for frequently accessed RNTIs
} PDU_CACHE;

PDU_CACHE* pdu_cache_init(size_t capacity) {
    PDU_CACHE* cache = malloc(sizeof(PDU_CACHE));
    if (!cache) return NULL;

    cache->capacity = capacity;
    cache->count = 0;
    cache->data = calloc(capacity, sizeof(NFAPI_CRFC_INDICATION_PDU_T));
    if (!cache->data) {
        free(cache);
        return NULL;
    }

    pthread_mutex_init(&cache->mutex, NULL);

    return cache;
}

void pdu_cache_free(PDU_CACHE* cache) {
    if (cache) {
        free(cache->data);
        pthread_mutex_destroy(&cache->mutex);
        free(cache);
    }
}

NFAPI_CRFC_INDICATION_PDU_T* pdu_cache_get(PDU_CACHE* cache, RX_UE_INFORMATION_TAG tag, uint32_t rnti) {
    if (!validate_rnti(rnti)) return NULL;

    // Check for RNTI in the cache
    for (size_t i = 0; i < MAX_RNTI; ++i) {
        if (cache->rnti_cache[i] == rnti) return &cache->data[cache->rnti_cache[i]];
    }

    // If not found, add it to the cache and return the PDU
    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->count; ++i) {
        if (cache->data[i].tag == tag && cache->data[i].rnti == rnti) {
            pthread_mutex_unlock(&cache->mutex);
            cache->rnti_cache[get_next_free_rnti_slot(cache)] = rnti;
            return &cache->data[i];
        }
    }

    // If not found, allocate a new PDU and add it to the cache
    if (cache->count >= cache->capacity) {
        pthread_mutex_unlock(&cache->mutex);
        return NULL;
    }

    NFAPI_CRFC_INDICATION_PDU_T* pdu = &cache->data[cache->count];
    pdu->tag = tag;
    pdu->rnti = rnti;
    pdu->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG

    cache->rnti_cache[get_next_free_rnti_slot(cache)] = rnti;
    ++cache->count;
    pthread_mutex_unlock(&cache->mutex);

    return pdu;
}

