void add_entry(NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list_lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list_lock);
        return;
    }
    new_node->data = entry;
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&list_lock);
}

void remove_entry(uint32_t rnti) {
    pthread_mutex_lock(&list_lock);
    Node* current = head;
    Node* previous = NULL;

    while (current != NULL && current->data.rnti != rnti) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        fprintf(stderr, "Invalid RNTI provided\n");
        pthread_mutex_unlock(&list_lock);
        return;
    }

    if (previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list_lock);
}

