void add_to_cache(NFAPI_CRC_INDICATION_PDU_T entry) {
    if (cache_size >= max_cache_size) {
        CacheEntry* oldest_entry = NULL;
        time_t oldest_time = 0;

        for (size_t i = 0; i < cache_size; ++i) {
            if (cache[i].last_accessed > oldest_time) {
                oldest_entry = &cache[i];
                oldest_time = cache[i].last_accessed;
            }
        }

        free(oldest_entry);
        memmove(cache, cache + 1, (max_cache_size - 1) * sizeof(CacheEntry));
        --cache_size;
