}

int is_unique(LTE_MAC_RX_FRAME_T **frames, size_t index, size_t n) {
    for (size_t i = 0; i < index; ++i) {
        if (frames[index]->sched_req_id == frames[i]->sched_req_id) {
            return 0;
        }
    }
    return 1;
}

void generate_random_data(LTE_MAC_RX_FRAME_T *frame, int delay) {
    // Implement external data source and network latency simulation here
    frame->header.field1 = rand() % MAX_FIELD1;
    frame->header.field2 = rand() % MAX_FIELD2;
    frame->header.field3 = rand() % MAX_FIELD3;
    frame->sched_req_id = rand();
    frame->pdcch_list.pdch_flag = rand() % 2;

    // Simulate network latency
    usleep(delay * 1000);
}

LTE_MAC_RX_FRAME_T* create_frame() {
    LTE_MAC_RX_FRAME_T *frame = (LTE_MAC_RX_FRAME_T *)malloc(sizeof(LTE_MAC_RX_FRAME_T));
    if (!frame) {
        log("Memory allocation failure");
        return NULL;
    }

    frame->pdcch_list.elements = (PDCH_LIST_ELEMENT *)calloc(MAX_ELEMENTS, sizeof(PDCH_LIST_ELEMENT));
    if (!frame->pdcch_list.elements) {
        log("Memory allocation failure");
        free(frame);
        return NULL;
    }

    return frame;
}

void destroy_frame(LTE_MAC_RX_FRAME_T *frame) {
    if (frame->pdcch_list.elements) {
        free(frame->pdcch_list.elements);
    }
    free(frame);
}

LTE_MAC_RX_FRAME_T* create_frames(size_t n) {
    LTE_MAC_RX_FRAME_T **frames = (LTE_MAC_RX_FRAME_T **)calloc(n, sizeof(LTE_MAC_RX_FRAME_T *));
    if (!frames) {
        log("Memory allocation failure");
        return NULL;
    }

    size_t index = 0;
    while (index < n) {
        LTE_MAC_RX_FRAME_T *frame = create_frame();
        if (!frame) {
            free(frames);
            return NULL;
        }

        while (!is_unique(frames, index, n)) {
            destroy_frame(frame);
            frame = create_frame();
            if (!frame) {
                free(frames);
                return NULL;
            }
        }

        frames[index] = frame;
        ++index;
    }

    return (LTE_MAC_RX_FRAME_T *)frames;
}

void populate_frames(LTE_MAC_RX_FRAME_T *frames, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        generate_random_data(frames[i], rand() % MAX_DELAY);
    }
}

void deallocate_frames(LTE_MAC_RX_FRAME_T *frames, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        destroy_frame(frames[i]);
    }
    free(frames);
}
