    private List<double[]> _data;
    private int _sampleSize;
    private double _samplePercentage;
    private bool _normalizeData;
    private bool _standardizeData;
    private TimeSpan _timeSeriesInterval;

    public DataSampler(List<double[]> data, int sampleSize = 1000, double samplePercentage = 0.1, bool normalizeData = false, bool standardizeData = false, TimeSpan timeSeriesInterval = new TimeSpan())
    {
        _data = data;
        _sampleSize = sampleSize;
        _samplePercentage = samplePercentage;
        _normalizeData = normalizeData;
        _standardizeData = standardizeData;
        _timeSeriesInterval = timeSeriesInterval;
    }

    public List<double[]> Sample()
    {
        if (_data.Count == 0) return new List<double[]>();

        var sampleSizeType = _samplePercentage > 0 ? GetSampleByPercentage : GetSampleByFixedSize;
        return sampleSizeType(_sampleSize);
    }

    private List<double[]> GetSampleByFixedSize(int size) => _data.Skip((_data.Count - size) * (_samplePercentage > 0 ? 1 : 0)).Take(size).ToList();

    private List<double[]> GetSampleByPercentage(int size)
    {
        var sampleSize = (int)(_data.Count * _samplePercentage);
        return _data.OrderBy(_ => Guid.NewGuid()).Take(sampleSize).ToList();
    }

    public List<double[]> Normalize()
    {
        if (!_normalizeData) return _data;
        var min = _data.Min(d => d.Min());
        var max = _data.Max(d => d.Max());
        return _data.Select(d => d.Select(x => (x - min) / (max - min))).ToList();
    }

    public List<double[]> Standardize()
    {
        if (!_standardizeData) return _data;
        var mean = _data.Average(d => d.Average());
        var stdDev = Math.Sqrt(_data.Average(d => d.AveragePow2()) - Math.Pow(mean, 2));
        return _data.Select(d => d.Select(x => (x - mean) / stdDev)).ToList();
    }

    public List<double[]> TimeSeriesSample()
    {
        // Implement time-series sampling logic here
    }

    public void ExportData(string format, string path)
    {
        switch (format.ToLower())
        {
            case "csv":
                ExportCsv(path);
                break;
            case "json":
                ExportJson(path);
                break;
            default:
                throw new ArgumentException($"Unsupported format: {format}");
        }
    }

    private void ExportCsv(string path)
    {
        // Implement CSV export logic here
    }

    private void ExportJson(string path)
    {
        var json = JsonConvert.SerializeObject(_data, Formatting.Indented);
        File.WriteAllText(path, json);
    }

    public override string ToString()
    {
        return $"DataSampler: \n\tSample Size: {_sampleSize}\n\tSample Percentage: {_samplePercentage}\n\tNormalize Data: {_normalizeData}\n\tStandardize Data: {_standardizeData}\n\tTime Series Interval: {_timeSeriesInterval}";
    }
}
