// Read configuration from JSON file
function readConfig() {
  try {
    const rawData = fs.readFileSync(configPath);
    return JSON.parse(rawData);
  } catch (err) {
    console.error(`Error reading config file: ${err}`);
    return {};
  }
}

// Execute command and handle errors
function execCommand(command, options = {}) {
  return new Promise((resolve, reject) => {
    exec(command, options, (error, stdout, stderr) => {
      if (error) {
        console.error(`Error executing command: ${error}`);
        reject(error);
      } else {
        resolve({ stdout, stderr });
      }
    });
  });
}

// Main function to fetch network interfaces and filter results based on IP addresses or subnet masks
async function getNetworkInterfaces(filters = {}) {
  const config = readConfig();
  let command;

  // Handle differences in command syntax across different operating systems
  if (process.platform === 'win32') {
    command = `ipconfig /all`;
  } else if (process.platform === 'darwin') {
    command = `ifconfig -a`;
  } else {
    command = `ip addr show`;
  }

  const { stdout, stderr } = await execCommand(command);

  // Filter results based on provided filters (IP addresses or subnet masks)
  const interfaces = stdout.split('\n').reduce((acc, line) => {
