    this.RNTI = null;
    this.RX_UE_INFORMATION_TAG = null;
    this.CRC_INDICATION_REL8_TAG = null;
    this.crcFlag = null;
  }
}

class RNTIs {
  constructor(size, delay) {
    this.RNTIs = [];
    this.size = size;
    this.delay = delay || 0;

    for (let i = 0; i < size; i++) {
      this.RNTIs[i] = new RNTI();
      while (this.RNTIs.some((rnti, index) => index !== i && rnti.RNTI === this.RNTIs[i].RNTI)) {
        this.RNTIs[i].RNTI = randomBytes(4).toString('hex');
      }
    }

    if (this.externalData) {
      this.initializeFromExternalSource();
    } else {
      this.initializeWithDefaults();
    }
  }

  initializeFromExternalSource() {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        try {
          const data = JSON.parse(this.externalData);
          for (let i = 0; i < this.RNTIs.length; i++) {
            this.RNTIs[i].RX_UE_INFORMATION_TAG = data[i]?.RX_UE_INFORMATION_TAG || this.RNTIs[i].RX_UE_INFORMATION_TAG;
          }
          resolve();
        } catch (error) {
          reject(error);
        }
      }, this.delay);
    });
  }

  initializeWithDefaults() {
    for (let i = 0; i < this.RNTIs.length; i++) {
      this.RNTIs[i].RX_UE_INFORMATION_TAG = Math.floor(Math.random() * 10000);
      this.RNTIs[i].CRC_INDICATION_REL8_TAG = Math.floor(Math.random() * 10000);
      this.RNTIs[i].crcFlag = Math.random() > 0.5 ? true : false;
    }
  }

