        new_node->crc_indication = generate_crc_indication();
        new_node->crcflag = rand() % 2;
        new_node->node = NULL;

        if (!manager->head) {
            manager->head = new_node;
        } else {
            Node *current = manager->head;
            while (current->next) current = current->next;
            current->next = new_node;
        }

        node->rnti = rnti;
        node->is_cached = true;
    }

    Node *result = node->node;
    pthread_mutex_unlock(&node->mutex);
    return result;
}

void manager_free(Manager *manager) {
    if (!manager) return;

    Node *current = manager->head;
    while (current) {
        Node *next = current->next;
        free(current);
        current = next;
    }

    free(manager->cache);
    free(manager);
}
