#include <vector>
#include <algorithm>
#include <mutex>
#include <chrono>
#include <iostream>
#include <stdexcept>

struct MEASUREMENT_REPORT {
    std::uint64_t timestamp;
    // Add other fields as needed
};

struct CELL_ID {
    int id;
    // Add other fields as needed
};

struct NR_UE_MEASUREMENT_RESULT {
    MEASUREMENT_REPORT report;
    CELL_ID cellId;
    std::mutex mutex;
};

class DynamicArray {
public:
    DynamicArray(size_t initialCapacity) : data_(initialCapacity), capacity_(initialCapacity) {}

    ~DynamicArray() {
        for (auto& entry : data_) {
            entry.~NR_UE_MEASUREMENT_RESULT();
        }
        data_.clear();
    }

    void add(const MEASUREMENT_REPORT& report, const CELL_ID& cellId) {
        if (data_.size() >= capacity_) {
            reserve(capacity_ * 2);
        }

        std::unique_lock<std::mutex> lock(mutex_);
        data_.emplace_back(NR_UE_MEASUREMENT_RESULT{ report, cellId });
        sortIfNeeded();
    }

    void sortByCellID() {
        std::sort(data_.begin(), data_.end(), [](const auto& a, const auto& b) { return a.cellId.id < b.cellId.id; });
    }

    void sortByTimestamp() {
        std::sort(data_.begin(), data_.end(), [](const auto& a, const auto& b) { return a.report.timestamp < b.report.timestamp; });
    }

private:
    std::vector<NR_UE_MEASUREMENT_RESULT> data_;
    size_t capacity_;
    mutable std::mutex mutex_;

    void reserve(size_t newCapacity) {
        if (newCapacity < data_.size()) {
            throw std::invalid_argument("New capacity must be greater than the current size.");
        }
        data_.reserve(newCapacity);
    }

    void sortIfNeeded() {
        if (!mutex_.try_lock()) {
            // Handle contention here, e.g., by waiting or retrying
        }
        sortByCellID();
        mutex_.unlock();
    }
};
```

