struct FrameStatistics {
    std::int64_t timestamp;
    std::vector<std::uint32_t> packetIds;
    bool hasErrorEvent;
};

std::unique_ptr<FrameStatistics[]> initializeFrames(const int frameCount, const int minPacketId, const int maxPacketId) {
    auto start = std::chrono::high_resolution_clock::now();
    std::mutex mtx;
    std::unique_ptr<FrameStatistics[]> frames(new FrameStatistics[frameCount]);

    std::thread workerThreads[std::thread::hardware_concurrency()];

    for (int i = 0; i < frameCount; ++i) {
        auto& frame = frames[i];
        frame.timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count();
        frame.packetIds.reserve(100); // Reserve some space for efficiency
        workerThreads[i % workerThreads.size()] = std::thread([&, i]() {
            std::unique_lock<std::mutex> lock(mtx);
            for (int j = minPacketId; j <= maxPacketId; ++j) {
                if (j >= 0 && j < static_cast<int>(frame.packetIds.size())) {
                    frame.packetIds[j] = j; // Valid packet ID
                } else {
                    throw std::runtime_error("Invalid packet ID");
                }
            }
        });
    }

    for (auto& thread : workerThreads) {
        if (thread.joinable()) {
            thread.detach();
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

    // Logging metrics (for example, using a logging library)
    // std::cout << "Initialized " << frameCount << " frames in " << duration << " milliseconds" << std::endl;

    return frames;
}
```

