#include <vector>
#include <queue>
#include <chrono>
#include <mutex>
#include <condition_variable>
#include <iostream>

class SensorDataPacket {
public:
    int deviceId;
    std::string sensorType;
    double value;
    std::int64_t timestamp;

    SensorDataPacket(int deviceId, const std::string& sensorType, double value, std::int64_t timestamp)
        : deviceId(deviceId), sensorType(sensorType), value(value), timestamp(timestamp) {}
};

class SensorDataProcessor {
public:
    SensorDataProcessor(size_t initialSize = 0) {
        packets.reserve(initialSize);
        for (size_t i = 0; i < initialSize; ++i) {
            packets.emplace_back(SensorDataPacket{i, "sensorType", 0.0, std::chrono::steady_clock::now().time_since_epoch().count()});
        }
        processingDelay = std::chrono::seconds(5);
    }

    void processData(SensorDataPacket& packet) {
        std::unique_lock<std::mutex> lock(dataMutex);
        dataQueue.push(packet);
        lastProcessedPacket = packet;
        lastProcessedTimestamp = packet.timestamp;
        lock.unlock();
        condition.notify_one();
        std::cout << "Processing packet: " << packet.deviceId << "\n";
    }

    void waitForProcessing() {
        std::unique_lock<std::mutex> lock(dataMutex);
        condition.wait(lock, [this] { return !dataQueue.empty() && (std::chrono::steady_clock::now() - lastProcessedTimestamp) > processingDelay; });
    }

private:
    std::vector<SensorDataPacket> packets;
    std::queue<SensorDataPacket> dataQueue;
    std::mutex dataMutex;
    std::condition_variable condition;
    SensorDataPacket lastProcessedPacket;
    std::int64_t lastProcessedTimestamp;
    std::chrono::seconds processingDelay;
};
```

