2. Parsing the TIFF image file:

This part is more complex and requires a library to handle TIFF files, such as libtiff. I will provide an example using the libtiff API for extracting the required information.

```c
#include <tiffio.h>
#include <stdint.h>

typedef struct {
    uint16_t bits_per_sample;
    uint16_t sample_per_pixel;
    int extra_samples;
    uint32_t *extra_samples_info; // Array to store extra samples information
} ImageInfo;

ImageInfo parse_tiff(const char *filename) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) return (ImageInfo){0};

    uint16_t bits_per_sample, sample_per_pixel;
    ImageInfo info = {0};

    for (int i = 0; TIFFGetField(tif, i); ++i) {
        if (TIFFFieldDesc(i)->fdType == PHOTOMetric && TIFFFieldDesc(i)->fdName[0] == 'B') {
            bits_per_sample = TIFFFieldDesc(i)->fdInt[0];
            info.bits_per_sample = bits_per_sample;
        } else if (TIFFFieldDesc(i)->fdType == SAMPLEFormat && TIFFFieldDesc(i)->fdName[0] == 'S') {
            sample_per_pixel = TIFFFieldDesc(i)->fdInt[0];
            info.sample_per_pixel = sample_per_pixel;
        }
    }

    if (info.bits_per_sample > 16 || info.sample_per_pixel == 0) {
        TIFFClose(tif);
        return (ImageInfo){-1, -1, -1}; // Error handling for unsupported configurations
    }

    uint32_t extra_samples_count = (info.bits_per_sample * info.sample_per_pixel) / 8 - info.sample_per_pixel;
    if (extra_samples_count > 0) {
        info.extra_samples = extra_samples_count;
        info.extra_samples_info = (uint32_t *)malloc(sizeof(uint32_t) * extra_samples_count);
        if (!info.extra_samples_info) {
            TIFFClose(tif);
            return (ImageInfo){-1, -1, -1}; // Error handling for memory allocation failure
        }

        for (int i = 0; i < extra_samples_count; ++i) {
            info.extra_samples_info[i] = TIFFScanline(tif, i + sample_per_pixel);
        }
    }

    TIFFClose(tif);
    return info;
}
```']

[' Here's a C++ example using the pthread library for thread safety, slab allocation for efficient memory management, and logging with a custom logger class. The code assumes the existence of necessary headers and data structures (NFAPI_CRC_INDICATION_PDU_T, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG).

```cpp
#include <iostream>
#include <vector>
#include <pthread.h>
#include <cstdlib>
#include <ctime>
#include "CustomLogger.h" // Custom logger class header

class SlabAllocator {
public:
    SlabAllocator(size_t size, size_t count) : _slabs(), _currentSlabIndex(0), _totalSize(size * count) {}

    NFAPI_CRC_INDICATION_PDU_T* allocate() {
        if (_currentSlabIndex >= _slabs.size()) {
            createNewSlab();
        }
        auto& currentSlab = _slabs[_currentSlabIndex];
        if (currentSlab.empty()) {
            currentSlab.resize(SLAB_SIZE);
        }
        auto result = &currentSlab.back();
        currentSlab.pop_back();
        return result;
    }

private:
    void createNewSlab() {
        _slabs.emplace_back(SLAB_SIZE);
        _currentSlabIndex++;
    }

    std::vector<std::vector<NFAPI_CRC_INDICATION_PDU_T>> _slabs;
    size_t _currentSlabIndex = 0;
    static constexpr size_t SLAB_SIZE = 128; // Adjust as needed
    size_t _totalSize;
};

class PDUList {
public:
    PDUList(size_t maxPDUs, CustomLogger& logger) : _maxPDUs(maxPDUs), _logger(logger), _allocator(), _mutex() {}

