    size_t _maxPDUs;
    CustomLogger& _logger;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> _pdus;
    pthread_mutex_t _mutex;
};

void* createPDUs(void* arg) {
    auto* list = static_cast<PDUList*>(arg);
    for (size_t i = 0; i < list->_maxPDUs * 10; ++i) {
        list->createAndAddPDU();
    }
    return nullptr;
}

int main() {
    srand(time(nullptr));

    CustomLogger logger("log.txt"); // Initialize custom logger
    PDUList list(1000, logger); // Create PDU list with a maximum of 1000 PDUs

    std::vector<std::thread> threads;
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        threads.emplace_back(createPDUs, &list);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
```

