typedef struct MAC_PDU_T {
    struct ether_hdr mac_header;
    uint8_t mac_payload[MAX_PAYLOAD_SIZE];
} MAC_PDU_T;

MAC_PDU_T* create_mac_pdu(uint16_t packet_size) {
    if (packet_size < sizeof(struct ether_hdr) + ETH_PADDING + ETH_FCS_LEN) {
        fprintf(stderr, "Invalid packet size: %u\n", packet_size);
        return NULL;
    }

    MAC_PDU_T* mac_pdu = (MAC_PDU_T*)malloc(sizeof(MAC_PDU_T));
    if (!mac_pdu) {
        perror("malloc");
        return NULL;
    }

    memset(mac_pdu, 0, sizeof(MAC_PDU_T));
    mac_pdu->mac_header.ether_type = htons(ETHERTYPE_IP); // Set EtherType to IPv4 (0x0800) by default

    if (packet_size > sizeof(mac_pdu->mac_payload)) {
        fprintf(stderr, "Packet size exceeds available payload space: %u\n", packet_size);
        free(mac_pdu);
        return NULL;
    }

    mac_pdu->mac_header.ether_dhost[0] = 0xDE; // Set destination MAC address example (replace with actual value)
    mac_pdu->mac_header.ether_shost[0] = 0xAD; // Set source MAC address example (replace with actual value)

    return mac_pdu;
}

void destroy_mac_pdu(MAC_PDU_T* mac_pdu) {
    free(mac_pdu);
}

int validate_mac_header(const MAC_PDU_T* mac_pdu) {
    uint16_t fcs = 0;
    uint16_t calc_fcs;

    // Calculate FCS using standard library functions
    for (size_t i = offsetof(MAC_PDU_T, mac_payload); i < sizeof(MAC_PDU_T) - ETH_FCS_LEN; ++i) {
        fcs = (fcs << 8) | mac_pdu->mac_payload[i];
    }

    calc_fcs = ~fcs & 0xFFFF; // Invert and mask with 16-bit ones complement

    return mac_pdu->mac_header.ether_check == calc_fcs;
}

MAC_PDU_T** create_dynamic_array(size_t size) {
    MAC_PDU_T** dynamic_array = (MAC_PDU_T**)malloc(sizeof(MAC_PDU_T*) * size);
    if (!dynamic_array) {
        perror("malloc");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        dynamic_array[i] = create_mac_pdu(MAX_PAYLOAD_SIZE);
        if (!dynamic_array[i]) {
            free(dynamic_array);
            return NULL;
        }
    }

    return dynamic_array;
}

void destroy_dynamic_array(MAC_PDU_T** dynamic_array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        destroy_mac_pdu(dynamic_array[i]);
    }
    free(dynamic_array);
}
```

