#include <unordered_map>
#include <stdexcept>
#include <chrono>
#include <thread>

struct NetworkEntity {
    int UE_ID;
    int CELL_ID;
    int SignalStrength;
};

class DynamicList {
public:
    void add(const NetworkEntity& entity) {
        if (unique_ids.count(entity.UE_ID)) {
            throw std::runtime_error("Duplicate UE_ID found.");
        }
        unique_ids[entity.UE_ID] = entities.size();
        entities.push_back(entity);
    }

    const NetworkEntity& get(int index) const {
        if (index >= entities.size()) {
            throw std::out_of_range("Index out of range.");
        }
        return entities[index];
    }

    size_t size() const {
        return entities.size();
    }

private:
    std::unordered_map<int, int> unique_ids;
    std::vector<NetworkEntity> entities;
};

class ExternalData {
public:
    virtual NetworkEntity get(int UE_ID) = 0;
    virtual void update() = 0;

    void retry(std::function<void()> func, int retries = 3, std::chrono::milliseconds delay = std::chrono::milliseconds{500}) {
        for (int i = 0; i < retries; ++i) {
            try {
                func();
                return;
            } catch (const std::exception& e) {
                if (i == retries - 1) {
                    throw e;
                }
                std::cout << "Error occurred while retrieving data. Retrying in " << delay.count() / 1000.0f << " seconds...\n";
                std::this_thread::sleep_for(delay);
            }
        }
    }
};

class NetworkEntityCache : public ExternalData {
public:
    NetworkEntity get(int UE_ID) override {
        if (cache.count(UE_ID)) {
            return cache[UE_ID];
        }
        retry([&]() { return external.get(UE_ID); }, retries, delay);
        cache[UE_ID] = external.get(UE_ID);
        return cache[UE_ID];
    }

    void update() override {
        retry([&]() { external.update(); }, retries, delay);
        for (auto& entity : cache) {
            cache[entity.first] = external.get(entity.first.load());
        }
    }

private:
    std::unordered_map<int, NetworkEntity> cache;
    ExternalData& external;
};

class DynamicListWithCache : public DynamicList {
public:
    void add(const NetworkEntity& entity) override {
        try {
            dataSource.get(entity.UE_ID);
        } catch (const std::exception& e) {
            if (e.what() == "Duplicate UE_ID found.") {
                throw;
            }
            retry([&]() { addImpl(entity); }, retries, delay);
            return;
        }
        addImpl(entity);
    }

    const NetworkEntity& get(int index) const override {
        if (index >= entities.size()) {
            throw std::out_of_range("Index out of range.");
        }
        return entities[index];
    }

    size_t size() const override {
        return entities.size();
    }

private:
    void addImpl(const NetworkEntity& entity) {
        if (unique_ids.count(entity.UE_ID)) {
            throw std::runtime_error("Duplicate UE_ID found.");
        }
        unique_ids[entity.UE_ID] = entities.size();
        entities.push_back(entity);
    }

    NetworkEntityCache dataSource;
};
```

