HashTable hash_table_init(unsigned int size) {
    HashTable table = {.size = size, .table = calloc(size, sizeof(HashNode*)), .lock = PTHREAD_MUTEX_INITIALIZER};
    return table;
}

unsigned int hash(const char* key, unsigned int size) {
    unsigned long hash = 5381;
    for (int i = 0; *key != '\0'; ++key)
        hash = ((hash << 5) + hash) + (*key);
    return hash % size;
}

void hash_table_insert(HashTable* table, const NetworkEntity* entity) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash((const char*) &entity->UE_ID, table->size);
    HashNode** current = &table->table[index];
    while (*current != NULL && (*current)->entity.UE_ID != entity->UE_ID) {
        current = &(*current)->next;
    }

    if (*current == NULL) {
        *current = malloc(sizeof(HashNode));
        (**current) = (NetworkEntity){*entity};
        (**current).next = NULL;
    } else {
        // Handle duplicate UE_ID error or update existing entity as needed
