class DynamicArrayManager {
public:
    void initialize(size_t numInterfaces) {
        interfaces.resize(numInterfaces);
        for (auto& interface : interfaces) {
            interface.lastUpdateTime = std::chrono::steady_clock::now();
        }
    }

    void addConnection(size_t interfaceIndex, const ConnectionDetails& connection) {
        std::unique_lock<std::mutex> lock(interfaces[interfaceIndex].mutex);
        interfaces[interfaceIndex].connectionDetails[connection.remoteIP] = connection;
        interfaces[interfaceIndex].lastUpdateTime = std::chrono::steady_clock::now();
    }

    void updateConnection(size_t interfaceIndex, const ConnectionDetails& connection) {
        std::unique_lock<std::mutex> lock(interfaces[interfaceIndex].mutex);
        interfaces[interfaceIndex].connectionDetails[connection.remoteIP] = connection;
    }

    NetworkInterfaceStatus getInterfaceStatus(size_t interfaceIndex) const {
        std::unique_lock<std::mutex> lock(interfaces[interfaceIndex].mutex);
        return interfaces[interfaceIndex];
    }

private:
    std::vector<NetworkInterfaceStatus> interfaces;
    boost::circular_buffer<ConnectionDetails> updateQueue(1000); // Adjust buffer size based on expected update rate
    boost::lockfree::spsc_queue<size_t> updateIndexQueue;
    std::mutex queueMutex;

    void processUpdates() {
        while (true) {
            size_t index;
            if (!updateIndexQueue.pop(index)) continue; // Exit loop if queue is empty

            auto currentTime = std::chrono::steady_clock::now();
            auto elapsed = currentTime - interfaces[index].lastUpdateTime;

            if (elapsed > std::chrono::seconds(1)) {
                // If the interface has not been updated for more than a second, fetch the latest update from the queue
                auto update = updateQueue.front();
                updateQueue.pop_front();
                addConnection(index, update);
            } else {
                // Update the interface with the latest connection details if they have been updated recently
                auto update = updateQueue.front();
                updateQueue.pop_front();
                updateConnection(index, update);
            }
        }
    }
};
```

