typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    unsigned long long crcflag; // Rolling hash function result
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU;

#define HASH_PRIME 31
#define HASH_MODULUS (1LL << 32)

unsigned long long rolling_hash(const void* data, size_t len) {
    const unsigned char *str = (const unsigned char*)data;
    unsigned long long hash = 0;
    for (size_t i = 0; i < len; ++i) {
        hash = hash * HASH_PRIME + str[i];
        hash %= HASH_MODULUS;
    }
    return hash;
}

void log_error(const char* message) {
    if (logging_enabled) {
        fprintf(stderr, "%s\n", message);
    }
}

NFAPI_CRC_INDICATION_PDU* init_list(size_t size, bool logging_enabled) {
    NFAPI_CRC_INDICATION_PDU *head = NULL;
    for (size_t i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!node) {
            log_error("Memory allocation failure");
            return NULL;
        }
        node->next = head;
        head = node;
    }
    logging_enabled = logging_enabled; // Set global logging flag
    return head;
}

bool validate(NFAPI_CRC_INDICATION_PDU* list) {
    NFAPI_CRC_INDICATION_PDU *current = list;
    while (current != NULL) {
        current->crcflag = rolling_hash(&current->tag, sizeof(current->tag)) ^
                           rolling_hash(&current->rnti, sizeof(current->rnti));
        if (current->crcflag != current->crc_indication) {
            log_error("Invalid CRCFLAG");
            return false;
        }
        current = current->next;
    }
    return true;
}

void free_list(NFAPI_CRC_INDICATION_PDU* list) {
    NFAPI_CRC_INDICATION_PDU *current = list, *temp;
    while (current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
    }
}

NFAPI_CRC_INDICATION_PDU* manage_list(size_t* size, bool logging_enabled) {
    NFAPI_CRC_INDICATION_PDU* list = *size > 0 ? init_list(*size, logging_enabled) : NULL;
    if (list != NULL && validate(list)) {
        return list;
    }
    free_list(list);
    *size *= 2; // Double the size of the list on failure
    return manage_list(size, logging_enabled);
}

NFAPI_CRC_INDICATION_PDU* get_ue_info() {
    // Replace this with your actual implementation for external data source integration.
    static NFAPI_CRC_INDICATION_PDU dummy = { .tag = 0x12345678, .rnti = 98765432, .crc_indication = 0xdeadbeef };
    return &dummy;
}
