    private static final LoadingCache<String, Config> configCache = CacheBuilder.newBuilder()
            .expireAfterAccess(10, TimeUnit.MINUTES)
            .maximumSize(1000)
            .build((key) -> fetchConfig(key));

    private static Config fetchConfig(String key) throws IOException, ExecutionException {
        OkHttpClient client = new OkHttpClient();
        Request request = new Request.Builder()
                .url(URI.create(key))
                .build();

        Response response;
