#include <limits>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcTag;
    std::atomic<bool> crcFlag{false};
};

std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> dataList;
std::mutex listMutex;
const int MAX_LIST_SIZE = 1000;
std::atomic<int> listSize{0};

void checkRNTI(uint32_t rnti) {
    if (rnti < 1 || rnti > std::numeric_limits<uint32_t>::max() - 1000) {
        std::cerr << "Invalid RNTI: " << rnti << std::endl;
        throw std::invalid_argument("Invalid RNTI");
    }
}

void addToList(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> data) {
    listMutex.lock();
    if (listSize < MAX_LIST_SIZE) {
        dataList.push_back(std::move(data));
        ++listSize;
    } else {
        std::cerr << "List is full, cannot add more elements." << std::endl;
    }
    listMutex.unlock();
}

void threadFunction(uint32_t startRNTI) {
    srand(time(nullptr));
    for (int i = 0; i < 1000; ++i) {
        uint32_t rnti = startRNTI + i;
        checkRNTI(rnti);

        auto data = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>();
        data->rnti = rnti;
        data->crcFlag.store(rand() % 2);

        listMutex.lock();
        auto it = std::find_if(dataList.begin(), dataList.end(),
                               [&](const auto &ptr) { return ptr->rnti == rnti; });
        if (it == dataList.end()) {
            addToList(std::move(data));
        } else {
            it->crcFlag.store((*it)->crcFlag.load() ^ 1);
        }
        listMutex.unlock();
    }
}

int main() {
    std::thread threads[4];
    for (size_t i = 0; i < arraysize(threads); ++i) {
        threads[i] = std::thread(threadFunction, i * 100 + 1);
    }

    for (auto &t : threads) t.join();

    return 0;
}
```

