    PHY_RX_DRB drb;
    PHY_RX_PDSCH_SYMBOL pdsch_symbol;
} LTE_PHY_RX_CONTEXT;

#define MAX_SIZE 1024 // Adjust this value according to your system's memory constraints

static LTE_PHY_RX_CONTEXT* pool = NULL;
static size_t allocated_size = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

LTE_PHY_RX_CONTEXT* allocate_context() {
    if (allocated_size >= MAX_SIZE) return NULL;

    LTE_PHY_RX_CONTEXT* context = &pool[allocated_size];
    allocated_size++;
    return context;
}

void deallocate_context(LTE_PHY_RX_CONTEXT* context) {
    pthread_mutex_lock(&mutex);
    if (--allocated_size == 0) { // All memory has been freed, free the pool
        free(pool);
        pool = NULL;
    }
    pthread_mutex_unlock(&mutex);
}
```

This code defines a dynamic memory pool for `LTE_PHY_RX_CONTEXT` structures. The `allocate_context()` function manages the allocation of new contexts, while the `deallocate_context()` function frees previously allocated ones.

The `pthread_mutex_t` mutex ensures thread safety by preventing concurrent access to the memory pool. The maximum size of the pool is defined as a constant (MAX_SIZE), and the pool itself is a global variable.

