using System;
using UnityEngine;

public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;

    public RandomValueGenerator(float min, float max)
    {
        if (min > max)
            Swap(ref min, ref max);
        AdjustRange(min);
    }

    private void AdjustRange(float value)
    {
        this.minValue = Mathf.Max(value - float.MaxValue / 2f, float.MinValue);
        this.maxValue = Mathf.Min(value + float.MaxValue / 2f, float.MaxValue);
    }

    private void Swap(ref float a, ref float b)
    {
        float temp = a;
        a = b;
        b = temp;
    }

    public float GetRandomFloat() => UnityEngine.Random.Range(minValue, maxValue + 1);

    public float GetRandomFloatExclusive() => UnityEngine.Random.Range(minValue, maxValue);

    public int GetRandomInt() => (int)UnityEngine.Random.Range((long)Mathf.Round(minValue), (long)Mathf.Ceil(maxValue) + 1);

    public int GetRandomIntExclusive() => (int)UnityEngine.Random.Range((long)Mathf.Floor(minValue), (long)Mathf.Ceil(maxValue));

    public void AdjustRange(float offset) => AdjustRange(minValue + offset);

    public override string ToString() => $"[{minValue}, {maxValue}]";
}
