    CRC_INDICATION_REL8_TAG crc_indication;
};

class DynamicList {
public:
    DynamicList(size_t initialCapacity, bool enableLogging) : capacity_(initialCapacity), logging_(enableLogging) {}

    NFAPI_CRC_INDICATION_PDU_T* allocate() {
        if (data_.empty()) {
            data_.reserve(capacity_);
            for (size_t i = 0; i < capacity_; ++i) {
                data_.emplace_back();
                auto& pdu = data_.back();
                pdu.rnti.value = i + minRnti_;
                pdu.crc_indication.valid = true;
                if (logging_) {
                    std::cout << "Allocated PDU with RNTI: " << pdu.rnti.value << std::endl;
                }
            }
            return &data_.back();
        }
        auto& last = data_.back();
        if (last.crc_indication.valid) {
            ++lastRNTI_;
            last.rnti.value = lastRNTI_;
            if (logging_) {
                std::cout << "Reused PDU with RNTI: " << last.rnti.value << std::endl;
            }
        } else {
            data_.pop_back();
            data_.emplace_back();
            auto& newLast = data_.back();
            newLast.rnti.value = lastRNTI_;
            ++lastRNTI_;
            if (logging_) {
                std::cout << "Allocated new PDU with RNTI: " << newLast.rnti.value << std::endl;
            }
        }
        return &data_.back();
    }

    void validate() {
        std::map<int, bool> rntiMap;
        for (const auto& pdu : data_) {
            if (!rntiMap.emplace(pdu.rnti.value, true).second) {
                if (logging_) {
                    std::cerr << "RNTI collision: " << pdu.rnti.value << std::endl;
                }
            }
        }
    }

    void process(std::function<void(NFAPI_CRC_INDICATION_PDU_T&)> func) {
        for (auto& pdu : data_) {
            func(pdu);
        }
    }

private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data_;
    size_t capacity_{};
    int lastRNTI_{minRnti_};
    bool logging_{};
    static constexpr int minRnti_ = 0;
};

class Service {
public:
    Service(DynamicList& list, double workloadFactor, std::chrono::milliseconds minDelay, std::chrono::milliseconds maxDelay)
        : list_(list), workloadFactor_(workloadFactor), minDelay_(minDelay), maxDelay_(maxDelay), rng_(std::random_device{}()), timer_(ioService_) {}

    void start() {
        auto delay = std::chrono::duration<double>(rng_()) * (maxDelay_ - minDelay_);
        std::cout << "Starting service after " << delay.count() << " ms" << std::endl;
        std::this_thread::sleep_for(delay);
        list_.process([&](auto& pdu) {
            if (!pdu.crc_indication.valid) {
                pdu.crc_indication.valid = generateCRCFlag();
                if (logging_) {
                    std::cout << "Generated CRC flag for PDU with RNTI: " << pdu.rnti.value << std::endl;
                }
            }
        });
        list_.validate();
        stop_ = true;
        ioService_.post([this]() { start(); });
    }

    void stop() {
        stop_ = true;
        ioService_.stop();
        if (logging_) {
            std::cout << "Stopping service" << std::endl;
        }
    }

private:
    bool generateCRCFlag() {
        // Implement a rolling hash function or random number generator here.
        return true;
    }

    DynamicList& list_;
    double workloadFactor_;
    std::chrono::milliseconds minDelay_, maxDelay_;
    std::random_device rng_;
    boost::asio::io_service ioService_;
    bool stop_{};
};
```

