    TCP_STATE_INFO_T* current = NULL;
    while (num_connections > 0) {
        TCP_STATE_INFO_T connection;
        fread(&connection, sizeof(TCP_STATE_INFO_T), 1, file);
        if (head == NULL) {
            head = &connection;
            current = head;
        } else {
            current->next = &connection;
            current = current->next;
        }
        num_connections--;
    }

    fclose(file);
}
