void processFilePath(const std::string& filePath, size_t bufferSize, char* buffer, size_t bufferSizeChars) {
    if (!filePath.empty() && buffer && bufferSizeChars >= filePath.size()) {
        boost::filesystem::path path(filePath);
        std::string separator = path.filename().empty() ? "/" : path.preferred_separator();
        size_t newLength = path.string().size() + separator.size();

