    char *data = malloc(len);
    if (!data) return -1;

    if (1 != EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), rsa, (const unsigned char*)passphrase, strlen(passphrase), i = 0, key.iv, key.key)) {
        free(data);
        return -1;
    }

    memcpy(iv, key.iv, AES_BLOCK_SIZE);
    AES_set_encrypt_key(key.key, 1, &key.iv);

    for (i = 0; i < num_packets; ++i) {
        size_t packet_len = sizeof(packets[i]);
        unsigned char *packet = malloc(packet_len);
        if (!packet) {
            free(data);
            return -1;
        }
        memcpy(packet, &packets[i], packet_len);

        AES_cbc_encrypt(packet, data + i * len / num_packets, packet_len, &key, iv, AES_ENCRYPT);
    }

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, data);
        curl_easy_setopt(curl, CURLOPT_UPLOAD, 1L);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, curl_slist_append(NULL, "Content-Type: application/octet-stream"));
        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            int num_retries = 3;
            while (num_retries-- > 0 && res == CURLE_OPERATION_TIMEDOUT || res == CURLE_FAILED_INIT) {
                curl_easy_reset(curl);
                res = curl_easy_perform(curl);
            }
        }

        if (res != CURLE_OK) {
            fprintf(stderr, "Failed to upload data: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }

    free(data);
    return res != CURLE_OK ? -1 : 0;
}

void cleanupAES256CBC(AES_KEY* key) {
    if (key) {
        EVP_cleanup();
        memset(key, 0, sizeof(*key));
    }
}
```

