#include <time.h>
#include <lws.h>

typedef struct {
    enum { TEMP, HUMIDITY, PRESSURE } type;
    union {
        double temperature;
        double humidity;
        double pressure;
    } data;
    time_t timestamp;
} sensor_data;

struct context {
    struct lws_context *ctx;
    struct lws *wsi;
    sensor_data *buffer;
    size_t buffer_size;
    size_t buffer_index;
};

int streamSensorData(struct context *ctx, const char *server_endpoint) {
    // Initialize libwebsockets context and WebSocket
    ctx->ctx = lws_create_context(&g_lws_context, NULL, 0);
    if (!ctx->ctx) return -1;

    ctx->wsi = lws_client_connect(ctx->ctx, server_endpoint, NULL, 0);
    if (!ctx->wsi) {
        lws_context_destroy(ctx->ctx);
        return -1;
    }

    // Allocate buffer for sensor data
    ctx->buffer = malloc(sizeof(sensor_data) * ctx->buffer_size);
    if (!ctx->buffer) {
        lws_client_reconnect(ctx->wsi);
        return -1;
    }

    // Main event loop
    while (1) {
        // Process sensor data and store in buffer
        // ...

        // Send buffered data over WebSocket
        if (lws_write(ctx->wsi, ctx->buffer, sizeof(sensor_data) * ctx->buffer_index, LWS_WRITE_TEXT) != 0) {
            perror("lws_write");
            break;
        }

        // Clear buffer and continue processing new data
        memmove(ctx->buffer, ctx->buffer + ctx->buffer_index, (ctx->buffer_size - ctx->buffer_index) * sizeof(sensor_data));
        ctx->buffer_index = 0;
    }

    free(ctx->buffer);
    lws_client_free_websockets(ctx->wsi);
    lws_context_destroy(ctx->ctx);

    return 0; // Success
}
