typedef struct {
    int cell_id;
    int ue_id;
    struct RRC_message *rrc_messages; // Pointer to the first RRC message in the list
    int rrc_count;                     // Number of RRC messages in the list
    int capacity;                      // Maximum number of RRC messages per context
} LTE_UE_Context;

typedef struct RRC_message {
    char data[100]; // Fixed-size buffer for each message
    struct RRC_message *next;
} RRC_message;

LTE_UE_Context* create_context() {
    LTE_UE_Context* context = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
    context->cell_id = rand();
    context->ue_id = rand();
    context->rrc_messages = NULL;
    context->rrc_count = 0;
    context->capacity = 50;
    return context;
}

void add_rrc_message(LTE_UE_Context* context, const char* message) {
    RRC_message* new_message = (RRC_message*)malloc(sizeof(RRC_message));
    strcpy(new_message->data, message);
    new_message->next = context->rrc_messages;
    context->rrc_messages = new_message;
    context->rrc_count++;

    if (context->rrc_count == context->capacity) {
        context->capacity *= 2;
        context->rrc_messages = realloc(context->rrc_messages, context->capacity * sizeof(RRC_message));
    }
}

void free_context(LTE_UE_Context* context) {
    RRC_message* current = context->rrc_messages;
    while (current != NULL) {
        RRC_message* temp = current;
        current = current->next;
        free(temp);
    }
    free(context);
}

void process_contexts(LTE_UE_Context** contexts, int count) {
    for (int i = 0; i < count; ++i) {
