class CRCManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::unordered_map<uint32_t, size_t> rntiMap;
    std::mutex mtx;
    std::random_device rd;
    std::mt19937 gen;
    uint32_t minRNTI = 0;
    uint32_t maxRNTI = 10000;

public:
    CRCManager() : gen(rd()) {
        gen <<= static_cast<uint32_t>(std::chrono::high_resolution_clock::now().time_since_epoch().count());
    }

    void add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(mtx);

        if (rntiMap.find(pdu.rnti) != rntiMap.end()) {
            throw std::invalid_argument("Invalid RNTI value");
        }

        pdu.crcIndication.crcFlag = gen();
        data.push_back(pdu);
        rntiMap[pdu.rnti] = data.size() - 1;
    }

    NFAPI_CRC_INDICATION_PDU_T get(uint32_t rnti) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = rntiMap.find(rnti);
        if (it == rntiMap.end()) {
            throw std::out_of_range("RNTI not found");
        }

        return data[it->second];
    }

    void remove(uint32_t rnti) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = rntiMap.find(rnti);
        if (it == rntiMap.end()) {
            throw std::out_of_range("RNTI not found");
        }

        rntiMap.erase(it);
        data[it->second].crcIndication.crcFlag = 0; // Set CRCFLAG to a known value for cleanup
        data.erase(it->second);
    }

    void cleanUp() {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = rntiMap.begin();
        while (it != rntiMap.end()) {
            if (data[it->second].crcIndication.crcFlag == 0) {
                it->second = rntiMap.end()->second;
                rntiMap.erase(it++);
                data.pop_back();
            } else {
                ++it;
            }
        }
    }
};
