                return &current->data;
            }
            current = current->next.get();
        }
        return nullptr;
    }

    void prune(std::uint64_t expirationThreshold) {
        auto current = _head.get();
        std::unique_ptr<ListNode> temp;
        while (current) {
            if (current->data.timestamp.ticks < expirationThreshold) {
                temp = std::move(current);
                current = current->next.get();
                _head = std::move(temp);
            } else {
