class RangeManager {
public:
    void addRange(uint32_t start, uint32_t end) {
        if (start >= end || ranges.empty()) {
            throw std::invalid_argument("Invalid range or no existing ranges");
        }
        ranges.push_back({start, end});
    }

    void removeRange(uint32_t start) {
        auto it = std::find_if(ranges.begin(), ranges.end(), [start](const auto& range) { return range.first <= start; });
        if (it == ranges.end()) {
            throw std::out_of_range("Range not found");
        }
        ranges.erase(it);
    }

private:
