```c
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct LTEPHYCONTEXT {
    int bandwidth;
    double center_frequency;
    enum MODULATION_SCHEME modulation_scheme;
    pthread_mutex_t lock;
} LTEPHYCONTEXT;

typedef struct NODE {
    LTEPHYCONTEXT context;
    struct NODE* next;
    pthread_cond_t cond;
} NODE;

NODE* head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void init_context(LTEPHYCONTEXT* context) {
    pthread_mutex_init(&context->lock, NULL);
}

void destroy_context(LTEPHYCONTEXT* context) {
    pthread_mutex_destroy(&context->lock);
}

NODE* create_node(const LTEPHYCONTEXT* context) {
    NODE* new_node = malloc(sizeof(NODE));
    if (!new_node) return NULL;

    *new_node = (NODE){ .context = *context };
    new_node->next = NULL;
    pthread_cond_init(&new_node->cond, NULL);

    return new_node;
}

void insert(const LTEPHYCONTEXT* context) {
    NODE* new_node = create_node(context);
    if (!new_node) return;

    pthread_mutex_lock(&list_lock);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&list_lock);
}

LTEPHYCONTEXT* find(int channel_id) {
    LTEPHYCONTEXT* result = NULL;
    pthread_mutex_lock(&list_lock);
    for (NODE* current = head; current != NULL; current = current->next) {
        pthread_mutex_lock(&current->context.lock);
        if (current->context.channel_id == channel_id) {
            result = &current->context;
            break;
        }
        pthread_mutex_unlock(&current->context.lock);
    }
    pthread_mutex_unlock(&list_lock);

    return result;
}

void update(int channel_id, const LTEPHYCONTEXT* new_context) {
    LTEPHYCONTEXT* context = find(channel_id);
    if (!context) return;

    pthread_mutex_lock(&context->lock);
    *context = *new_context;
    pthread_mutex_unlock(&context->lock);
}

void on_update(const LTEPHYCONTEXT* new_context, void (*callback)(const LTEPHYCONTEXT*)) {
    if (!new_context) return;

    pthread_mutex_lock(&new_context->lock);
    callback(new_context);
    pthread_mutex_unlock(&new_context->lock);
}
```

