struct PDUAllocator : public std::allocator<NFAPI_CRC_INDICATION_PDU_T> {
    using value_type = NFAPI_CRC_INDICATION_PDU_T;
    using pointer = value_type*;
    using const_pointer = const value_type*;
    using size_type = std::size_t;

    PDUAllocator() : blockSize_(1024) {}

    pointer allocate(size_type n, const allocator_type&) {
        if (n > blockSize_) {
            auto* result = static_cast<value_type*>(operator new(n * sizeof(value_type)));
            return result;
        }

        auto* result = blocks_.empty() ? static_cast<value_type*>(operator new(blockSize_ * sizeof(value_type))) : blocks_.back();
        blocks_.pop_back();
        std::fill_n(result, n, value_type{});
        return result;
    }

    void deallocate(pointer p, const allocator_type&) {
        if (!blocks_.empty() && static_cast<size_t>(std::distance(p, blocks_.back())) == blockSize_) {
            blocks_.push_back(p);
        } else {
            operator delete(p);
        }
    }

    std::vector<value_type*> blocks_;
    size_type blockSize_;
};

std::mutex pduListMutex;
