        auto& pdu = pduList.back();
        pdu.RX_UE_INFORMATION_TAG = /* initialize RX_UE_INFORMATION_TAG */;
        pdu.RNTI = distr(gen);
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = distr(gen) % 2;
        pduList.pop_back();
