```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <memory>
#include <cstdlib>
#include <ctime>
#include <cerrno>
#include <stdexcept>
#include <boost/log/trivial.hpp>

struct Record {
    int value1;
    int value2;
    int average;
};

class MemoryPool {
public:
    MemoryPool(size_t blockSize) : buffer_(nullptr), blockSize_(blockSize), allocatedBlocks_(0) {}

    void* allocate() {
        if (allocatedBlocks_ == 0 && buffer_ == nullptr) {
            buffer_ = std::make_unique<char[]>(initialBlockSize_);
            allocatedBlocks_++;
        }

        if (static_cast<size_t>(offset_) + blockSize_ > bufferSize_) {
            BOOST_LOG_TRIVIAL(error) << "Out of memory";
            throw std::runtime_error("Out of memory");
        }

        auto result = &buffer_[offset_];
        offset_ += blockSize_;
        allocatedBlocks_++;
        return result;
    }

    void deallocate(void* ptr) {
        if (ptr >= buffer_ && ptr < buffer_.get() + bufferSize_) {
            allocatedBlocks_--;
        } else {
            BOOST_LOG_TRIVIAL(error) << "Invalid pointer";
            throw std::runtime_error("Invalid pointer");
        }
    }

private:
    static constexpr size_t initialBlockSize_ = 1024;
    std::unique_ptr<char[]> buffer_;
    size_t blockSize_ = 0;
    size_t offset_ = 0;
    size_t allocatedBlocks_ = 0;
    size_t bufferSize_ = initialBlockSize_;
};

void parseLine(const std::string& line, Record* record, long* offset, int* key) {
    std::istringstream iss(line);
    std::string field;
    int index = 0;

    while (std::getline(iss, field, '\t')) {
        switch (index++) {
            case *key:
                record->value1 = std::stoi(field);
                break;
            case *(key + 1):
                record->value2 = std::stoi(field);
                break;
            default:
                // Ignore extra fields
                break;
        }
    }

    if (index < *(key + 1) + 1) {
        BOOST_LOG_TRIVIAL(error) << "Invalid line format";
        throw std::runtime_error("Invalid line format");
    }

    *offset += line.size() + 1; // +1 for newline character
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        BOOST_LOG_TRIVIAL(error) << "Usage: " << argv[0] << " inputFile outputFile";
        return 1;
    }

    std::ifstream inputFile(argv[1], std::ios::binary);
    if (!inputFile.is_open()) {
        BOOST_LOG_TRIVIAL(error) << "Could not open input file: " << strerror(errno);
        return 2;
    }

    std::ofstream outputFile(argv[2], std::ios::binary);
    if (!outputFile.is_open()) {
        BOOST_LOG_TRIVIAL(error) << "Could not open output file: " << strerror(errno);
        return 3;
    }

    MemoryPool memoryPool(4096); // Adjust block size as needed
    std::vector<Record> records;
    long offset = 0;
    int key = 2; // Adjust key as needed

    char buffer[1024];
    while (inputFile.getline(buffer, sizeof(buffer))) {
        auto recordPtr = static_cast<Record*>(memoryPool.allocate());
        parseLine(buffer, recordPtr, &offset, &key);
        recordPtr->average = (recordPtr->value1 + recordPtr->value2) / 2;
        records.push_back(*recordPtr);
        memoryPool.deallocate(recordPtr);
    }

    // Save the averages to the output file
    for (const auto& record : records) {
        std::ostream_iterator<int> out_it(outputFile, "\t");
        *out_it << record.value1; ++out_it;
        *out_it << record.value2; ++out_it;
        *out_it << record.average; ++out_it;
    }

    return 0;
}
