```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace DynamicValueGenerator
{
    public class DynamicValueGenerator
    {
        private readonly Random _random;
        private double _minFloat;
        private double _maxFloat;
        private int _minInt;
        private int _maxInt;
        private bool _isInclusive;
        private List<(DateTime timestamp, double value, int index)> _loggedFloats = new List<(DateTime timestamp, double value, int index)>();
        private List<(DateTime timestamp, int value, int index)> _loggedInts = new List<(DateTime timestamp, int value, int index)>();
        private const int MaxLogEntries = 100;

        public DynamicValueGenerator()
        {
            _random = new Random();
            ResetToDefaults();
        }

        public void SetRange(double minFloat, double maxFloat, bool isInclusive, int minInt, int maxInt, bool includeFloat = true, bool includeInt = true)
        {
            if (includeFloat)
                _minFloat = minFloat;
            if (includeInt)
                _minInt = minInt;

            _maxFloat = maxFloat;
            _maxInt = maxInt;
            _isInclusive = isInclusive;
        }

        public double GetRandomFloat()
        {
            var value = _random.NextDouble() * (_maxFloat - _minFloat) + _minFloat;
            if (!_isInclusive && value >= _maxFloat || value <= _minFloat)
                return _random.NextDouble() * (_maxFloat - _minFloat) + _minFloat;
            LogValue(value);
            return value;
        }

        public int GetRandomInt()
        {
            var value = _random.Next(_minInt, _maxInt + 1);
            if (!_isInclusive && (value == _minInt || value == _maxInt))
                value = _random.Next(_minInt, _maxInt + 1);
            LogValue(value);
            return value;
        }

        public string ToString() => $"MinFloat: {_minFloat}, MaxFloat: {_maxFloat}, MinInt: {_minInt}, MaxInt: {_maxInt}";

        public void ResetToDefaults()
        {
            _minFloat = double.NegativeInfinity;
            _maxFloat = double.PositiveInfinity;
            _minInt = int.MinValue;
            _maxInt = int.MaxValue;
            _isInclusive = true;
            _loggedFloats.Clear();
            _loggedInts.Clear();
        }

        private void LogValue<T>(T value)
        {
            lock (this)
            {
                if (_loggedFloats.Count >= MaxLogEntries && typeof(T) == typeof(double))
                    _loggedFloats.RemoveAt(0);
                else if (_loggedInts.Count >= MaxLogEntries && typeof(T) == typeof(int))
                    _loggedInts.RemoveAt(0);

                var timestamp = DateTime.UtcNow;
                var index = _loggedFloats.Count + _loggedInts.Count;
                if (typeof(T) == typeof(double))
                    _loggedFloats.Add((timestamp, Convert.ToDouble(value), index));
                else
                    _loggedInts.Add((timestamp, Convert.ToInt32(value), index));
            }
        }
    }
}
```

