    bool crcflag;
};

using PDU_T = std::aligned_storage_t<sizeof(NFAPI_CRC_INDICATION_PDU_T), alignof(NFAPI_CRC_INDICATION_PDU_T)>;

class Allocator : public std::allocator<PDU_T> {
public:
    PDU_T* allocate(std::size_type n, std::allocator<void>::const_pointer hint = nullptr) {
        auto ptr = static_cast<PDU_T*>(::operator new(n * sizeof(PDU_T), alignof(NFAPI_CRC_INDICATION_PDU_T)));
        if (ptr == nullptr)
            throw std::system_error(errno, std::generic_category(), "Memory allocation failed");
        return ptr;
    }

    void deallocate(PDU_T* p, std::size_type n) {
        ::operator delete(p);
    }
};

class PDUQueue {
public:
    explicit PDUQueue(std::size_t capacity) : m_queue(capacity), m_allocator(Allocator()) {}

    void enqueue(PDU_T&& pdu) {
        if (m_queue.push(std::move(pdu))) {
            ++m_successfullyAllocated;
        } else {
            std::cerr << "Failed to enqueue PDU: queue is full\n";
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* dequeue() {
        auto pdu = m_queue.pop();
        if (pdu) {
            new (pdu) NFAPI_CRC_INDICATION_PDU_T;
            return &*pdu;
        } else {
            std::cerr << "Failed to dequeue PDU: queue is empty\n";
            return nullptr;
        }
    }

    std::size_t getSuccessfullyAllocated() const {
        return m_successfullyAllocated;
    }

private:
    boost::lockfree::spsc_queue<PDU_T, Allocator> m_queue;
    std::size_t m_successfullyAllocated = 0;
    Allocator m_allocator;
};

void createPDUs(PDUQueue& pduQueue, size_t count) {
    boost::random::mt19937 generator;
    for (size_t i = 0; i < count; ++i) {
        auto pdu = pduQueue.dequeue();
        if (pdu) {
            new (pdu) NFAPI_CRC_INDICATION_PDU_T;
            pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG{}; // Initialize RX_UE_INFORMATION_TAG as needed
            pdu->rnti = i + 1;
            pdu->crc_indication_rel8_tag.crcflag = bool(generator() % 2);
        }
    }
}
