// Custom allocator for aligned memory blocks
void* custom_malloc(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return align_memory((uint8_t*)ptr, size);
}

// Align memory to a specified boundary
void* align_memory(void* ptr, size_t alignment, size_t size) {
    size_t new_size = ((size + alignment - 1) / alignment) * alignment;
    void* aligned_ptr = realloc(ptr, new_size);
    if (!aligned_ptr) {
        perror("realloc");
        exit(EXIT_FAILURE);
    }
    memset((uint8_t*)aligned_ptr + size, 0, new_size - size);
    return aligned_ptr;
}

// Custom free function for deallocating memory blocks
void custom_free(void* ptr) {
    munmap(ptr, malloc_usable_size((void*)ptr));
}

