[' I will provide you with a simplified C++ solution that addresses some of the constraints mentioned above. This code uses a `std::vector` for dynamic array management, `std::mutex` for thread safety, and custom allocator for memory management. The logging mechanism records the number of messages added and any errors encountered during memory allocation.

```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <new>
#include <stdexcept>
#include <chrono>
#include <atomic>

struct Message {
    int sender_id;
    std::uint64_t timestamp;
    std::string payload;
};

class CustomAllocator : public std::allocator<Message> {
public:
    using value_type = Message;
    using pointer = value_type*;
    using const_pointer = const value_type*;
    using reference = value_type&;
    using const_reference = const value_type&;
    using size_type = std::size_t;
    using difference_type = std::ptrdiff_t;

    CustomAllocator() : _logged_errors(0) {}

    pointer allocate(size_type n, const allocator_traits<CustomAllocator>::construct_params& params) {
        try {
            return std::allocator<Message>::allocate(n);
        } catch (std::bad_alloc& e) {
            ++_logged_errors;
            throw;
        }
    }

    void deallocate(pointer p, size_type n) noexcept {
        std::allocator<Message>::deallocate(p, n);
    }

    void construct(pointer p, const value_type& val) {
        new (static_cast<void*>(p)) value_type(val);
    }

    void destroy(pointer p) noexcept {
        static_cast<value_type*>(p)->~Message();
    }

    std::atomic<size_t> _logged_errors;
};

std::vector<Message, CustomAllocator> messages;
std::mutex mtx;

void append_message(const Message& msg) {
    std::lock_guard<std::mutex> lock(mtx);
    messages.push_back(msg);
}

int main() {
    // ... (thread creation, message processing, etc.)

    std::cout << "Total messages added: " << messages.size() - messages._Mylast << "\n";
    std::cout << "Logged errors: " << messages._Myptr->CustomAllocator::_logged_errors << "\n";
}
