```c
aes_context* aes_init(const unsigned char* password, size_t password_len,
                       const unsigned char* salt, size_t salt_len) {
    // Allocate memory for the context and key derivation.
    aes_context* ctx = malloc(sizeof(aes_context));
    if (!ctx) return NULL;

    // Derive the key using PBKDF2 implementation.
    unsigned char prk[KEY_LENGTH];
    pbkdf2(password, password_len, salt, salt_len, prk, KEY_LENGTH);

    // Initialize AES context with derived key and IV.
    EVP_CIPHER_CTX_init(ctx->ctx);
    EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, prk, ctx->iv);

    // Copy the derived key and IV for future use.
    memcpy(ctx->key, prk, KEY_LENGTH);
    memcpy(ctx->iv, ctx->iv, IV_LENGTH);

    return ctx;
}
```

5. Encrypt data using AES context:

```c
int aes_encrypt(aes_context* ctx, unsigned char* plaintext, size_t plaintext_len,
                unsigned char* ciphertext) {
    // Allocate memory for the ciphertext.
    if (plaintext_len > INT_MAX - IV_LENGTH) return -1;
    unsigned char* buf = malloc(plaintext_len + IV_LENGTH);
    if (!buf) return -1;

    // Copy IV to the beginning of the buffer.
    memcpy(buf, ctx->iv, IV_LENGTH);

    // Encrypt the plaintext and write the ciphertext into the buffer.
    int len = 0;
    EVP_EncryptUpdate(ctx->ctx, buf + IV_LENGTH, &len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx->ctx, buf + len, &len);

    // Copy the ciphertext into the provided buffer.
    memcpy(ciphertext, buf, len);

    free(buf);
    return len;
}
```

