int aes_update_salt(aes_context* ctx, const unsigned char* new_salt, size_t new_salt_len) {
    // Derive the new key using PBKDF2 implementation.
    unsigned char prk[KEY_LENGTH];
    pbkdf2(ctx->key, KEY_LENGTH, new_salt, new_salt_len, prk, KEY_LENGTH);

    // Update the derived key in the context.
    memcpy(ctx->key, prk, KEY_LENGTH);
    return 0;
}
