            perror("Error reading key");
            return NULL;
        }

        fseek(file, sizeof(long) + sizeof(int), SEEK_CUR); // Skip timestamp

        if (*num_records >= 10000) {
            break;
        }

        Record *record = realloc(*records, sizeof(Record) * (*num_records + 1));
        if (!record) {
            perror("Error allocating memory");
            return NULL;
        }

        record[*num_records].offset = offset;
        record[*num_records].key = key;
        record[*num_records].timestamp = rand() % 101; // Random timestamp between 0.0 and 100.0
        (*num_records)++;
