class DynamicLinkedList {
public:
    DynamicLinkedList() : m_queue(10000), m_elements(), m_mutex() {}

    void addElement(const NFAPI_CRC_INDICATION_PDU_T& element) {
        auto it = m_elements.emplace(std::piecewise_construct, std::make_pair(element.rnti, element.tag), element);
        if (it != m_elements.end()) {
            m_queue.push(it->first);
        }
    }

    bool removeDuplicates() {
        std::unordered_map<std::pair<uint32_t, uint16_t>, NFAPI_CRC_INDICATION_PDU_T> temp;
        while (!m_queue.empty()) {
            auto rnti = m_queue.front();
            m_queue.pop();
            auto it = m_elements.find(rnti);
            if (it != m_elements.end() && temp.count(it->second) == 0) {
                temp.emplace(it->second, it->first);
            }
        }
        std::swap(m_elements, temp);
        return !m_queue.empty();
    }

    bool isEmpty() const {
        return m_queue.size() == 0 && m_elements.size() == 0;
    }

private:
