#include <mutex>
#include <stdexcept>
#include <cstdint>
#include <pthread.h>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint32_t checksum; // precomputed checksum for each structure
};

class CRCList {
private:
    std::list<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> data;
    std::mutex mtx;
    pthread_cond_t notEmpty = PTHREAD_COND_INITIALIZER;
    pthread_cond_t notFull = PTHREAD_COND_INITIALIZER;

public:
    CRCList(size_t capacity) {
        data.reserve(capacity);
    }

    void append(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> pdu) {
        std::lock_guard<stdat::mutex> lock(mtx);

        while (data.size() >= data.capacity()) {
            pthread_cond_wait(&notFull, &mtx.native_handle());
        }

        data.push_back(std::move(pdu));
        pthread_cond_signal(&notEmpty);
    }

    size_t size() const {
        std::lock_guard<stdat::mutex> lock(mtx);
        return data.size();
    }

    bool popFront(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        std::lock_guard<stdat::mutex> lock(mtx);

        if (data.empty()) {
            pthread_cond_wait(&notEmpty, &mtx.native_handle());
        }

        if (!data.empty()) {
            *pdu = *data.begin();
            data.pop_front();
            pthread_cond_signal(&notFull);
            return true;
        } else {
            return false;
        }
    }
};
```

