pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
pthread_key_t key;
static void (*log_func)(const char*, ...) = NULL;

void init_logging(void (*log_func)(const char*, ...)) {
    pthread_key_create(&key, NULL);
    this_thread_key_current(key);
    this_thread_key_setspecific(key, log_func);
}

void log(const char *format, ...) {
