    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        log("Error: Failed to allocate memory for %d elements", N);
        pthread_rwlock_unlock(&rwlock);
        return NULL;
    }

    log("Allocated memory for %d elements", N);
