int capacity = 0;
LTE_PHY_RX_FRAME_INFO_T* frames = NULL;
const int MIN_CELL_ID = 1;
const int MAX_CELL_ID = 100;

void init(int m) {
    if (m <= 0) return;
    capacity = m;
    frames = calloc(capacity, sizeof(LTE_PHY_RX_FRAME_INFO_T));
    if (!frames) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void resize() {
    int new_capacity = capacity * 2;
    LTE_PHY_RX_FRAME_INFO_T* new_frames = realloc(frames, new_capacity * sizeof(LTE_PHY_RX_FRAME_INFO_T));
    if (!new_frames) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    frames = new_frames;
    capacity = new_capacity;
}

void add_frame(LTE_PHY_RX_FRAME_INFO_T frame) {
    pthread_mutex_lock(&mutex);
    if (capacity == 0) init(1);
    else if (capacity == size) resize();

    frame.cell_id = (frame.cell_id < MIN_CELL_ID || frame.cell_id > MAX_CELL_ID) ? MIN_CELL_ID : frame.cell_id;
    frames[size++] = frame;
    pthread_mutex_unlock(&mutex);
}

void update_power_level(LTE_PHY_RX_FRAME_INFO_T* frame, int window_size) {
    static double power_sum = 0.0;
    static int count = 0;

    if (count >= window_size) {
        power_sum -= frames[count - window_size].power_level;
    }
    power_sum += frame->power_level;
    count = (count + 1) % window_size;

    frame->power_level = power_sum / count;
}
