struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *next;
};

struct list {
    struct list_node *head;
    struct list_node *tail;
    size_t size;
    pthread_mutex_t lock;
};

void init_list(struct list *list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void free_list(struct list *list) {
    struct list_node *current = list->head;
    while (current != NULL) {
        struct list_node *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

void push_back(struct list *list, NFAPI_CRC_INDICATION_PDU_T data) {
    struct list_node *new_node = malloc(sizeof(struct list_node));
    if (new_node == NULL) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* pop_front(struct list *list) {
    if (list->head == NULL) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = &list->head->data;
    struct list_node *temp = list->head;
    list->head = list->head->next;

    if (list->head == NULL) {
        list->tail = NULL;
    }

    free(temp);
    list->size--;
    return result;
}

