    List(size_t chunkSize, size_t maxSize) : _chunkSize(chunkSize), _maxSize(maxSize), _data(), _mutex() {}

    void push_back(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(_mutex);
        if (_data.size() >= _maxSize) {
            std::cerr << "Error: List is full.\n";
            return;
        }
        _data.emplace_back(pdu);
        auto start = std::chrono::high_resolution_clock::now();
        _data.back().crcIndication.crcFlag = rand() % 2;
        auto end = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();
        _stats.emplace_back(pdu, duration);
        if (_data.size() > _maxSize / 2) {
