        for (auto& pdu : _data) {
            // Process the PDU here using a separate thread pool.
        }
        _data.clear();
    }

    size_t getSize() const { return _data.size(); }

private:
    void adjustChunkSize() {
        size_t newChunkSize = (_maxSize / _data.size()) * 2;
        if (newChunkSize > _chunkSize) {
            _chunkSize = newChunkSize;
        }
    }

    std::vector<NFAPI_CRC_INDICATION_PDU_T> _data;
    std::mutex _mutex;
    size_t _chunkSize;
    size_t _maxSize;
    std::vector<std::pair<NFAPI_CRC_INDICATION_PDU_T, uint64_t>> _stats;
};

int main() {
