```java
import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ConcurrentHashGenerator {
    private static final Logger LOGGER = LoggerFactory.getLogger(ConcurrentHashGenerator.class);
    private final Map<Integer, BigInteger> hashes;
    private final ExecutorService executor;
    private final BlockingQueue<String> taskQueue;

    public ConcurrentHashGenerator(int corePoolSize, int maximumPoolSize, int queueCapacity) {
        this.hashes = new ConcurrentHashMap<>();
        this.executor = Executors.newFixedThreadPool(corePoolSize, r -> new Thread(r, "ConcurrentHashGenerator-" + r.hashCode()));
        this.taskQueue = new LinkedBlockingQueue<>(queueCapacity);
    }

    public void addTask(String input) {
        taskQueue.add(input);
    }

    public BigInteger getHash(int index) {
        return hashes.getOrDefault(index, null);
    }

    public void shutdown() {
        executor.shutdown();
    }

    private final class HashTask implements Runnable {
        private String input;

        public HashTask(String input) {
            this.input = input;
        }

        @Override
        public void run() {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] digest = md.digest(input.getBytes());
                BigInteger hash = new BigInteger(1, digest);
                hashes.put(hashes.size(), hash);
                LOGGER.info("Generated MD5 hash for input {}: {}", input, hash);
            } catch (NoSuchAlgorithmException e) {
                LOGGER.error("Failed to generate MD5 hash for input {}: {}", input, e.getMessage());
            }
        }
    }

    public void processTasks() {
        while (!taskQueue.isEmpty() || !executor.isTerminated()) {
            Runnable task = taskQueue.poll();
            if (task != null) {
                executor.execute(new HashTask(task));
            }
        }
    }
}
```

This code creates a `ConcurrentHashGenerator` class that uses an ExecutorService to manage a thread pool for generating MD5 hashes concurrently. The utility stores the generated hashes in a thread-safe map using string indices as keys. It also includes error handling, logging, and a method to add tasks (strings) to be processed.

