import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.logging.Level;
import java.util.logging.Logger;

public class AsyncMD5Hasher {
    private static final Logger LOGGER = Logger.getLogger(AsyncMD5Hasher.class.getName());
    private static final ExecutorService EXECUTOR = Executors.newCachedThreadPool();
    private static final int MAX_CONCURRENT_REQUESTS = 100;
    private static final Map<String, Long> hashCounts = new HashMap<>();

    public void process(String input, String identifier) {
        Runnable task = () -> {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                long timestamp = System.currentTimeMillis();
                String hashedInput = String.format("%s_%d", hash(input, md), timestamp);
                synchronized (hashCounts) {
                    if (!hashCounts.containsKey(hashedInput)) {
                        hashCounts.put(hashedInput, 1L);
                    } else {
                        hashCounts.put(hashedInput, hashCounts.get(hashedInput) + 1);
                    }
                }
                LOGGER.log(Level.INFO, "Generated MD5 hash: {0} for identifier: {1}", new Object[]{hashedInput, identifier});
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Error generating MD5 hash for input: {0}", input);
            }
        };

        EXECUTOR.submit(task);

        synchronized (hashCounts) {
            while (EXECUTOR.getActiveCount() >= MAX_CONCURRENT_REQUESTS) {
                try {
                    hashCounts.wait();
                } catch (InterruptedException e) {
                    LOGGER.log(Level.WARNING, "Interrupted while waiting for active tasks to complete");
                }
            }
        }
    }

    private static BigInteger hash(String input, MessageDigest md) throws Exception {
        md.update(input.getBytes());
        return new BigInteger(1, md.digest());
    }
}
