typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
    pthread_spinlock_t lock;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_lock(Node* node) {
    pthread_spin_init(&node->lock, 0);
}

void lock(Node* node) {
    pthread_spin_lock(&node->lock);
}

void unlock(Node* node) {
    pthread_spin_unlock(&node->lock);
}

bool is_empty() {
    return head == NULL;
}

void push(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    init_lock(new_node);
    new_node->data = data;
    new_node->next = head;
    head = new_node;
}

Node* pop() {
    Node* temp = head;
    if (temp) {
        head = head->next;
        pthread_spin_destroy(&temp->lock);
        free(temp);
    }
    return head;
}
