std::list<LTEMetric> metrics_list;
std::mutex list_mutex;
std::condition_variable cv;
std::atomic<bool> notifier{false};

auto start = std::chrono::high_resolution_clock::now();
std::atomic<unsigned long> num_elements{0};
const unsigned int max_entries = 10000;
const unsigned int chunk_size = 100;

void grow_list() {
    while (true) {
        std::unique_lock<std::mutex> lock(list_mutex);
        notifier.wait(lock, []{ return metrics_list.size() >= max_entries || notifier.load(); });

        if (metrics_list.size() >= max_entries) {
            // Reached maximum number of entries, do something like clearing the list or rejecting new entries
            metrics_list.clear();
            num_elements = 0;
            notifier = false;
        } else {
            metrics_list.resize(metrics_list.size() + chunk_size);
            num_elements += chunk_size;
            notifier = true;
            cv.notify_all();
        }
    }
}

void add_metric(const LTEMetric& metric) {
