    for (size_t i = 0; i < n; ++i) {
        CRC_INDICATION_REL8_TAG tag;
        tag.rnti = rand() % UINT32_MAX; // Generate random RNTI value

        if (whitelist.find(tag.rnti) != whitelist.end()) {
            // Validate RNTI against the whitelist
            uint16_t crcflag = 0;

            // Generate CRCFLAG using PRNG
            for (uint32_t j = 0; j < 8; ++j) {
                crcflag |= (prng() & 1) << (7 - j);
            }

            tag.tag.tag = rand(); // Generate random RX_UE_INFORMATION_TAG value
            tag.tag.crcflag = crcflag;

            list.push_back(NFAPI_CRC_INDICATION_PDU_T{tag});
        } else {
            log_message("Invalid RNTI detected: " + std::to_string(tag.rnti));
        }
    }
}

void manage_list(std::vector<NFAPI_CRC_INDICATION_PDU_T>& list, size_t buffer_size) {
    size_t processed = 0;
    size_t buffer_index = 0;

    while (processed < list.size()) {
        // Process data in chunks to handle varying data stream rates and network jitter
        size_t chunk_size = std::min(buffer_size, list.size() - processed);

        for (size_t i = 0; i < chunk_size; ++i) {
            auto& pdu = list[processed + i];

            // Adaptive behavior for varying data stream rates and network jitter
            std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 100));

            if (pdu.tag.rnti >= UINT32_MAX || whitelist.find(pdu.tag.rnti) == whitelist.end()) {
                // Skip processing for invalid RNTI values
                log_message("Invalid RNTI detected: " + std::to_string(pdu.tag.rnti));
            } else {
                ++processed;

                if (buffer_index < buffer_size) {
                    // Store processed PDUs in a buffer for further processing or transmission
                    list[buffer_index++] = pdu;
                }
            }
        }
    }

    // Clear the list after processing to ensure efficient memory management
    list.clear();
}
