using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

public class DynamicValueGenerator {
    private readonly Dictionary<string, Range> ranges = new Dictionary<string, Range>();
    private string defaultRangeName = "default";

    public void AddRange(string name, float min, float max) {
        if (ranges.ContainsKey(name)) {
            throw new ArgumentException($"Range with name '{name}' already exists.");
        }

        ranges[name] = new Range { Min = min, Max = max };
    }

    public void RemoveRange(string name) {
        if (!ranges.ContainsKey(name)) {
            throw new ArgumentException($"Range with name '{name}' does not exist.");
        }

        ranges.Remove(name);
    }

    public float GetRandomFloat(string rangeName = default) {
        if (!ranges.TryGetValue(rangeName, out Range range)) {
            range = ranges[defaultRangeName];
        }

        return new Random().NextFloat(range.Min, range.Max);
    }

    public int GetRandomInt(string rangeName = default) {
        float value = GetRandomFloat(rangeName);
        return (int)Math.Floor(value);
    }

    public string GetMD5Hash(string input) {
        using (MD5 md5 = MD5.Create()) {
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hash = md5.ComputeHash(inputBytes);
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) {
                sb.AppendFormat("{0:x2}", b);
            }
            return sb.ToString();
        }
    }

    private class Range {
        public float Min { get; set; }
        public float Max { get; set; }
    }
}
```

