    std::unique_ptr<RNTI> rnti_;
    std::function<RX_UE_INFORMATION_TAG()> tagFunc_;
    std::function<RNTI()> rntiFunc_;
};

class CRCGenerator : public RandomGenerator {
public:
    uint32_t generateCRCFlag() const override {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, UINT32_MAX);
        return dis(gen);
    }
};

std::vector<NFAPI_CRC_INDICATION_PDU_T> createPDUs(unsigned int N, const DataFetcher& dataFetcher, const RandomGenerator& randomGenerator) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdus;
    pdus.reserve(N);

    std::mutex logMutex;

    for (unsigned int i = 0; i < N; ++i) {
        auto pdu = new NFAPI_CRC_INDICATION_PDU_T{};
        pdu->tag = dataFetcher.fetchTag();
        pdu->rnti = dataFetcher.fetchRnti();
        pdu->crcIndication.crcFlag = randomGenerator.generateCRCFlag();

        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "Created PDU with tag: " << pdu->tag << ", RNTI: " << pdu->rnti << ", CRC Flag: " << pdu->crcIndication.crcFlag << '\n';

        pdus.push_back(*pdu);
    }

