void generateUniqueRNTI(NFAPI_CRC_INDICATION_PDU_T& pdu) {
    std::unique_lock<std::mutex> lock(mtx);
    while (uniqueRNTIs.count(pdu.rnti)) {
        ++pdu.rnti;
    }
    uniqueRNTIs[pdu.rnti] = true;
}

void manageArray(std::vector<NFAPI_CRC_INDICATION_PDU_T>& array, int initialSize) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, UINT32_MAX);

    for (size_t i = 0; i < initialSize; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rnti = dis(gen);
        generateUniqueRNTI(pdu);
        array.push_back(pdu);
    }

    int capacity = initialSize;
    while (true) {
        for (auto& pdu : array) {
            try {
                pdu.rnti = dis(gen);
                generateUniqueRNTI(pdu);
                array.push_back(pdu);
            } catch (const std::length_error& e) {
                if (capacity * MIN_GROWTH_FACTOR < array.size()) {
                    capacity *= MIN_GROWTH_FACTOR;
                    array.resize(capacity);
                }
            }
        }
    }
}
