    std::string payload; // Variable-length message
    std::string uniqueIdentifier;
};

class LoggingService {
public:
    virtual void log(const NetworkEvent& event) = 0;
};

class SimpleLoggingService : public LoggingService {
public:
    void log(const NetworkEvent& event) override {
        std::cout << "Logged event: " << event.timestamp.time_since_epoch().count()
                  << ", type: " << event.eventType
                  << ", sourceID: " << event.sourceID
                  << ", payload: " << event.payload
                  << ", uniqueIdentifier: " << event.uniqueIdentifier << std::endl;
    }
};

std::mutex eventsMutex;
std::vector<NetworkEvent> events;
std::atomic_bool running{true};

void producer(LoggingService& loggingService, int numEvents) {
    for (int i = 0; i < numEvents; ++i) {
        auto timestamp = std::chrono::steady_clock::now();
        NetworkEvent event{timestamp, rand(), rand(), "Variable-length message", "UniqueIdentifier"};

        // Dynamic memory allocation for payload using std::make_unique
        event.payload.resize(rand() % 100); // Simulate variable length
        event.payload.assign(numEvents + '0', 'a'); // Fill with random characters

        {
            std::lock_guard<std::mutex> lock(eventsMutex);
            events.push_back(event);
        }

        if (loggingService.log(event)) {
            std::cout << "Produced event: " << event.timestamp.time_since_epoch().count() << std::endl;
        } else {
            std::cerr << "Failed to log event" << std::endl;
        }
    }
}

void consumer(LoggingService& loggingService) {
    while (running) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));

        NetworkEvent event;
        {
            std::lock_guard<std::mutex> lock(eventsMutex);
            if (!events.empty()) {
                event = events.front();
                events.erase(events.begin());
            }
        }

        if (!event.payload.empty() && loggingService.log(event)) {
            std::cout << "Consumed event: " << event.timestamp.time_since_epoch().count() << std::endl;
        } else {
            std::cerr << "Failed to consume event" << std::endl;
        }
    }
}

int main() {
    SimpleLoggingService loggingService;
    std::thread producerThread(producer, std::ref(loggingService), 1000);
    std::thread consumerThread(consumer, std::ref(loggingService));

    // Simulate high-throughput conditions and potential delays in external data sources
    std::this_thread::sleep_for(std::chrono::seconds(5));

    running = false;
    producerThread.join();
    consumerThread.join();

    return 0;
}
