    uint32_t valid_count = 0;
    uint32_t total_count = 0;
    uint32_t allocation_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(allocation_size);
    if (!list) {
        fprintf(stderr, "Memory allocation failed. Retrying with reduced size.\n");
        return create_list(N / 2, min_rnti, max_rnti);
    }

