} Node;

typedef struct {
    unsigned int size;
    unsigned int capacity;
    Node **nodes;
} HashTable;

Node* create_node(RX_UE_INFORMATION_TAG tag, unsigned int rnti, CRC_INDICATION_REL8_TAG crc_indication) {
