    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication = crc_indication;
    new_node->next = NULL;
    return new_node;
}

HashTable* create_hash_table(unsigned int capacity) {
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    ht->size = 0;
    ht->capacity = capacity;
    ht->nodes = calloc(capacity, sizeof(Node*));
    return ht;
}

unsigned int hash_function(unsigned int key, unsigned int capacity) {
    return key % capacity;
}

void resize_hash_table(HashTable *ht) {
    unsigned int new_capacity = ht->capacity * 2;
    Node **new_nodes = calloc(new_capacity, sizeof(Node*));

    for (unsigned int i = 0; i < ht->capacity; ++i) {
        Node *current = ht->nodes[i];
        while (current != NULL) {
            unsigned int index = hash_function(current->rnti, new_capacity);
            Node *next = current->next;
            current->next = new_nodes[index];
            new_nodes[index] = current;
            current = next;
        }
    }

    free(ht->nodes);
    ht->nodes = new_nodes;
    ht->capacity = new_capacity;
}

