        node->crcflag = 1;
    } else {
        node->crcflag = 0;
    }
}

void insert_node(HashTable *ht, Node *node) {
    unsigned int index = hash_function(node->rnti, ht->capacity);
    node->next = ht->nodes[index];
    ht->nodes[index] = node;

    if (ht->size >= ht->capacity * 0.75) {
        resize_hash_table(ht);
    }

    set_crcflag(node);
    ++ht->size;
}

Node* find_node(HashTable *ht, unsigned int rnti) {
    unsigned int index = hash_function(rnti, ht->capacity);
    Node *current = ht->nodes[index];

    while (current != NULL) {
        if (current->rnti == rnti) {
            return current;
        }
        current = current->next;
    }

    return NULL;
}

void validate_list(HashTable *ht) {
