void free_node(Node *node) {
    free(node);
}

void free_hash_table(HashTable *ht) {
    for (unsigned int i = 0; i < ht->capacity; ++i) {
        Node *current = ht->nodes[i];
        Node *next;

        while (current != NULL) {
