#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
} ListNode;

typedef struct {
    ListNode** nodes;
    unsigned int capacity;
    unsigned int size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list(unsigned int capacity) {
    DynamicList* list = malloc(sizeof(DynamicList));
    list->capacity = capacity;
    list->size = 0;
    list->nodes = calloc(capacity, sizeof(ListNode*));
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_node(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        printf("Error: List is full.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    ListNode* node = malloc(sizeof(ListNode));
    node->data = data;
    node->next = list->nodes[list->size];
    list->nodes[list->size] = node;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void remove_node(DynamicList* list, unsigned int index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->capacity || index < 0 || list->size == 0) {
        printf("Error: Invalid index.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    ListNode* current = list->nodes[0];
    for (unsigned int i = 0; i < index; ++i) {
        current = current->next;
    }

    ListNode* temp = current->next;
    current->next = temp->next;
    free(temp);
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

void destroy_list(DynamicList* list) {
    pthread_mutex_destroy(&list->lock);
    for (unsigned int i = 0; i < list->capacity; ++i) {
        ListNode* current = list->nodes[i];
        while (current != NULL) {
            ListNode* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(list->nodes);
    free(list);
}
```

