#include <time.h>

typedef struct {
    uint32_t rnti;
    uint8_t crcflag;
    RX_UE_INFORMATION_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next, *prev;
} Node;

static Node **slab = NULL;
static size_t nodes_per_cacheline = 0;
static size_t num_caches = 0;
static size_t max_nodes = 0;
static pthread_mutex_t slab_lock = PTHREAD_MUTEX_INITIALIZER;

void init_slab(size_t nodes) {
    if (slab != NULL) return;

    num_caches = nodes / nodes_per_cacheline + (nodes % nodes_per_cacheline > 0);
    slab = calloc(num_caches, sizeof(Node*));
    max_nodes = nodes;
}

Node *get_node() {
    pthread_mutex_lock(&slab_lock);
    for (size_t i = 0; i < num_caches; ++i) {
        if (slab[i] != NULL) {
            Node *node = slab[i];
            slab[i] = node->next;
            node->next = NULL;
            node->prev = NULL;
            pthread_mutex_unlock(&slab_lock);
            return node;
        }
    }
    pthread_mutex_unlock(&slab_lock);

    size_t new_nodes = max_nodes < nodes_per_cacheline * 2 ? nodes_per_cacheline * 2 : max_nodes * 2;
    Node **new_slab = realloc(slab, sizeof(Node*) * (num_caches + 1));
    if (new_slab == NULL) {
        fprintf(stderr, "Failed to allocate memory for slab\n");
        return NULL;
    }
    slab = new_slab;
    num_caches++;
    slab[num_caches - 1] = calloc(new_nodes, sizeof(Node));

    pthread_mutex_lock(&slab_lock);
    return slab[num_caches - 1];
}

void free_node(Node *node) {
    if (slab == NULL) return;

    pthread_mutex_lock(&slab_lock);
    node->next = slab[0];
    slab[0] = node;
    pthread_mutex_unlock(&slab_lock);
}

void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->crcflag = rand() % 256;
}

// Function to add a new element to the doubly-linked list
void add_to_list(Node **head, Node *new_node) {
    if (*head == NULL) {
        *head = new_node;
        return;
    }

    new_node->next = *head;
    (*head)->prev = new_node;
    *head = new_node;
}

// Function to remove a node from the doubly-linked list
void remove_from_list(Node **head, Node *node) {
    if (node == NULL || *head == NULL) return;

    if (*head == node) {
        *head = (*head)->next;
        if (*head != NULL) (*head)->prev = NULL;
        return;
    }

    Node *current = *head;
    while (current->next != NULL && current->next != node) current = current->next;
    if (current->next == NULL) return;

    current->next = current->next->next;
    if (current->next != NULL) current->next->prev = current;
}

