class NFAPI_CRC_POOL {
public:
    NFAPI_CRC_POOL(size_t maxCapacity) : m_maxCapacity(maxCapacity), m_queue(m_buffer.get(), m_buffer.size()) {}

    int allocate() {
        if (m_free.empty()) {
            if (m_allocated.size() >= 0.75 * m_maxCapacity) {
                resize();
            }
            auto p = new NFAPI_CRC_INDICATION_PDU_T;
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(0, 1);
            p->crcflag = dis(gen);
            m_allocated.emplace_back(p);
        }
        auto it = m_free.front();
        m_free.pop_front();
        new (it) NFAPI_CRC_INDICATION_PDU_T(*m_allocated.back());
        m_allocated.back()->~NFAPI_CRC_INDICATION_PDU_T();
        return it - &m_buffer[0];
    }

    void deallocate(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        new (&m_free.front()) NFAPI_CRC_INDICATION_PDU_T(*pdu);
        m_free.push_back(std::move(m_buffer[pdu - &m_buffer[0]]));
    }

private:
    void resize() {
        auto newSize = m_allocated.size() * 2;
        std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> newBuffer(new NFAPI_CRC_INDICATION_PDU_T[newSize]);
        std::copy(m_allocated.begin(), m_allocated.end(), newBuffer.get());
        m_buffer.swap(newBuffer);
        m_maxCapacity = newSize;
    }

    std::vector<NFAPI_CRC_INDICATION_PDU_T> m_allocated;
    boost::lockfree::singly_linked_list<NFAPI_CRC_INDICATION_PDU_T> m_free, m_queue;
    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> m_buffer;
    size_t m_maxCapacity;
};
