    size_t size;
    transport_block_t* blocks;
    pthread_mutex_t mutex;
} dynamic_array_t;

void init_dynamic_array(dynamic_array_t* array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->size = 0;
    array->blocks = calloc(initial_capacity, sizeof(transport_block_t));
    if (!array->blocks) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->mutex, NULL);
}

void resize_if_needed(dynamic_array_t* array, size_t new_capacity) {
    if (new_capacity > array->capacity && array->size == array->capacity) {
        transport_block_t* new_blocks = realloc(array->blocks, new_capacity * sizeof(transport_block_t));
        if (!new_blocks) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        array->blocks = new_blocks;
        array->capacity = new_capacity;
    }
}

void add_entry(dynamic_array_t* array, const transport_block_t* entry) {
    pthread_mutex_lock(&array->mutex);
    resize_if_needed(array, array->size + 1);
    memcpy(&array->blocks[array->size], entry, sizeof(transport_block_t));
    array->size++;
    pthread_mutex_unlock(&array->mutex);
}

bool remove_entry_by_rnti(dynamic_array_t* array, uint32_t rnti) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->blocks[i].tag.rnti == rnti) {
            memmove(&array->blocks[i], &array->blocks[i + 1], (array->size - i - 1) * sizeof(transport_block_t));
            --array->size;
            pthread_mutex_unlock(&array->mutex);
            return true;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return false;
}

