    struct node* next;
} Node;

Node* generateCRCIndicationList(int N) {
    srand(time(NULL));
    Node *head = NULL, *current = NULL, *temp = NULL;

    for (int i = 0; i < N; ++i) {
        temp = (Node*)malloc(sizeof(Node));
        if (!temp) {
            free_list(head);
            return NULL;
        }

        temp->data.rxUEInfoTag = rand() % UINT32_MAX;
        temp->data.rnti = rand() % UINT16_MAX;
        for (int j = 0; j < 4; ++j) {
            temp->data.crcIndicationRel8Tag[j] = rand() % UINT8_MAX;
        }

        if (!head) {
            head = temp;
            current = head;
        } else {
            current->next = temp;
            current = temp;
        }
    }

    // FSA-based functionality implementation
    int states[] = {0, 1, 2, 3};
    int stateCount = sizeof(states) / sizeof(states[0]);
    int lastState = 3;

    current->next = (Node*)malloc((stateCount + 1) * sizeof(Node));
    if (!current->next) {
        free_list(head);
        return NULL;
    }

    current = current->next;
    for (int i = 0; i <= lastState; ++i) {
        current->data.rxUEInfoTag = states[i];
        current->next = (i < stateCount) ? (current + 1) : NULL;
        current++;
    }

    return head;
}

void free_list(Node *head) {
    Node *current = head;
    while (current != NULL) {
        Node *temp = current->next;
        free(current);
        current = temp;
    }
}
