```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    uint32_t rnti;
    uint8_t crcFlag;
    RX_UE_INFORMATION_TAG tag;
    NFAPI_CRC_INDICATION_PDU_T *next;
} PDU_NODE;

typedef struct {
    int size;
    PDU_NODE *head;
    UE_IDENTIFIER_MANAGER *ueManager; // Pre-existing data structure to manage UE identifiers
} PDU_LIST;

PDU_LIST* pduListCreate(UE_IDENTIFIER_MANAGER *ueManager) {
    PDU_LIST *list = (PDU_LIST *)malloc(sizeof(PDU_LIST));
    if (!list) return NULL;

    list->size = 0;
    list->head = NULL;
    list->ueManager = ueManager;

    return list;
}

bool pduListAdd(PDU_LIST *list, RX_UE_INFORMATION_TAG tag, uint32_t rnti) {
    PDU_NODE *newNode = (PDU_NODE *)malloc(sizeof(PDU_NODE));
    if (!newNode) return false;

    newNode->tag = tag;
    newNode->rnti = rnti;
    newNode->crcFlag = rand() % 2; // Randomly set CRCFLAG

    if (list->size == 0) {
        list->head = newNode;
    } else {
        PDU_NODE *current = list->head;
        while (current->next != NULL) current = current->next;
        current->next = newNode;
    }

    list->size++;

    // Ensure each RX_UE_INFORMATION_TAG is unique within the list
    if (!ueManager->addIdentifier(ueManager, tag)) {
        free(newNode);
        return false;
    }

    return true;
}

void pduListDestroy(PDU_LIST *list) {
    PDU_NODE *current = list->head;
    while (current != NULL) {
        PDU_NODE *temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}
