};

// Custom allocator class for efficient memory management
class CustomAllocator {
public:
    CustomAllocator(size_t blockSize, size_t numBlocks) : _blockSize(blockSize), _numBlocks(numBlocks), _memoryPool(nullptr) {
        _memoryPool = static_cast<char*>(std::malloc(_numBlocks * _blockSize));
        if (_memoryPool == nullptr) {
            throw std::runtime_error("Failed to allocate memory pool");
        }
    }

    ~CustomAllocator() {
        std::free(_memoryPool);
    }

    void* allocate(size_t size, std::size_t numElements) {
        if (numElements > _numBlocks || (_blockSize * _numBlocks - _memoryPool.size()) < numElements * size) {
            throw std::runtime_error("Insufficient memory in the pool");
        }

        auto start = _memoryPool.data() + (_numBlocks - 1) * _blockSize;
        auto result = start + (_numBlocks - 1 - (size_t)(start - _memoryPool.data())) * _blockSize;
        _numBlocks -= numElements;
        return result;
    }

    void deallocate(void* ptr, std::size_t numElements) {
        if (_numBlocks + numElements > _numBlocks) {
            throw std::runtime_error("Cannot deallocate more memory than allocated");
        }

        auto blockSize = static_cast<char*>(ptr) - _memoryPool.data();
        std::memcpy(_memoryPool.data() + (_numBlocks * _blockSize), ptr, numElements * _blockSize);
        _numBlocks += numElements;
    }

private:
    size_t _blockSize;
    size_t _numBlocks;
    std::vector<char> _memoryPool;
};

// Function to dynamically allocate and populate the array of structures
std::vector<NFAPI_CRC_INDICATION_PDU_T> createStructures(size_t numElements, uint32_t minRnti, uint32_t maxRnti) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> distr(minRnti, maxRnti);

    CustomAllocator allocator(sizeof(NFAPI_CRC_INDICATION_PDU_T), numElements);

    std::vector<NFAPI_CRC_INDICATION_PDU_T> structures;
    structures.reserve(numElements);

    for (size_t i = 0; i < numElements; ++i) {
        auto* structurePtr = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(allocator.allocate(1, 1));
        if (!structurePtr) {
            throw std::runtime_error("Failed to allocate memory for a single structure");
        }

        structurePtr->rnti = distr(gen);
        structurePtr->crcIndication.crcFlag = rand() % 2; // Randomly set CRCFLAG

        structures.push_back(*structurePtr);
        allocator.deallocate(structurePtr, 1);
    }

    return structures;
}
