        free_list(&head);
        return NULL;
    }

    current = head;
    while (current->prev) {
        current = current->prev;
    }

    return head;
}

void free_list(Node** head_ref) {
    Node* current = *head_ref;
    Node* next;

    while (current != NULL) {
