public class ThemeHasher {
    private static final String DEFAULT_THEME_DIR = "themes";
    private static final MessageDigest MD5;
    private final File cacheRoot;
    private final Map<String, byte[]> themeCache;

    static {
        try {
            MD5 = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public ThemeHasher() throws IOException {
        cacheRoot = FileUtils.getUserDirectory().toFile().resolve(DEFAULT_THEME_DIR);
        if (!cacheRoot.exists()) {
            cacheRoot.mkdirs();
        }
        themeCache = new HashMap<>();
    }

    public byte[] hashTheme(File themeFile) throws IOException {
        try (InputStream inputStream = Files.newInputStream(themeFile.toPath())) {
            return MessageDigest.digest(inputStream);
        }
    }

    public void cacheTheme(String key, File themeFile) throws IOException {
        byte[] hash = hashTheme(themeFile);
        themeCache.put(key, hash);
        try (BufferedImage image = ImageIO.read(themeFile)) {
            // Recycle the image to free up resources
            ImageIO.write(image, "png", FileUtils.toByteArray(themeFile));
        }
    }

    public byte[] getTheme(String key) {
        return themeCache.getOrDefault(key, null);
    }

    // Add methods for batch processing and asynchronous updates here
}
```

