    static std::unique_ptr<T> fromJson(const Json::Value& json) {
        auto it = dynamic_cast<T*>(json.getPointer(json["_class"].asCString()));
        if (!it) {
            syslog(LOG_ERR, "Invalid JSON format: %s", json.toStyledString().c_str());
            return nullptr;
