    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void read_integers(int *numbers, int *n) {
    int number;
    for (int i = 0; i < INT_MAX; ++i) {
        if (scanf("%d", &number) != 1) break;
        numbers[*n] = number;
        (*n)++;
    }
}

void find_largest(const int *numbers, int n, int *largest) {
    *largest = numbers[0];
    for (int i = 1; i < n; ++i) {
        if (numbers[i] > *largest) {
            *largest = numbers[i];
        }
    }
}

void init_struct(NFAPI_CRC_INDICATION_PDU_T *pdu, int rnti, int largest) {
    pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG_VALID;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag.crcflag = rand() % 2;
    pdu->crc_indication_rel8_tag.crc = largest;
}

